window.PRACTICAL_PAST = [
{"id": "sk-cc-43-01", "topic": "第 43 次（93.11.21）", "code": "43-01", "n": 43, "q": "依勞工安全衛生教育訓練規則規定，那些人員應分別施以從事工作及預防災害所必要之安全衛生教育訓練?(10分)", "ans": "", "sol": "1、勞工安全衛生人員。\n2、作業環境測定人員。\n3、施工安全評估人員及製程安全評估人員。\n4、安全衛生相關作業主管。\n5、危險性機械、設備操作人員。\n6、特殊作業人員。\n7、一般作業人員。\n8、其他經中央主管機關指定之人員。", "old": 1},
{"id": "sk-cc-43-02", "topic": "第 43 次（93.11.21）", "code": "43-02", "n": 43, "q": "依勞工安全衛生設施規則規定，使用之移動梯應符合那些規定？(10分)", "ans": "", "sol": "1、具有堅固之構造。\n2、其材質不得有顯著之損傷、腐蝕等現象。\n3、寬度應在三十公分以上。\n4、應採取防止滑溜或其他防止轉動之必要措施。", "old": 1},
{"id": "sk-cc-43-03", "topic": "第 43 次（93.11.21）", "code": "43-03", "n": 43, "q": "依勞工安全衛生組織管理及自動檢查辦法規定，事業單位以其事業之全部或部分交付承攬或再承攬時，如該承攬人使用之機械、設備或器具係由原事業單位提供者，該機械、設備或器具之定期撿查及重點檢查等自動檢查，應如何實施?(10分)", "ans": "", "sol": "1.事業單位以其事業之全部或部分交付承攬或再承攬時，如該承攬人使用之機械、設備或器具係由原事業單位提供者，該機械、設備或器具應由原事業單位實施定期檢查及重點檢查。\n2.上述定期檢查及重點檢查於有必要時得由承攬人或再承攬人會同實施。\n3.上述定期檢查及重點檢查如承攬人或再承攬人具有實施之能力時，得以書面約定由承攬人或再承攬人為之。", "old": 1},
{"id": "sk-cc-43-04", "topic": "第 43 次（93.11.21）", "code": "43-04", "n": 43, "q": "為防止勞工因不安全行為致使勞工遭受傷害而實施之安全觀察，應觀察那些作業?(10 分)", "ans": "", "sol": "1、傷害頻率高的作業\n2、傷害嚴重率高的作業\n3、曾發生事故的作業\n4、具潛在嚴重危害性的作業\n5、臨時性或非經常性的作業\n6、新作業\n7、經常性但非生產性的作業"},
{"id": "sk-cc-43-05", "topic": "第 43 次（93.11.21）", "code": "43-05", "n": 43, "q": "試解釋下列名詞：\n(一)著火點（Fire Point） (5 分)\n(二)燃燒界限(範圍)（Flammable Limit）。(5 分)", "ans": "", "sol": "（一）引火性物質表面蒸發作用釋出的蒸氣，在空氣中擴散成為可燃的混合氣體，其濃度相當爆炸下限，此時液體之最低溫度稱為閃火點。此時，如繼續加熱使其液溫繼續以一定速率上升，如使其所產生之蒸氣與空氣混合氣，足以持續燃燒，而使火焰不再熄滅時之最低溫度，即為其著火點。\n（二）係指可燃性氣體或引火性液體之蒸氣，與空氣混合後遇到火源可以燃燒的最高之體積百分比，其範圍謂之燃燒界限(範圍)。"},
{"id": "sk-cc-43-06", "topic": "第 43 次（93.11.21）", "code": "43-06", "n": 43, "q": "請說明鍋爐操作人員於操作過程中應注意事項?(10 分)。", "ans": "", "sol": "1、監視壓力、水位、燃燒狀態等運轉狀態，並確認安全閥、壓力表及其他安全裝置無異狀。\n2、避免急劇負荷變動之現象。\n3、保持汽壓在最高使用壓力以下。\n4、保持安全閥之功能正常。\n5、每日檢點水位測定裝置之功能一次以上。\n6、適當沖放鍋爐水，確保鍋爐水質。\n7、保持給水裝置功能正常。\n8、檢點及調整低水位燃燒遮斷裝置、火焰檢出裝置及其他自動控制裝置，以保持功能正常。\n9、以上各款發現有異狀時，應即採取適當措施。\n註：本題出自「鍋爐及壓力容器安全規則第二十二條」係屬勞工安全管理師43小時課程內"},
{"id": "sk-cc-43-07", "topic": "第 43 次（93.11.21）", "code": "43-07", "n": 43, "q": "請說明選擇安全帽應注意事項。(10分)", "ans": "", "sol": "1.適用於作業性質\n2.經檢驗合格\n3.適合頭部形狀\n4.重量要輕"},
{"id": "sk-cc-43-08", "topic": "第 43 次（93.11.21）", "code": "43-08", "n": 43, "q": "某勞工工作日暴露於甲苯之濃度及時間如下表：\n試問：\n(一)工作日時量平均濃度為多少ppm?(5 分)。\n(二)相當八小時日時量平均濃度多少ppm?(5分)。", "ans": "", "sol": "(一)（2×80＋2×110＋2×100＋3×90）÷9＝94.44 (ppm)\n(二) 94.44ppm × 9/8＝106.25ppm", "fig": "| 時間 | 08：00－10：00 | 10：00－12：00 | 13：00－15：00 | 15：00－18：00 |\n| --- | --- | --- | --- | --- |\n| 濃度 | 80PPM | 110PPM | 100PPM | 90PPM |"},
{"id": "sk-cc-43-09", "topic": "第 43 次（93.11.21）", "code": "43-09", "n": 43, "q": "如何預防游離輻射之危害?(10分)", "ans": "", "sol": "1.游離輻射危害可用「時間」、「距離」、「屏蔽」三原則來預防，時間係指儘量減少暴露時間，距離係指儘量遠離輻射源，屏蔽則係指必要時用含鉛之屏障阻隔輻射線。\n2.加強作業人員進出及作業中於游離輻射場所之安全管理。\n3.應依規定實施作業人員之特殊健康檢查。"},
{"id": "sk-cc-43-10", "topic": "第 43 次（93.11.21）", "code": "43-10", "n": 43, "q": "請由參考答案攔中選出與下列作業或危害因子有關之最主要的一種疾病，將其代號填入括號內(即A、B、C‥．):(10分)", "ans": "", "sol": "1．振動作業 ( C )\n2．紅外線 ( D )\n3．異常氣壓作業( B )\n4，錳( G )\n5，二異氰酸甲苯 (TDI )( H )", "fig": "參考答案：\n|  |  |\n| --- | --- |\n| A | 聽力損失 |\n| B | 潛涵病 |\n| C | 白手病 |\n| D | 白內障 |\n| E | 凍傷 |\n| F | 貧血 |\n| G | 巴金森氏病 |\n| H | 過敏性氣喘 |\n| I | 肝腫瘤 |\n| J | 腎衰竭 |"},
{"id": "sk-cc-44-01", "topic": "第 44 次（94.3.27）", "code": "44-01", "n": 44, "q": "依據勞工安全衛生法令，事業單位以其事業之全部或一部分交付承攬時，應對承攬人予以告知，其告知時機為何?告知事項為何?告知方式為何?(10 分)", "ans": "", "sol": "1、告知時機：事前告知。\n2、告知事項：有關其事業工作環境、危害因素、勞工安全衛生法及有關安全衛生規定應採取之措施。\n3、告知方式：應以書面為之，或召開協商會議並作成紀錄。", "old": 1},
{"id": "sk-cc-44-02", "topic": "第 44 次（94.3.27）", "code": "44-02", "n": 44, "q": "依據勞工安全衛生法令，解釋下列名詞：(10分)\n(一)職業災害\n(二)工作場所\n(三)共同作業\n(四)工作場所負責人\n(五)雇主", "ans": "", "sol": "1、職業災害：勞工就業場所之建築物、設備、原料、材料、化學物品、氣體、蒸氣、粉塵等或作業活動及其他職業上原因引起之勞工疾病、傷害、殘廢或死亡。\n2、工作場所：係指就業場所中，接受雇主或代理雇主指示處理有關勞工事務之人所能支配、管理之場所。\n3、共同作業：係指事業單位與承攬人、再承攬人所僱用之勞工於同一期間、同一工作場所從事工作。\n4、工作場所負責人：係指於該工作場所中代表雇主從事管理、指揮或監督勞工從事工作之人。\n5、雇主：事業主或事業之經營負責人。", "old": 1},
{"id": "sk-cc-44-03", "topic": "第 44 次（94.3.27）", "code": "44-03", "n": 44, "q": "依據勞工安全衛生設施規則，對於毒性高壓氣體之儲存及使用，應依那些規定辦理 (10分)", "ans": "", "sol": "(一)雇主對於毒性高壓氣體之儲存，應依下列規定辦理：\n1.貯存處要置備吸收劑、中和劑及適用之防毒面罩或呼吸用防護具。\n2.具有腐蝕性之毒性氣體，應充分換氣，保持通風良好。\n3.不得在腐蝕化學藥品或煙囪附近貯藏。\n4.預防異物之混入。\n(二)雇主對於毒性高壓氣體之使用，應依下列規定辦理：\n1.非對該氣體有實地瞭解之人員，不准進入。\n2.工作場所空氣中之毒性氣體濃度不得超過容許濃度。\n3.工作場所置備充分及適用之防護具。\n4.使用毒性氣體場所，應保持通風良好。", "old": 1},
{"id": "sk-cc-44-04", "topic": "第 44 次（94.3.27）", "code": "44-04", "n": 44, "q": "室內作業場所機械設備所發生之噪音超過九十分貝時，依據勞工安全衛生法令，事業單位應、採取那些措施以預防噪音危害勞工健康? (10分)", "ans": "", "sol": "（一）工程改善\n(1)設置吸音板等吸音設備，減低反射音波。\n(2)變更製程，設備，採用低噪音機械及材料。\n(3)設隔音罩、隔音牆等隔離噪音。\n(4)消除機械鬆動現象。\n(5)減少物料之摩擦、衝擊。\n(6)降低流體流速或加裝消音設備。\n(7)減少對振動面之作用力，並減小振動面積。\n（二）行政管理\n(1)定期實施聽力圖檢查，可及早發現聽力是否受影響。\n(2)控制勞工於高噪音場所暴露時間。\n(3)正確配戴耳塞、耳罩等防音防護具。", "old": 1},
{"id": "sk-cc-44-05", "topic": "第 44 次（94.3.27）", "code": "44-05", "n": 44, "q": "試說明安全作業標準之功用。(10分)", "ans": "", "sol": "1、防範工作場所災害發生。\n2、確定工作場所所需設備或器具。\n3、選擇適當的人員工作。\n4、作為安全教導參考。\n5、作為安全觀察參考。\n6、作為事故調查參考。\n7、增進工作人員之參與感。"},
{"id": "sk-cc-44-06", "topic": "第 44 次（94.3.27）", "code": "44-06", "n": 44, "q": "王君每日八小時的工作時間內，於 A 場所工作二小時、B場所工作三小時、C場所工作三小時，甲物質八小時日時量平均容許濃度為 100PPM、乙物質為 150PPM、丙物質為200PPM。請以相加效應評估王君之暴露是否合於勞工安全衛生法令規定？(10分)", "ans": "", "sol": "甲物質：（2×50）÷8＝12.5 ppm\n乙物質：（2×60＋3×90）÷8＝48.75 ppm\n丙物質：（3×50＋3×100）÷8＝56.25 ppm\n計算如下：（12.5÷100）＋（48.75÷150）＋（56.25÷200）＝0.73\n其和小於１，王君之暴露未超出容許濃度，故合於勞工安全衛生法令規定。", "fig": "| 工作地點有害物 | A | B | C |\n| --- | --- | --- | --- |\n| 甲 | 50ppm | 0 | 0 |\n| 乙 | 60 ppm | 90 ppm | 0 |\n| 丙 | 0 | 50 ppm | 100 ppm |", "old": 1},
{"id": "sk-cc-44-07", "topic": "第 44 次（94.3.27）", "code": "44-07", "n": 44, "q": "事業單位推動危害通識制度，應採取那些措施。(10分)", "ans": "", "sol": "1.編撰危害通識計畫書。\n2.製備危害物清單。\n3.標示危害物質。\n4.提供物質安全資料表。\n5.辦理勞工危害通識教育訓練"},
{"id": "sk-cc-44-08", "topic": "第 44 次（94.3.27）", "code": "44-08", "n": 44, "q": "(一)請略述電路短路事故的原因。(5 分)\n(二)請說明過電流的原因有那三類？(5 分)", "ans": "", "sol": "(一)短路事故的原因：\n1.電纜、電線絕緣物自然劣化。\n2.變壓器、電動機等電氣設備裝置製造不良。\n3.礙子自然劣化或製造不良。\n4.電纜施工不良或絕緣物自然劣化。\n(二)過電流的原因：\n1.因短路而發生過電流：電路中因為不正確的連接方式或設備零件的故障，引起電路短路所釋放出的過電流。\n2.因接地不良而發生過電流：如果沒有良好之設備接地，因故障迴路阻抗較大，使故障電流過小而無法及時啟動過電流保護裝置而使設備受損，在故障迴路中的高阻抗點可能會發生火花而導致火災或爆炸。\n3.因過載而發生過電流：因電氣設備、電線過載超過電流而過熱，而引起火花放電或短路，引起發生電氣火災。"},
{"id": "sk-cc-44-09", "topic": "第 44 次（94.3.27）", "code": "44-09", "n": 44, "q": "請說明鍋爐操作人員於操作過程中應注意事項？(10分)。", "ans": "", "sol": "1、監視壓力、水位、燃燒狀態等運轉狀態，並確認安全閥、壓力表及其他安全裝置無異狀。\n2、避免急劇負荷變動之現象。\n3、保持汽壓在最高使用壓力以下。\n4、保持安全閥之功能正常。\n5、每日檢點水位測定裝置之功能一次以上。\n6、適當沖放鍋爐水，確保鍋爐水質。\n7、保持給水裝置功能正常。\n8、檢點及調整低水位燃燒遮斷裝置、火焰檢出裝置及其他自動控制裝置，以保持功能正常。\n9、以上各款發現有異狀時，應即採取適當措施。"},
{"id": "sk-cc-44-10", "topic": "第 44 次（94.3.27）", "code": "44-10", "n": 44, "q": "空氣在風管內流動會產生摩擦損失及擾動損失。請問：在計算局部排氣裝置壓力損失時，那些損失屬於摩擦損失?那些損失屬於擾動損失？(10分)。", "ans": "", "sol": "(一)風管內流動所產生摩擦損失如下：\n1.風管長度成正比。\n2.風管直徑大小成反比。\n3.流速平方成正比。\n(二)風管內流動所產生擾動損失如下：\n1.彎管之壓力損失。\n2.縮管、擴管之壓力損失。\n3合流管之壓力損失。\n4.排氣口之壓力損失。\n5.進入氣罩壓力損失。\n6.通過空氣清淨裝置之壓力損失。"},
{"id": "sk-cc-45-01", "topic": "第 45 次（94.6.26）", "code": "45-01", "n": 45, "q": "依勞動檢查法令規定，經指定丁類工作場所之營造工程工作場所範圍為何?請說明之。(10分)", "ans": "", "sol": "係指下列範圍之營造工程：\n1.建築物頂樓樓板高度在五十公尺以上之建築工程。\n2.橋墩中心與橋墩中心之距離在五十公尺以上之橋樑工程。\n3.採用壓氣施工作業之工程。\n4.長度一千公尺以上或需開挖十五公尺以上之豎坑之隧道工程。\n5.開挖深度達十五公尺以上或地下室為四層樓以上，且開挖面積達五百平方公尺之工程。\n6.工程中模板支撐高度七公尺以上、面積達一百平方公尺以上且佔該層模板支撐面積百分之六十以上者。\n7.其他經中央主管機關指定公告者。"},
{"id": "sk-cc-45-02", "topic": "第 45 次（94.6.26）", "code": "45-02", "n": 45, "q": "事業單位推動危害通識制度，應採取那些措施?(10 分)", "ans": "", "sol": "1、編撰危害通識計畫書：\n2、製備危害物清單：\n3、標示危害物質：\n4、提供物質安全資料表：\n5、辦理勞工危害通識教育訓練："},
{"id": "sk-cc-45-03", "topic": "第 45 次（94.6.26）", "code": "45-03", "n": 45, "q": "事業單位將其專業之一部分交付承攬時，\n(一)事前告知應包括那些事項?(3分)\n(二)原事業單位與承攬人分別僱用勞工共同作業時，依法應對那些作業管制進行協議?(7分)", "ans": "", "sol": "(一) 有關其事業工作環境、危害因素、勞工安全衛生法及有關安全衛生規定應採取之措施。\n(二)\n1、從事動火、高架、開挖、爆破、高壓電活線等危險作業之管制。\n2、對進入密閉空間、有害物質作業等作業環境之作業管制。\n3、電氣機具入廠管制。\n4、作業人員進場管制。", "old": 1},
{"id": "sk-cc-45-04", "topic": "第 45 次（94.6.26）", "code": "45-04", "n": 45, "q": "雇主使勞工於局限空間從事作業，事前推測局限空聞內可能有缺氧、沼氣、中毒及爆炸火災等危害之虞，應訂定危害防止計畫，請試述該危害防止計畫應包括之事項?(10分)", "ans": "", "sol": "局限空間危害防止計畫應依作業可能引起之危害訂定下列事項：\n1.局限空間內危害之確認。\n2.通風換氣實施方式。\n3.局限空間內氧氣、危險物、有害物濃度之測定。\n4.電能、高溫、低溫及危害物質之隔離措施及缺氧、中毒、感電、塌陷、被夾、被捲等危害防止措施。\n5.作業方法及安全管制作法。\n6.進入作業許可程序。\n7.提供之防護設備之檢點及維護方法。\n8.作業控制設施及作業安全檢點方法。\n9.緊急應變處置措施。"},
{"id": "sk-cc-45-05", "topic": "第 45 次（94.6.26）", "code": "45-05", "n": 45, "q": "靜電火花是工廠火災爆炸主要危害源之一，請簡述五種預防靜電危害之方法。(10分)。", "ans": "", "sol": "1、抑制靜電產生。\n2、接地：（1）導體部分接地（2）移動性容器及裝置接地（3）轉動部分接地（4）橡皮管噴嘴接地。\n3、使用導電性之材料。\n4、加濕。\n5、游離化。"},
{"id": "sk-cc-45-06", "topic": "第 45 次（94.6.26）", "code": "45-06", "n": 45, "q": "使用移動式施工架從事作業，為預防人員發生墜落災害，其作業安全應注意事項為何?(10分)", "ans": "", "sol": "1、應設置昇降用梯或其他安全上下之設備。\n2、細長形施工架應設置控索。\n3、在作業中施工架應予固定，不能搖動。\n4、施工架移動時，先要認清地面狀況及確認有無障礙物。\n5、施工架上有作業人員時，不得移動。"},
{"id": "sk-cc-45-07", "topic": "第 45 次（94.6.26）", "code": "45-07", "n": 45, "q": "從事挖掘公路施工作業之工作場所，為防止車輛突入等引起之危害，依勞工安全衛生法令規定，就交通維持、人員服裝、車輛出入等應辦理事項為何?請說明之。。(10分)", "ans": "", "sol": "1.從事挖掘公路施工作業，應依所在地直轄市、縣（市）政府審查同意之交通維持計畫，設置交通管制設施。\n2.作業人員應戴安全帽、穿著顏色鮮明之施工背心，於夜間作業時，安全帽、施工背心應有反光帶以利辨識。\n3.與作業無關之車輛禁止停入作業場所。但作業中必須使用之待用車輛，其駕駛常駐作業場所者，不在此限。\n4.使用道路作業之工作場所，應於車流方向後面設置車輛出入口。但依周遭狀況設置有困難者，得於平行車流處設置車輛出入口，並置交通引導人員，使一般車輛優先通行，不得造成大眾通行之障礙。", "old": 1},
{"id": "sk-cc-45-08", "topic": "第 45 次（94.6.26）", "code": "45-08", "n": 45, "q": "(一)依勞工健康保護規則規定，雇主對在職勞工，應依何種期限，定期賞施一般健康檢查?(3分)\n(二)勞工安全衛生法規定之特別危害健康之作業有那些，請列出七種。(7分)。", "ans": "", "sol": "(一) 1.年滿六十五歲以上者，每年檢查一次。\n2.年滿四十歲以上未滿六十五歲者，每三年檢查一次。\n3.未滿四十歲者，每五年檢查一次。\n(二)\n1、高溫作業。\n2、噪音作業。\n3、游離輻射作業。\n4、異常氣壓作業。\n5、鉛作業。\n6、四烷基鉛作業。\n7、粉塵作業。", "old": 1},
{"id": "sk-cc-45-09", "topic": "第 45 次（94.6.26）", "code": "45-09", "n": 45, "q": "試述我國勞工作業環境空氣中有害物容許濃度標準對於勞工之暴露濃度如何規定?(6分)如有兩種以上有害物同時存在時應如何評估？(4 分)。", "ans": "", "sol": "（一）勞工作業環境空氣中有害物之濃度應符合下列規定：\n1.全程工作日之時量平均濃度不得超過相當「八小時日時量平均容許濃度」。\n2.任何一次連續十五分鐘內之平均濃度不得超過「短時間時量平均容許濃度」。\n3.任何時間均不得超過「最高容許濃度」。\n（二）依據勞工作業環境空氣中有害物容許濃度標準規定作業環境空氣中有二種以上有害物存在而其相互間效應非屬於相乘效應或獨立效應時應視為相加效應，其計算方法如下：\n甲有害物成分之濃度/甲有害物成分之容許濃度 ＋ 乙有害物成分之濃度/乙有害物成分之容許濃度 ＋ 丙有害物成分之濃度/丙有害物成分之容許濃度 …… ＜／＝／＞ １\n其和大於１時，即屬超出容許濃度。"},
{"id": "sk-cc-45-10", "topic": "第 45 次（94.6.26）", "code": "45-10", "n": 45, "q": "王君從事有機溶劑作業，在某工作日內暴露最嚴重時段測定十五分鐘，測定結果如下表(25°C，一大氣壓下)。設該場所除二甲苯、丁酮及正已烷外無其他有害物之暴露，若以相加效應評估時，該勞工暴露是否符合勞工作業環境空氣中有害物容許濃度標準規定?\n(10分)。", "ans": "", "sol": "二甲苯：200mg / M3＝（200×24.45）÷106＝46.13ppm\n丁酮：250mg / M3＝（250×24.45）÷72＝84.9ppm\n正己烷：100mg / M3＝（100×24.45）÷86＝28.43ppm\n二甲苯短時間時量平均容許濃度為：100×1.25＝125（ppm）\n丁酮短時間時量平均容許濃度為：200×1.25＝250（ppm）\n正已烷短時間時量平均容許濃度為：50×15＝75（ppm）計算如下：\n（46.1÷125）＋（84.9÷250）＋（28.4÷75）＝1.087＞1\n其和大於1超出容許濃度之規定。", "fig": "| 暴露物質 | 二甲苯 | 丁酮 | 正己烷 |\n| --- | --- | --- | --- |\n| 暴露濃度 | 200mg / M3 | 250mg / M3 | 100mg / M3 |\n| 八小時日時量平均容許濃度 | 100PPM | 200PPM | 50PPM |\n| 變量係數 | 1.25 | 1.25 | 1.5 |\n| 分子量 | 106 | 72 | 86 |"},
{"id": "sk-cc-46-01", "topic": "第 46 次（94.11.20）", "code": "46-01", "n": 46, "q": "依勞工安全衛生設施規則規定，雇主使勞工於局限空間從事作業，有危害勞工之虞時，應於作業場所入口顯而易見處公告注意事項，使作業勞工周知，請敘述所稱注意事項為何？(10 分)", "ans": "", "sol": "依照勞工安全衛生設施規則第二十九條之二規定：\n雇主應於作業場所入口顯而易見處公告下列五項注意事項：\n1.作業有可能引起缺氧等危害時，應經許可始得進入之重要性。\n2.進入該場所時應採取之措施。\n3.事故發生時之緊急措施及緊急聯絡方式。\n4.現場監視人員姓名。\n5.其他作業安全應注意事項。", "old": 1},
{"id": "sk-cc-46-02", "topic": "第 46 次（94.11.20）", "code": "46-02", "n": 46, "q": "依勞工健康保護規則規定，雇主使勞工從事粉塵作業外之特別危害健康作業時，應建立健康管理資料，分級實施健康管理。請回答下列問題：\n(一)如何分級？(5 分)\n(二)如何實施健康管理？(5 分)", "ans": "", "sol": "(一)依照勞工健康保護規則第 15 條規定：\n雇主使勞工從事粉塵作業外之特別危害健康作業時，應建立健康管理資料，並依下列規定分級實施健康管理：\n第一級管理：特殊健康檢查或健康追蹤檢查結果，全部項目正常，或部分項目異常，但經醫師綜合判定為無異常者。\n第二級管理：特殊健康檢查或健康追蹤檢查結果，部分或全部項目異常，經醫師綜合判定為異常，但可能與職業原因無關者。\n第三級管理：特殊健康檢查或健康追蹤檢查結果，部分或全部項目異常，經醫師綜合判定為異常，且可能與職業原因有關者。\n第四級管理：特殊健康檢查或健康追蹤檢查結果，部分或全部項目異常，經醫師綜合判定為異常，且與職業原因有關者。\n(二) 依照勞工健康保護規則第 19 條規定：\n雇主對依第十五條規定列入第二級管理之勞工，得使其依醫師之意見於一定期間內實施健康追蹤檢查；列入第三級管理以上之勞工，應至聘有職業醫學科專科醫師開設門診之指定醫療機構實施診治。並應將處理及醫療情形予以記錄，並保存十年以上。但游離輻射作業等作業之勞工，其紀錄應保存三十年。"},
{"id": "sk-cc-46-03", "topic": "第 46 次（94.11.20）", "code": "46-03", "n": 46, "q": "依營造安全衛生設施標準規定，雇主使勞工於屋頂作業，應辦理事項為何？\n(10 分)", "ans": "", "sol": "一、依營造安全衛生設施標準第 18 條規定：雇主使勞工於屋頂作業，應辦理下列事項：\n1.因屋頂斜度、屋面性質或天候等致使勞工有墜落之虞者，應採取適當安全措施。\n2.於斜度大於三十四度（高低比為二比三）或滑溜之屋頂上從事工作者，應設置適當之護欄，支承穩妥且寬度在四十公分以上之適當工作臺及數量充分、安裝牢穩之適當梯子、麻布梯或爬行板。如不能設置護欄者，應供給並使勞工佩掛安全帶，並掛置於堅固錨錠、可供鉤掛之物件或安全母索等裝置上。\n二、另營造安全衛生設施標準第 19 條亦有下列規定：雇主對於高度二公尺以上之屋頂作業，勞工有遭受墜落危險之虞者，應於該處設置護欄、護蓋或安全網等防護設備。\n三、而對於高度二公尺以上之工作場所（包括屋頂作業），勞工作業有墜落之虞者，依營造安全衛生設施標準第 17 條規定：雇主應依下列規定訂定墜落災害防止計畫，採取適當墜落災害防止設施：\n1.經由設計或工法之選擇，儘量使勞工於地面完成作業以減少高處作業項目。\n2.經由施工程序之變更，優先施作永久構造物之上下昇降設備或防墜設施。\n3.設置護欄、護蓋。\n4.張掛安全網。\n5.使勞工佩掛安全帶。\n6.設置警示線系統。\n7.限制作業人員進入管制區。\n8.對於因開放邊線、組模作業、收尾作業等及採取第一款至第五款規定之設施致增加其作業危險者，應訂定保護計畫並實施。"},
{"id": "sk-cc-46-04", "topic": "第 46 次（94.11.20）", "code": "46-04", "n": 46, "q": "擬定職業災害防止計畫的方法，依其編製程序(順序)可以分成那些過程？\n(10 分)", "ans": "", "sol": "(一)擬具基本方針及計畫目標草案共同會商勞工安全衛生管理單位或勞工安全衛生人員於每一年度開始（或新工程正式開工前）之前二個月即應請各有關部門對實際之安全衛生問題加以檢討，提出檢討報告，同時由勞工安全衛生人員對各部門之安全衛生管理活動狀況，以及管理組織、管理規章等加以檢點，掌握安全衛生之具體問題重點，擬訂次年度應予改善或新工程應訂定之對策，並根據事業經營負責人之指示擬具次年度職業災害防止計畫之基本方針及計畫目標草案，陳請經營負責人邀集各有關部門主管共同會商決定。如在此會議對基本方針及計畫目標不能決定，亦可延至下次會商時再予決定。\n(二)分工研擬計畫各項內容勞工安全衛生管理單位或勞工安全衛生人員應請各部門主管依據會商決定之次年度應予改善或新工程應予訂定之對策、職業災害防止計畫之基本方針、計畫目標(或草案)等草擬各該部門之職業災害防止計畫之計畫項目、實施細目、實施要領、實施單位及人員，預定工作進度、需用經費等，送由勞工安全衛生管理單位或勞工安全衛生人員彙整為整體計畫草案。\n(三)會商討論定案勞工安全衛生管理單位或勞工安全衛生人員將整體職業災害防止計畫彙整完竣後，應請經營負責人邀請各有關部門主管會商討論予以定案，如基本方針及計畫目標在上次會議尚未決定者，亦應擬本次會議同時予以定案。\n(四)細部計畫編擬核定實施職業災害防止計畫定案後，應由各負責實施單位及人員就其負責辦理之實施細目訂定具體的細部實施計畫，陳請上級主管核定後付諸實施。", "old": 1},
{"id": "sk-cc-46-05", "topic": "第 46 次（94.11.20）", "code": "46-05", "n": 46, "q": "車架固定有一內容積 10 立方公尺容器之槽車，灌裝有比重 0.67 之液氨 2500公斤，請分別就下列敘述簡答:(10 分)\n(一)該容器依「危險物及有害物通識規則」規定，應標示之圖式為何？請書明該圖式之危害性之分類。(2 分)\n(二)使用該容器應先取得何種危險性設備檢查合格證明？自構造檢查合格日起算 20 年以上者，每幾年應檢查一次？(2 分)\n(三)該容器依「高壓氣體勞工安全規則」規定之儲存能力為若干？(請列出計算式， 2 分)\n(四)該容器在管理分類上，應至少再灌裝多少公斤才屬灌氣容器？(請列出計算式，2 分)\n(五)該容器於灌裝液氨時，其處理設備之外面至處理煙火設備，應保持多少公尺以上距離？(2 分)", "ans": "", "sol": "(一)該容器依「危險物及有害物通識規則」規定，應標示之圖式及危害性之分類：\n(二) 使用該容器應先取得危險性設備定期檢查合格證明；自構造檢查合格日起算 20 年以上者，每年應檢查一次。\n(三) 依「高壓氣體勞工安全規則」第 18 條規定該容器之儲存能力為：\nW＝0.9wV₂＝0.9×0.67×10000＝6030kg\n(四) 依「高壓氣體勞工安全規則」第 8 條規定：灌氣容器，係指灌裝有高壓氣體之容器，而該氣體之質量在灌裝時質量之二分之一以上者。故以上述計算結果該容器之儲存能力為 6030kg，其二分之一即為3015kg。目前已裝 2500kg,所以應至少再灌裝 3015-2500＝515 公斤以上才屬灌氣容器。\n(五) 依高壓氣體勞工安全規則第 33 條規定：須 8 公尺以上。", "fig": "圖式：紅底菱形，上方為黑色火焰，下方文字依序為「易燃氣體」、「FLAMMABLE GAS」、「2」。"},
{"id": "sk-cc-46-06", "topic": "第 46 次（94.11.20）", "code": "46-06", "n": 46, "q": "電氣作業時需採取適當安全措施，請說明停電作業時的安全措施為何？\n(10 分)", "ans": "", "sol": "1.切斷開關停電之前應先連絡 o\n2.開關切開後應揭立必要的標誌，必要時並將開關加鎖(鑰匙由作業人員保管)，必要時應再派人監視 o\n3.停電後工作之前，必須確實檢查有無充電，並裝設短路接地線。\n4.裝有電力電纜及電力電容器線路，停電後有殘留電荷，應先送電，實施方法為開關切開二分鐘後予以短路，短路五分鐘後始可開始工作。\n5.作業終了恢復送電之前應確實檢查作業人員均離開線路後始可送電。"},
{"id": "sk-cc-46-07", "topic": "第 46 次（94.11.20）", "code": "46-07", "n": 46, "q": "一般而言，要判定為職業疾病，至少必須要滿足的條件有那些？(10 分)", "ans": "", "sol": "1、勞工確實有病徵，且工作場所中有害因子應確實存在。\n2、必須曾暴露於存在有害因子之環境。\n3、發病期間與症狀及有害因子之暴露期間有時序之關係。\n4、病因不屬於非職業上之因素所引起。\n5、文獻上曾記載症狀與危害因子之關係（但極少數新形成之職業病例外）。"},
{"id": "sk-cc-46-08", "topic": "第 46 次（94.11.20）", "code": "46-08", "n": 46, "q": "請回答下列問題:\n(一)依勞工作業環境空氣中有害物容許濃度標準所稱之第一種、第二種、第三種、第四種粉塵分別為何？(5 分)\n(二)何謂綜合溫度熱指數(WBGT)？並列出計算方法。(5 分)", "ans": "", "sol": "(一)1.第一種粉塵：含游離二氧化矽 10％以上之礦物性粉塵。\n2.第二種粉塵：未滿 10％游離二氧化矽之礦物性粉塵。\n3.第三種粉塵：石綿纖維。\n4.第四種粉塵：厭惡性粉塵。\n(二)1.WBGT：係為綜合溫度熱指數為我國在高溫作業勞工作息時間標準、勞工作業環境測定實施辦法作為評估高溫作業之指標，單位為°C。\n2.戶內或戶外無日曬時：WBGT＝0.7×Tnwb＋0.3×Tgb\n戶外有日曬時：WBGT＝0.7×Tnwb＋0.2×Tgb＋0.1×Tdb"},
{"id": "sk-cc-46-09", "topic": "第 46 次（94.11.20）", "code": "46-09", "n": 46, "q": "某一作業場所勞工暴露於噪音之時間為下午 14 時至 16 時，以噪音劑量計測定結果為 50％，則該噪音作業時段之噪音音壓級為多少分貝？(5 分)如該日該勞工無其他時段有噪音暴露時，則該勞工噪音暴露之八小時日時量平均音壓級為何？(5 分)(註：log2＝0.30，log3＝0.48，log5＝0.70，log7＝0.85)", "ans": "", "sol": "(一)D=50%＝0.5\nD＝t₁/T₁＋t₂/T₂＋t₃/T₃＋.....t_{n}/T_{n}＝t₁/T₁\n即0.5＝2/T₁ 故T₁＝4小時，則該噪音作業時段之噪音音壓級為95分貝\n(二)TWA＝16.61log0.5＋90＝85 分貝\n另解：\n（一）L_{TWA}=16.61log100×D/(12.5×t)+90\n=16.61log100×D/(12.5×2)+90\n=16.61log(50/25)+90\n=16.61log2+90\n=5+90\n=95 分貝\n（二）L_{TWA}=16.61log100×D/(12.5×t)+90\n=16.61log100×D/(12.5×8)+90\n=16.61log(50/100)+90\n=16.61log1/2+90\n=(16.61log1)+(-16.61log2)+90\n=0+(-5)+90\n=85 分貝"},
{"id": "sk-cc-46-10", "topic": "第 46 次（94.11.20）", "code": "46-10", "n": 46, "q": "何謂心肺復甦術？心肺復甦術適合於何種情況使用？(10 分）", "ans": "", "sol": "(一) 心肺復甦術：是以人工呼吸的方式以維持呼吸功能及以人工胸外按摩，維持心臟跳動的方法，來維持及挽救患者的生命。\n(二) 心肺復甦術適合使用情況：以人工呼吸法與胸外壓心法的交推操作，用於呼吸與脈搏均消失的昏迷患者。若患者仍有微弱脈搏(頸動脈)時，如冒然進行心肺復甦術，會造成心律不整而有生命危險。"},
{"id": "sk-cc-47-01", "topic": "第 47 次（95.3.26）", "code": "47-01", "n": 47, "q": "(一)依勞工安全衛生設施規則規定，那些其有有害作業環境之工作場所，雇主應禁止非從事作業有關人員進入?(7 分)\n(二)雇主未實施作業環境測定，經檢查機構通知限期改善而不如期改善，其處罰規定為何?(3 分)", "ans": "", "sol": "(一)1.處置大量高熱物體或顯著濕熱之場所。\n2.處置大量低溫物體或顯著寒冷之場所。\n3.強烈微波、射頻波或雷射等非游離輻射之場所。\n4.氧氣濃度未滿百分之十八之場所。\n5.有害物超過容許濃度之場所。\n6.處置特殊有害物之場所。\n7.生物病原體顯著污染之場所。\n(二)處新臺幣三萬元以上六萬元以下罰鍰。", "old": 1},
{"id": "sk-cc-47-02", "topic": "第 47 次（95.3.26）", "code": "47-02", "n": 47, "q": "僱用勞工 200 人之金屬製品製造公司，依勞工安全衛生法令規定，應如何設置勞工安全衛生組織、人員?(10 分)", "ans": "", "sol": "(一)應設置勞工安全衛生組織如下：\n1.勞工安全衛生管理單位。\n2.勞工安全衛生委員會。\n(二)應設置勞工安全衛生人員如下：\n1.勞工安全衛生管理單位：置勞工安全衛生業務主管及勞工安全衛生管理員各一人。\n2.勞工安全衛生委員會：置委員七人以上；由雇主視該事業單位之實際需要指定下列人員組成：\n（1）事業經營負責人或其代理人。\n（2）勞工安全衛生人員。\n（3）事業內各部門之主管、監督、指揮人員。\n（4）與勞工安全衛生有關之工程技術人員。\n（5）醫護人員。\n（6）工會或勞工選舉之代表。", "old": 1},
{"id": "sk-cc-47-03", "topic": "第 47 次（95.3.26）", "code": "47-03", "n": 47, "q": "試述我國勞工作業環境空氣中有害物容許濃度標準對於勞工之暴露濃度如何規定?如有兩種以上有害物同時存在時應如何評估?(10 分)", "ans": "", "sol": "（一）勞工作業環境空氣中有害物之濃度應符合下列規定：\n1.全程工作日之時量平均濃度不得超過相當「八小時日時量平均容許濃度」。\n2.任何一次連續十五分鐘內之平均濃度不得超過「短時間時量平均容許濃度」。\n3.任何時間均不得超過「最高容許濃度」。\n（二）依據勞工作業環境空氣中有害物容許濃度標準規定作業環境空氣中有二種以上有害物存在而其相互間效應非屬於相乘效應或獨立效應時應視為相加效應，其計算方法如下：\n甲有害物成分之濃度/甲有害物成分之容許濃度 ＋ 乙有害物成分之濃度/乙有害物成分之容許濃度 ＋ 丙有害物成分之濃度/丙有害物成分之容許濃度 …… ＜／＝／＞ １\n其和大於１時，即屬超出容許濃度。"},
{"id": "sk-cc-47-04", "topic": "第 47 次（95.3.26）", "code": "47-04", "n": 47, "q": "(一)工作安全分析之意義為何?(3 分)\n(二)在訂定工作安全分析時，須將工作分解成數個步驟，試簡述有關工作步驟分解的方法為何?(4 分)\n(三)試簡述工作安全分析表修訂之時機為何?(3 分)", "ans": "", "sol": "（一）工作安全分析可以說是「工作分析」與「預知危險」的結合。工作分析是讓主管人員清楚每件工作的詳細步驟、方法內容、規範。而預知危險是將每件工作中所存在的潛在危險與可能危害，事先加以預知，再經溝通討論而決定最佳的行動目標，或工作方法以確保安全工作。\n(二)1.選擇一個有經驗、能力強的工作人員來實地演練操作。\n2.觀察他進行工作，並列出每一個主要基本步驟，並說明每一基本步驟的目的或意義。\n3.與被觀察的人討論並核對每一個主要步驟，並與有關作業人員討論每一步驟，文字宜簡單明瞭，必要時以圖例說明，務使工作人員明瞭。\n4.修正或改進。\n(三)1.發生事故時，分析表應就事故原因予以檢討修改或增刪。\n2.工作程序變更時應即修訂。\n3.工作方法改變時亦應重新分析，以符實際需要。"},
{"id": "sk-cc-47-05", "topic": "第 47 次（95.3.26）", "code": "47-05", "n": 47, "q": "依「營造安全衛生設施標準」之規定，雇主使勞工以機械從事露天開挖作業應符合之規定有那些?試列舉三項。(10 分)", "ans": "", "sol": "(一)使用之機械有損壞地下電線、電纜、危險或有害物管線、水管等地下埋設物，而有危害勞工之虞者，應妥為規劃該機械之施工方法。\n(二)於搬運機械作業或開挖作業時，應指派專人指揮，以防止機械翻覆或勞工自機械後側接近作業場所。\n(三)嚴禁操作人員以外之勞工進入營建用機械之操作半徑範圍內。"},
{"id": "sk-cc-47-06", "topic": "第 47 次（95.3.26）", "code": "47-06", "n": 47, "q": "試解釋下列名詞:\n(一)閃火點(Flash Point)。(5 分)\n(二)最低著火能量(Minimum Ignition Energy)(5 分)", "ans": "", "sol": "(一) 閃火點：引火性液體表面蒸發作用釋出的蒸氣，在空氣中擴散成為可燃性的混合氣體，其濃度相當於爆炸下限，此時液體之最低溫度稱為閃火點。\n(二) 最低著火能量：使引火性液體之蒸氣、可燃性氣體或可燃性粉塵著火需要之最低能量。"},
{"id": "sk-cc-47-07", "topic": "第 47 次（95.3.26）", "code": "47-07", "n": 47, "q": "試列舉五項選擇呼吸防護具應先確認之事項。(10 分)", "ans": "", "sol": "(一)有害物質之種類。\n(二)是否有缺氧之可能。\n(三)是否會立即危及生命或健康。\n(四)有害物在空氣中之濃度為何?\n(五)有害物之物性、化性及毒性。\n(六)是否具刺激性作用，如對眼、鼻、皮膚等。\n(七)是否會引起火災、爆炸。\n(八)是否有設置必要之工程控制設備。\n(九)是否有令人憎惡之味道存在，或其他物理條件。\n(十)是否需配戴其他的防護具如安全眼鏡、防護衣等\n(十一)勞工工作進行速度、工作範圍、移動情形。\n(十二)各項呼吸防護具之特性及限制。（以上列舉五項即可）"},
{"id": "sk-cc-47-08", "topic": "第 47 次（95.3.26）", "code": "47-08", "n": 47, "q": "試說明勞工休克時應如何實施急救。(10 分)", "ans": "", "sol": "(一)避免搬動，維持安靜的環境。\n(二)維持平躺姿勢，下肢微抬高，以改善腦及心臟血循環量。\n(三)注意皮膚的顏色變化。(若改善則由蒼自逐漸變有血色。)\n(四)觀察血壓、脈博、呼吸的次數。\n(五)個案清醒，且沒有嘔吐情況下，給予適量口服液。\n(六)保持呼吸道(Air-way)通暢，必要時給予氧氣(0₂)。\n(七)快速補充液體，以期增加血液循環量。\n(八)注意尿量及尿比重(正常比重為 1.010~1.020)，以防止腎臟的病變。\n(九)注意個案的保暖，以維持個案的體溫。"},
{"id": "sk-cc-47-09", "topic": "第 47 次（95.3.26）", "code": "47-09", "n": 47, "q": "試列舉三項事業單位為預防禽流感而對勞工進行健康狀況監控時之注意事項。(10 分)", "ans": "", "sol": "(1)若曾去過禽流感疫區或是疑似有禽流感污染的環境，一週後出現發燒、呼吸系統或是眼睛感染的結膜炎等必須立刻就醫。\n(2)個人若有不適時應立即向健康照護單位反應，告知是否曾經暴露於禽流感中，並通知服務機構的安全衛生單位。\n(3)高風險暴露勞工個人若有不舒服感覺時建議全天待在家中，直到發燒狀況解除，或經診斷不是 A 型流感感染。"},
{"id": "sk-cc-47-10", "topic": "第 47 次（95.3.26）", "code": "47-10", "n": 47, "q": "(一)一勞工每日工作時間八小時，其噪音之暴露在上午八時至十二時為穩定性噪音，音壓級為 90 dBA；下午一時至下午五時為變動性噪音，此時段暴露累積劑量為 40%。試計算該勞工全程工作日之噪音暴露劑量，並說明該勞工噪音暴露是否合於法令規定。(6 分)\n(二)一噪音(純音)其頻率為 1,OOO Hz，音量為 95 dBA，如該測定儀器無誤差，試將以 F 或 C 權衡電網測定時之結果列出，並說明之。(4 分)", "ans": "", "sol": "(一) D＝4/8 ＋ 40% ＝ 0.5＋0.4＝0.9暴露劑量 D 小於 1， 故合於法令規定。\n(二)噪音計權衡電網設計原理上是依(Fletcher-Munson)的等感覺曲線相當的頻率感度設計用以測定音壓位準。而根據(Fletcher-Munson)等感覺曲線，音量的基準值就是以 1000Hz 的感覺最小音即為 O dB。此噪音(純音)其頻率在 1000Hz 音量為 95dBA 時，因此 F or C 權衡電網測定時之結果為：95 dB + O dB＝95 dB(F)或(C)"},
{"id": "sk-cc-48-01", "topic": "第 48 次（95.7.23）", "code": "48-01", "n": 48, "q": "試述雇主對擔任下列工作之勞工，應依其工作性質至少多久需施以多少時間之勞工安全衛生在職教育訓練。（10 分）\n(一) 勞工安全衛生管理人員\n(二) 高壓氣體作業主管、營造作業主管及有害作業主管\n(三)各級業務主管\n(四)營造作業、車輛系營建機械作業、高空工作車作業、缺氧作業、局限空間作業及製造、處置或使用危險物、有害物作業之人員\n(五)一般勞工", "ans": "", "sol": "(一) 每年至少 6 小時\n(二) 每年至少 6 小時\n(三) 每 2 年至少 3 小時\n(四) 每 2 年至少 3 小時\n(五) 每 2 年至少 3 小時", "old": 1},
{"id": "sk-cc-48-02", "topic": "第 48 次（95.7.23）", "code": "48-02", "n": 48, "q": "為防止勞工於使用移動梯工作時發生墜落災害，依勞工安全衛生設施規則規定，雇主對於供勞工使用之移動梯應符合那些規定?(10 分)", "ans": "", "sol": "1.具有堅固之構造。\n2.其材質不得有顯著之損傷、腐蝕等現象。\n3.寬度應在三十公分以上。\n4.應採取防止滑溜或其他防止轉動之必要措施。", "old": 1},
{"id": "sk-cc-48-03", "topic": "第 48 次（95.7.23）", "code": "48-03", "n": 48, "q": "試述依事業單位僱用人數在一百人以上者，雇主應訂定勞工安全衛生管理規章，要求各級主管及管理、指揮、監督有關人員執行與其有關之那些勞工安全衛生事項？(10 分)", "ans": "", "sol": "一、職業災害防止計畫事項。\n二、安全衛生管理執行事項。\n三、定期檢查、重點檢查、檢點及其他有關檢查督導事項。\n四、定期或不定期實施巡視。\n五、提供改善工作方法。\n六、擬定安全作業標準。\n七、教導及督導所屬依安全作業標準方法實施。\n八、其他雇主交辦有關安全衛生管理事項。", "old": 1},
{"id": "sk-cc-48-04", "topic": "第 48 次（95.7.23）", "code": "48-04", "n": 48, "q": "試述安全作業標準之功用為何？(10 分)", "ans": "", "sol": "1、防範工作場所災害發生。\n2、確定工作場所所需設備或器具。\n3、選擇適當的人員工作。\n4、作為安全教導參考。\n5、作為安全觀察參考。\n6、作為事故調查參考。\n7、增進工作人員之參與感。"},
{"id": "sk-cc-48-05", "topic": "第 48 次（95.7.23）", "code": "48-05", "n": 48, "q": "某營造公司僱用勞工 250 人，二月份總歷經工時為 50,000 小時，其二月份全月職災之紀錄僅記載於二月六日下午四時發生施工架倒塌，致甲勞工當場死亡；乙勞工受傷住院，二月二十二日恢復工作；丙勞工受傷回家休養，翌日恢復上班工作。試計算該公司該月之失能傷害頻率（傷害頻率）、失能傷害嚴重率（職業災害嚴重率）（計算時應列出公式）。(10 分)", "ans": "", "sol": "(一) 失能傷害頻率(FR)＝失能傷害人次數×1,000,000/總歷經工時\n＝2×1,000,000/50000＝40\n(二) 失能傷害嚴重率(SR)＝失能傷害總損失日數×1,000,000/總歷經工時\n＝（6000＋15）×1,000,000/50000＝120300"},
{"id": "sk-cc-48-06", "topic": "第 48 次（95.7.23）", "code": "48-06", "n": 48, "q": "依勞工安全衛生設施規則規定，下列機械各應分別裝設（置）何種安全防護裝置？\n（一）離心機械\n（二）射出成型機\n（三）滾輾橡膠之滾輾機\n（四）具有捲入點之滾軋機\n（五）棉紡機之高速迴轉部份", "ans": "", "sol": "(一) 離心機械：應裝置覆蓋及連鎖裝置。\n（二）射出成型機：應設置安全門，雙手操作式起動裝置或其他安全裝置。\n（三）滾輾橡膠之滾輾機：應設置於災害發生時，被害者能自己易於操縱之緊急制動裝置。\n（四）具有捲入點之滾軋機：應設護圍、導輪等設備。\n（五）棉紡機之高速迴轉部份：應於專用之堅固建築物內或以堅固之隔牆隔離之場所實施。", "old": 1},
{"id": "sk-cc-48-07", "topic": "第 48 次（95.7.23）", "code": "48-07", "n": 48, "q": "依感電所引起的事故，有那些預防對策？(10 分)", "ans": "", "sol": "1.小電壓法。\n2.遙控方法。\n3.減低電路對地電壓。\n4.非接地配電方式。\n5.電氣設備接地。\n6.裝設漏電斷路器。\n7.電氣設備定期檢查。\n8.電氣作業時採取必要之措施。\n9.其他防之感電措施。如交流電焊機加裝自動電擊防止裝置。"},
{"id": "sk-cc-48-08", "topic": "第 48 次（95.7.23）", "code": "48-08", "n": 48, "q": "王君每日八小時的工作時間內，於 A 場所工作時間為三小時、B 場所為三小時、C 場所為二小時、甲物質八小時日時量平均容許濃度為 120ppm、乙物質為 60ppm、丙物質為 40ppm。各場所時量平均暴露濃度如下表所示，請以相加效應評估王君之暴露是否合於勞工安全衛生法令規定？(10 分)（假設八小時內任何時間濃度均未超過短時間時量平均容許濃度）", "ans": "", "sol": "甲物質：（80×3）÷8＝30 ppm\n乙物質：（30×3＋50×3）÷8＝30 ppm\n丙物質：（40×3＋20×2）÷8＝20 ppm\n計算如下：（30÷120）＋（30÷60）＋（20÷40）＝1.25\n其和大於１超出容許濃度，不合於勞工安全衛生法令規定。", "fig": "|  | A 場所 | B 場所 | C 場所 |\n| --- | --- | --- | --- |\n| 甲物質 | 80ppm | 0 | 0 |\n| 乙物質 | 30ppm | 50ppm | 0 |\n| 丙物質 | 0 | 40ppm | 20ppm |", "old": 1},
{"id": "sk-cc-48-09", "topic": "第 48 次（95.7.23）", "code": "48-09", "n": 48, "q": "勞工懷疑自己罹患職業病，欲向雇主申請職業災害補償，試述勞雇雙方可循何程序處理？。(10 分)", "ans": "", "sol": "", "fig": "流程：勞工疑似罹患職業病 → 醫師（職業疾病／非職業疾病） → 診斷結果勞雇任一方有無異議。\n1.無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償。\n2.無異議且不屬職業疾病 → 結案。\n3.有異議 → 直轄市、縣（市）政府認定；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案。\n4.直轄市、縣（市）政府認定困難，或勞雇任一方對認定有異議 → 行政院勞工委員會（職業疾病鑑定委員會）；勞工保險機構審定職業疾病認有必要時，亦送行政院勞工委員會。\n5.行政院勞工委員會 → 診斷結果勞雇任一方有無異議；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案；有異議 → 法律訴訟。", "note": "本題有流程圖，內容已轉錄於 fig。"},
{"id": "sk-cc-48-10", "topic": "第 48 次（95.7.23）", "code": "48-10", "n": 48, "q": "（一）請說明通風之主要目的為何?（6 分）\n（二）適合使用整體換氣裝置之場合有那些？（4 分）", "ans": "", "sol": "(一) 通風之目的：1.維持作業場所之舒適。\n2.排除作業場所空氣中之有害物。\n3.稀釋作業產生之有害物。\n4.防止火災或爆炸事故之發生。\n5.維持作業場所空氣中之良好品質。\n6.供給補充之新鮮空氣。\n(二)其使用場合：1.產生之有害物質毒性較低之作業場所。\n2.有害物質產生速率較小之作業場所。\n3.有害物質之發生源均勻廣泛。\n4.有害物質之發生源遠離作業者呼吸域時。"},
{"id": "sk-cc-49-01", "topic": "第 49 次（95.11.19）", "code": "49-01", "n": 49, "q": "請依勞工安全衛生法令解釋下列各項。(10 分)\n(一)就業場所;\n(二)共同作業;\n(三)工作場所負責人;\n(四)體格檢查;\n(五)定期健康檢查", "ans": "", "sol": "(一) 就業場所：係指於勞動契約存續中，由雇主所提示，使勞工履行契約提供勞務之場所。\n(二) 共同作業：係指事業單位與承攬人、再承攬人所僱用之勞工於同一期間、同一工作場所從事工作。\n(三) 工作場所負責人：係指於該工作場所中代表雇主從事管理、指揮或監督勞工從事工作之人。\n(四) 體格檢查：係指於僱用勞工或變更其工作時，為識別勞工工作適性，考量其是否有不適合作業之疾病所實施之健康檢查。\n(五) 定期健康檢查：所稱定期健康檢查，係指依在職勞工之年齡層，於一定期間所實施之一般健康檢查。", "old": 1},
{"id": "sk-cc-49-02", "topic": "第 49 次（95.11.19）", "code": "49-02", "n": 49, "q": "(一)事業單位工作場所發生那些職業災害時，雇主應於二十四小時內報告檢查機構?(6 分)\n(二)如未於二十四小時內報告檢查機構，依勞工安全衛生法令規定，其罰則為何?(4 分)", "ans": "", "sol": "(一)事業單位工作場所發生下列職業災害之一時，雇主應於二十四小時內報告檢查機構：\n一、發生死亡災害者。\n二、發生災害之罹災人數在三人以上者。\n三、其他經中央主管機關指定公告之災害。\n(二) 處一年以下有期徒刑、拘役或科或併科新臺幣九萬元以下罰金。", "old": 1},
{"id": "sk-cc-49-03", "topic": "第 49 次（95.11.19）", "code": "49-03", "n": 49, "q": "雇主對於機械之掃除、上油、檢查、修理或調整有導致危害勞工之虞者，應採取那些措施?(10 分)", "ans": "", "sol": "1.應停止該機械運轉。\n2.為防止他人操作該機械之起動裝置，應採上鎖或設置標示等措施。\n3.設置防止落下物導致危害勞工之安全設施。\n4.工作如必須在運轉狀態下施行者，雇主應於危險之部分設置護罩或護圍等設備。"},
{"id": "sk-cc-49-04", "topic": "第 49 次（95.11.19）", "code": "49-04", "n": 49, "q": "工作安全分析之目的為發現潛在的危險或可能危害而加以控制，分析時應特別重視危險根源或應考慮及注意事項為何?並試將工作安全分析之程序列出。(10 分)", "ans": "", "sol": "(一) 1.人的方面。\n2.方法方面。\n3.機械方面。\n4.材料方面。\n5.環境方面。\n（二）1.擬定工作安全分析計畫。\n2.決定要分析工作的名稱。\n3.將工作步驟分解。\n4.辨識出潛在的危險。\n5.決定安全的工作方法。"},
{"id": "sk-cc-49-05", "topic": "第 49 次（95.11.19）", "code": "49-05", "n": 49, "q": "試說明四種會發生墜落之虞之場所或作業，並分別說明其預防墜落之方法？\n(10 分)", "ans": "", "sol": "1.高度二公尺以上工作場所邊緣及開口部分預防：設置適當之護欄、握把、覆蓋等防護措施或採取讓勞工使用安全帶。\n2.石綿、鐵皮板、瓦、木板、茅草、塑膠等材料構築之屋頂。\n預防：於屋架上設置適當強度且寬度在三十公分以上之踏板或裝設安全護網。\n3.以船舶運輸勞工前往作業場所預防：不得超載，備置救生衣及其他救生用具。\n4.水上作業（二公尺屋頂水上船舶）預防：使勞工穿上救生衣，設置監事人員及救生設備。"},
{"id": "sk-cc-49-06", "topic": "第 49 次（95.11.19）", "code": "49-06", "n": 49, "q": "(一)某一戶外有日曬工作環境中，測得乾球溫度 31°C，自然濕球溫度 27°C，黑球溫度 34°C，請問該環境之綜合溫度熱指數為若干?(請列出計算公式)(5分)\n(二)某一戶內工作環境中，作業人員呼氣與製程所產生二氧化碳之速率為5m³/hr，戶外二氧化碳濃度為 400ppm，如欲使戶內二氧化碳濃度不超過1400ppm，則戶外空氣之進氣量應至少為若干m³/hr?(請列出計算公式)(5 分)", "ans": "", "sol": "(一) WBGT＝0.7 × tnwb + 0.2 × tg + 0.1 × tb\n＝0.7×27°C＋0.2×34°C＋0.1×31°C\n＝28.8°C\n（二）Q＝K/p－q＝5m³/hr / (1400-400)×10⁻⁶＝5000 m³/hr"},
{"id": "sk-cc-49-07", "topic": "第 49 次（95.11.19）", "code": "49-07", "n": 49, "q": "某一作業場所勞工．人數 150 人，採一班制，作業場所長 25 公尺、寬 15公尺、高 4 公尺，每天工作八小時，每日甲苯及丙酮消費量分別為二公斤及四公斤，如使用整體換氣裝置控制時，其最少換氣量為何?(10 分)說明:甲苯、丙酮皆為第二種有機溶劑，其分子量分別為\n92、58，日時量平均容許濃度分別為100ppm、750ppm。依勞工安全衛生設施規則規定，為避免CO₂超過容許濃度必要之換氣量標準如下表:", "ans": "", "sol": "(一)工作場所每一勞工所佔立方公尺數＝(25×15×4)/150＝10m³/人依換氣量標準表得知換氣能力應達 0.4 m³/min．人\n故換氣能力為Q₁＝0.4 m³/min．人×150人＝60 m³/min\n(二) Q₂＝【(2000＋4000)÷8】×0.04＝30 m³/min\n(三) Q₃＝【(24.45×10³×2000)÷(60×100×92)＋(24.45×10³×4000)÷(60×750×58)】÷8\n＝【88.59＋37.47】÷8＝15.76 m³/min\n因為Q₁(60 m³/min)＞Q₂(30 m³/min)＞Q₃(15.76 m³/min)\n所以本題之作業場所如使用整體換氣裝置控制時，其最少換氣量為：\n60 m³/min", "note": "題目提及「下表」，但原PDF該題未見對應表格。", "old": 1},
{"id": "sk-cc-49-08", "topic": "第 49 次（95.11.19）", "code": "49-08", "n": 49, "q": "試述辦理勞工體格檢查及定期健康檢查之目的。(10 分)", "ans": "", "sol": "1.依勞工之身體及心理狀況，分配適當工作，避免危害勞工本身及其同伴。\n2.早期偵知有害作業場所的各種影響，評估安全衛生管理措施是否適當並提出改善措施。\n3.藉由教育訓練養成勞工良好之衛生與安全習慣，以保持或增進勞工之健康與幸福。\n4.減少勞工因傷病而缺工。\n5.於每次檢查之際，均建立每一勞工的健康資料，並歸納整體趨勢，俾採取對策。"},
{"id": "sk-cc-49-09", "topic": "第 49 次（95.11.19）", "code": "49-09", "n": 49, "q": "電氣接地之種類有那些?又其接地電阻規定值分別為多少?", "ans": "", "sol": "接地線種類及接地電阻規定值分別為：\n（1）特種地線 ：接地電阻 10 歐姆以下\n（2）第一種地線：接地電阻 25 歐姆以下\n（3）第二種地線：接地電阻 50 歐姆以下\n（4）第三種地線：接地電阻 10~100 歐姆以下"},
{"id": "sk-cc-49-10", "topic": "第 49 次（95.11.19）", "code": "49-10", "n": 49, "q": "試述火災之四種滅火原理或方法?並各舉一例說明之。(10 分)", "ans": "", "sol": "1.隔離法：將燃燒中的物質移開或斷絕其供應，使受熱面積減少，以削弱火勢或阻止延燒以達滅火的目的。如防火巷。\n2.冷卻法：將燃燒物冷卻，使其熱能減低，亦能使火自然熄滅。如消防水。\n3.窒息法：使燃燒中的氧氣含量減少，可以達到窒息火災的效果。如二氧化碳。\n4.抑制法：在連鎖反應中的游離基，可用化學乾粉或鹵化碳氫化合物除去。如 ABC 乾粉。"},
{"id": "sk-cc-50-01", "topic": "第 50 次（96.4.22）", "code": "50-01", "n": 50, "q": "依「營造安全衛生設施標準」之規定，對於高度二公尺以上之工作場所，勞工作業有墜落之虞者，試說明雇主應依那些規定項目訂定墜落災害防止計畫，採取適當墜落災害防止設施?(10 分)", "ans": "", "sol": "一、經由設計或工法之選擇，儘量使勞工於地面完成作業以減少高處作業項目。\n二、經由施工程序之變更，優先施作永久構造物之上下昇降設備或防墜設施。\n三、設置護欄、護蓋。\n四、張掛安全網。\n五、使勞工佩掛安全帶。\n六、設置警示線系統。\n七、限制作業人員進入管制區。\n八、對於因開放邊線、組模作業、收尾作業等及採取第一款至第五款規定之設施致增加其作業危險者，應訂定保護計畫並實施。"},
{"id": "sk-cc-50-02", "topic": "第 50 次（96.4.22）", "code": "50-02", "n": 50, "q": "依「勞工安全衛生設施規則」之規定，對於毒性高壓氣體之儲存及使用，應依那些規定辦理?(10 分)", "ans": "", "sol": "(一) 雇主對於毒性高壓氣體之儲存，應依下列規定辦理：\n1、貯存處要置備吸收劑、中和劑及適用之防毒面罩或呼吸用防護具。\n2、具有腐蝕性之毒性氣體，應充分換氣，保持通風良好。\n3、不得在腐蝕化學藥品或煙囪附近貯藏。\n4、預防異物之混入。\n(二) 雇主對於毒性高壓氣體之使用，應依下列規定辦理：\n1、非對該氣體有實地瞭解之人員，不准進入。\n2、工作場所空氣中之毒性氣體濃度不得超過容許濃度。\n3、工作場所置備充分及適用之防護具。\n4、使用毒性氣體場所，應保持通風良好。", "old": 1},
{"id": "sk-cc-50-03", "topic": "第 50 次（96.4.22）", "code": "50-03", "n": 50, "q": "依「機械器具防護標準」之規定，試回答下列問題:\n(一)雙手操作式安全裝置中，安全一行程式安全裝置應具有之機能為何?(2 分)\n(二)雙手起動式安全裝置應具有之機能為何?(2 分)\n(三)安全一行程式安全裝置，其按鈕與危險界限間之距離如何計算?(3 分)\n(四)雙手起動式安全裝置之按鈕與危險界限間之距離如何計算?(3 分)", "ans": "", "sol": "(一)安全一行程式安全裝置：雙手操作式安全裝置、在手指自按下起動按鈕或操作控制桿，脫手後至該手達到危險界限前，能使滑塊等停止動作。\n(二)雙手起動式安全裝置：以雙手操作按鈕等，於滑塊等動作中，手離開按鈕等時手無法達到危險界限。\n(三) D >1.6(T1+Ts）式中D ：為按鈕等與危險界限間之距離以公厘表示。\nT1：為手指離開按鈕等時至緊急停止機構開始動作之時間以毫秒表示。\nTs：緊急停止機構開始動作時至滑塊停止之時間，以毫秒表示。\n(四) D >1.6Tm式中D：雙手起動式安全裝置者為自按鈕等至危險界限間之距離，以公厘表示。\nTm：手指離開按鈕等至滑塊抵達下死點時之最大時間，以毫秒表示。\n註：本題為新題。"},
{"id": "sk-cc-50-04", "topic": "第 50 次（96.4.22）", "code": "50-04", "n": 50, "q": "緊急應變計畫之主要內容，除了法令要求事項外，為使計畫架構趨於完整，請列舉五個要項。(10 分)", "ans": "", "sol": "1.擬定緊急應變組織架構及權責\n2.訂定通報程序及連絡體系\n3.整理緊急應變器材之配置狀況並統計數量\n4.擬定疏散路線圖、疏散後集合點及清查人數方式\n5.擬定緊急應變程序\n6.訂定各類意外狀況緊急處理措施\n7.事故調查及復原工作\n8.訂定緊急應變訓練計畫\n9.實施演練計畫\n10.緊急應變計畫之檢討與修正（以上任選五項）"},
{"id": "sk-cc-50-05", "topic": "第 50 次（96.4.22）", "code": "50-05", "n": 50, "q": "試簡述下列名詞。(10 分)\n(一)高空工作車\n(二)壓氣施工法\n(三)漏電斷路器\n(四)擋土支撐", "ans": "", "sol": "(一)高空工作車：係指於二公尺以上之高處作業，無法施作施工架或工作台，亦無法張設安全網或佩戴安全帶時，以油壓升降工作台，從事頂高作業之車輛。\n(二)壓氣施工法：係指基礎施工時若現場地層湧水量多或極軟弱時，將壓縮空氣壓送到沈箱內部之作業室，使其壓力與地下水壓呈平衡狀態，再放入作業人員，挖掘下面土砂，利用構造物重量或荷重之力量，使構造物(沈箱)逐次沈下到預定位置，此種工法稱為壓氣沈箱工法。\n(三)漏電斷路器：係指為防止電氣設備發生接地之異常現象，造成勞工因漏電而有感電之危害所裝置之設備，其可檢測電路漏電狀態而將電路切斷。\n(四)擋土支撐 ：係指為防止露天開挖作業發生土方倒塌崩塌對勞工之危害，應依位置條件及周圍條件、地盤條件、開挖深度、建築物之規模等決定。所做之擋土預防設施之謂，其種類有鋼製支撐、鋼筋混凝土製支撐、地錨等。"},
{"id": "sk-cc-50-06", "topic": "第 50 次（96.4.22）", "code": "50-06", "n": 50, "q": "勞工從事下列作業時，會引起那些危害，試從下表中選出其代號:\n(一)局部振動;\n(二)高溫作業;\n(三)熔接作業;\n(四)高壓室內作業;\n(五)電腦終端機作業;\n(六)二異氮酸甲苯作業;\n(七)鉛作業;\n(八)氯乙烯作業;\n(九)噴砂(石英砂)作業;\n(十)煉焦作業。(10 分)", "ans": "", "sol": "(一)局部振動：I (白指病)\n(二)高溫作業：A (熱痙攣)\n(三)熔接作業：H (電眼炎)\n(四)高壓室內作業：J (減壓症)\n(五)電腦終端機作業：B (腕隧道症候群)\n(六)二異氰酸甲苯作業：G (過敏性氣喘)\n(七)鉛作業：C (貧血)\n(八)氯乙烯作業：E (肝癌)\n(九)噴砂：D (塵肺症)\n(十)煉焦作業：F (肺癌)", "note": "題目提及「下表」，但原PDF該題未見對應表格。"},
{"id": "sk-cc-50-07", "topic": "第 50 次（96.4.22）", "code": "50-07", "n": 50, "q": "試列舉五種應考慮使用呼吸防護具之場合", "ans": "", "sol": "有害物作業場所如：有機溶劑作業場所、鉛作業場所、特定化學物質作業場所、缺氧作業場所、粉塵作業場所等使用呼吸防護具應考量下述因素：\n1.危害性作業或製程之特性。\n2.空氣污染物之類型，含其物性、化性、濃度及對人體之效應等。\n3.需使用防護具之時間。\n4.危害作業場所與清淨空氣供應處之位置。\n5.防護具之功能與物理特性。"},
{"id": "sk-cc-50-08", "topic": "第 50 次（96.4.22）", "code": "50-08", "n": 50, "q": "有一框式鋼管施工架構築之移動式施工架，每框架(立架)寬 70 公分、高 180公分共組搭四層，其腳部接續使用 12 公分高之腳輪，為防止使用移動式施工架作業之傾倒危險，試問該施工架短邊方向至少應分別伸出幾公分之輔助撐材?(10 分;應列出計算式)", "ans": "", "sol": "H≦7.7L－5.0式中 H 為自腳輪至工作台之高度(公尺)L 為腳輪主軸之間距(公尺)L>(H+5)/7.7 ∵H＝(180×4)+12＝7.32 公尺L>(7.32+5)/7.7 L>1.6 公尺\n∴施工架短邊方向至少應分別伸出長度(公分)\n＝(160－70)/2＝45 公分"},
{"id": "sk-cc-50-09", "topic": "第 50 次（96.4.22）", "code": "50-09", "n": 50, "q": "正已烷 (分子量 86)每天 8 小時消費 48 公斤，其爆炸範圍 1.1%~7.5%，為防止爆炸，\n(一)在一大氣壓下，25°C，時其理論換氣量應至少為多少?\n(二)若設定安全係數為 5 時，其換氣量應至少為多少?(10 分)", "ans": "", "sol": "(一)在一大氣壓下，25°C，時其理論換氣量：\nQ＝( 24.45 × 1000 × W ) ÷ ( 60 × LEL × 10⁴× M )\n＝【24.45 ×1000 × ( 48000 ÷ 8 )】÷ ( 60 × 1.1 × 10⁴ × 86)\n＝2.58 M³/min\n(二)若設定安全係數為 5 時，其換氣量：\nQ ＝ 2.58 M³/min × 5 ＝ 12.92 M³/min"},
{"id": "sk-cc-50-10", "topic": "第 50 次（96.4.22）", "code": "50-10", "n": 50, "q": "工作場所中，有許多會導致勞工產生職業壓力之可能來源。試根據\n(一)作業環境危害種類及\n(二)工作內容特性，各舉出五項職業壓力源。(10 分)", "ans": "", "sol": "（一）作業環境危害種類職業壓力源：\n1.採光照明\n2.噪音\n3.通風換氣\n4.高溫\n5.有害物暴露\n（二）工作內容特性職業壓力源：\n(1)公司或組織內部之衝突\n(2)勞工個人生涯之發展\n(3)個人所扮演之角色衝突或模糊\n(4)工作的負荷量或難度\n(5)輪班工作\n註：本題出自甲級安全或衛生管理師『勞動生理/勞動疲勞與壓力』課程內。"},
{"id": "sk-cc-51-01", "topic": "第 51 次（96.8.5）", "code": "51-01", "n": 51, "q": "雇主對於機械之掃除、上油、檢查、修理或調整有導致危害勞工之虞者，應採取那些措施？(10 分)", "ans": "", "sol": "1.應停止該機械作業。\n2.為防止他人操作該機械之起動裝致，應採取上鎖或設置標示等措施。\n3.設置防止落下物導致危害勞工之安全設施。\n4.工作若必須在運轉狀態下施行者，雇主應於危險之部份設置護罩或護圍等設備。"},
{"id": "sk-cc-51-02", "topic": "第 51 次（96.8.5）", "code": "51-02", "n": 51, "q": "依「營造安全衛生設施標準」之規定，試說明雇主使勞工鄰近河川、湖泊、海岸作業，勞工有落水之虞者，應辦理之事項為何？(10 分)", "ans": "", "sol": "一、設置防止勞工落水之設施或使勞工著用救生衣。\n二、於工作場所或其附近設置下列救生設備：\n（一）依勞工人數，備足夠數量之動力救生船（如橡皮艇），每艘船上並配備長度十五公尺，直徑九‧五公厘之聚丙烯纖維繩索，其上掛繫與最大可救援人數相同之救生圈以及船鉤、救生衣。\n（二）有湍流、潮流之情況，應預先架設延伸過水面且位於作業場所上方的繩索，其上掛繫可支持拉住落水者之救生圈。\n（三）可通知相關人員參與救援行動之警報系統。"},
{"id": "sk-cc-51-03", "topic": "第 51 次（96.8.5）", "code": "51-03", "n": 51, "q": "依勞工安全衛生組織管理及自動檢查辦法規定，勞工安全衛生委員會：\n(一)應每幾個月至少開會一次？(2 分)\n(二)應辦理那些事項(至少列出 8 項)？(8 分)", "ans": "", "sol": "(一)應每三個月至少開會一次。\n(二)委員會應辦理下列事項並應置備紀錄：\n1、對雇主擬訂之勞工安全衛生政策提出建議。\n2、協調、建議安全衛生自主管理計畫。\n3、研議安全、衛生教育訓練實施計畫。\n4、研議作業環境測定結果應採取之對策。\n5、研議健康管理及健康促進事項。\n6、研議各項安全衛生提案。\n7、研議事業單位自動檢查及安全衛生稽核事項。\n8、研議機械、設備或原料、材料危害之預防措施。", "old": 1},
{"id": "sk-cc-51-04", "topic": "第 51 次（96.8.5）", "code": "51-04", "n": 51, "q": "試以聯合國勞工組織所頒布之職業安全衛生管理系統指引(ILO-OSH 2001)，說明職業安全衛生管理系統之五大要素為何？(10 分)", "ans": "", "sol": "一、政策(－)職業安全衛生政策\n(二)勞工參與\n二、組織編制(－)職責及考核責任\n(二)能力及訓練\n(三)職業安全衛生管理系統文件\n(四)溝通\n三、規劃與執行\n(一)先期審查\n(二)系統規劃、建立與實施\n(三)安全衛生目標\n(四)危害預防\n四、評估(－)績效監督與量測\n(二)職業傷害、疾病、事故、及其對安全衛生績效影響之調查。\n(三)稽核－定期對安全衛生管理系統之適當性進行稽核以保護勞工的安全衛生。\n(四)管理階層審查\n五、改善措施\n(一)預防及改善措施\n(二)持續改善"},
{"id": "sk-cc-51-05", "topic": "第 51 次（96.8.5）", "code": "51-05", "n": 51, "q": "某事業單位僱用勞工 500 人，6 月份總經歷工時為 80,000 小時，6 月 8 日下午 5 時發生一起感電職業災害，造成甲勞工送醫急救無效死亡，乙勞工受傷住院，6 月 29 日恢復上班，丙勞工受傷經包紮後回家休養，翌日 8 時恢復上班工作，試計算該事業 6 月份傷害頻率及職業災害嚴重率？(計算過程時應列出公式)(10 分)", "ans": "", "sol": "總歷經工時＝80,000 小時\n失能傷害人次數＝2（丙於 6 月 8 日下午 5 時受傷經，翌日 8 時即上班，不予列計）\n失能傷害損失日數分別為：甲＝6000 天 ；乙＝29－8－1＝20 天；丙（輕\n傷害）＝0 天\n失能傷害總損失日數＝6000＋20＝6020 天\n失 能 傷 害 頻率 (FR) ＝ 失 能 傷 害 人 次數 × 1,000,000/ 總 歷 經 工 時 ＝\n2×1,000,000/80000＝25\n失能傷害嚴重率(SR)＝失能傷害總損失日數×1,000,000/總歷經工時\n＝6020×1,000,000/80000＝75,250"},
{"id": "sk-cc-51-06", "topic": "第 51 次（96.8.5）", "code": "51-06", "n": 51, "q": "勞工懷疑自己罹患職業病，欲向雇主申請職業災害補償，試述勞雇雙方可循何程序處理。(10 分)", "ans": "", "sol": "", "fig": "流程：勞工疑似罹患職業病 → 醫師（職業疾病／非職業疾病） → 診斷結果勞雇任一方有無異議。\n1.無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償。\n2.無異議且不屬職業疾病 → 結案。\n3.有異議 → 直轄市、縣（市）政府認定；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案。\n4.直轄市、縣（市）政府認定困難，或勞雇任一方對認定有異議 → 行政院勞工委員會（職業疾病鑑定委員會）；勞工保險機構審定職業疾病認有必要時，亦送行政院勞工委員會。\n5.行政院勞工委員會 → 診斷結果勞雇任一方有無異議；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案；有異議 → 法律訴訟。", "note": "本題有流程圖，內容已轉錄於 fig。"},
{"id": "sk-cc-51-07", "topic": "第 51 次（96.8.5）", "code": "51-07", "n": 51, "q": "請列舉 5 項鍋爐操作人員於操作鍋爐之過程中應實施之事項。(10 分)", "ans": "", "sol": "1、監視壓力、水位、燃燒狀態等運轉狀態，並確認安全閥、壓力表及其他安全裝置無異狀。\n2、避免急劇負荷變動之現象。\n3、保持汽壓在最高使用壓力以下。\n4、保持安全閥之功能正常。\n5、每日檢點水位測定裝置之功能一次以上。"},
{"id": "sk-cc-51-08", "topic": "第 51 次（96.8.5）", "code": "51-08", "n": 51, "q": "請列舉 5 項戴用工地安全帽時應遵守之事項。(10 分)", "ans": "", "sol": "1.帽子必須正戴並嚴禁反戴。\n2.帽帶應確實的裝入或嵌入帽接合處，且不可前後或左右錯誤接合。\n3.帽帶與帽殼中，不應填入或塞入任何異物，且應使頭部直接接觸帽帶為之。\n4.除了調整帽帶與頭部之鬆緊外，不宜外加其他扣緊裝置使其固牢於頭部。\n5.帽殼與帽帶之間應保持一定的間隙。"},
{"id": "sk-cc-51-09", "topic": "第 51 次（96.8.5）", "code": "51-09", "n": 51, "q": "為防止高處作業人員發生墜落災害，試舉出 5 項在「人員管理」方面之對策。(10 分)", "ans": "", "sol": "1.經由設計或工法之選擇，儘量使勞工於地面完成作業以減少高處作業項目。\n2.經由施工程序之變更，優先施作永久構造物之上下昇降設備或防墜設施。\n3.使勞工佩掛安全帶。\n4.限制作業人員進入管制區。\n5.對於因開放邊線、組模作業、收尾作業等及採取法定規定之設施致增加其作業危險者，應訂定保護計畫並實施。"},
{"id": "sk-cc-51-10", "topic": "第 51 次（96.8.5）", "code": "51-10", "n": 51, "q": "王君每日 8 小時的工作時間內，於 A 場所作業時間為 4 小時、B 場所為 2 小時、C 場所為 2 小時，甲物質 8 小時日時量平均容許濃度為 40 ppm，乙物質為 120 ppm、丙物質為 400 ppm，各場所時量平均暴露濃度如下表所示，請以相加效應評估王君之暴露是否合於法令規定？(10 分)(假設 8 小時內任何時間濃度均很穩定)", "ans": "", "sol": "甲物質：(20 × 4 + 40 × 2 + 0 × 2)/8＝20ppm\n乙物質：(80 × 4 + 0 × 2 + 80 × 2)/8＝60ppm\n丙物質：(0 × 4 + 100 × 2 + 300 × 2)/8＝100ppm\n計算如下：20/40 ＋ 60/120 ＋ 100/400＝1.25\n其和大於1已超出容許濃度，於法令規定不合。", "fig": "|  | A | B | C |\n| --- | --- | --- | --- |\n| 甲 | 20ppm | 40ppm | 0 |\n| 乙 | 80ppm | 0 | 80ppm |\n| 丙 | 0 | 100ppm | 300ppm |"},
{"id": "sk-cc-52-01", "topic": "第 52 次（96.11.18）", "code": "52-01", "n": 52, "q": "依「勞工安全衛生設施規則」之規定，雇主供給勞工使用之個人防護具或防護器具，應依規定辦理之項目為何？(10 分)", "ans": "", "sol": "依勞工安全衛生設施規則第二百七十七條：\n1.保持清潔，並予必要之消毒。\n2.經常檢查，保持其性能，不用時並妥予保存。\n3.防護具或防護器具應準備足夠使用之數量，個人使用之防護具應置備與作業勞工人數相同或以上之數量，並以個人專用為原則。\n4.如對勞工有感染疾病之虞時，應置備個人專用防護器具，或作預防感染疾病之措施。", "old": 1},
{"id": "sk-cc-52-02", "topic": "第 52 次（96.11.18）", "code": "52-02", "n": 52, "q": "依「營造安全衛生設施標準」之規定，試說明工地露天開挖為防止地面之崩塌及損壞地下埋設物致有危害勞工之虞，應事前就作業地點從事那些調查？(10 分)", "ans": "", "sol": "依營造安全衛生設施標準第六十三條：\n1.地面形狀、地層、地質、鄰近建築物及交通影響情形等。\n2.地面有否龜裂、地下水位狀況及地層凍結狀況等。\n3.有無地下埋設物及其狀況。\n4.地下有無高溫、危險或有害之氣體、蒸氣及其狀況。"},
{"id": "sk-cc-52-03", "topic": "第 52 次（96.11.18）", "code": "52-03", "n": 52, "q": "依「勞工安全衛生設施規則」之規定，於通風或換氣不充分之工作場所，使用可燃性氣體及氧氣從事熔接、熔斷或金屬之加熱作業時，為防止該等氣體之洩漏或排出引起爆炸、火災，試舉出 5 項雇主應辦理之事項？(10 分)", "ans": "", "sol": "依勞工安全衛生設施規則第一百八十九條：\n1.氣體軟管或吹管，應使用不因其損傷、摩擦導致漏氣者。\n2.氣體軟管或吹管相互連接處，應以軟管帶、軟管套及其他適當設備等固定確實套牢、連接。\n3.擬供氣於氣體軟管時，應事先確定在該軟管裝置之吹管在關閉狀態或將軟管確實止栓後，始得作業。\n4.氣體等之軟管供氣口之閥或旋塞，於使用時應設置標示使用者之名牌，以防止操作錯誤引起危害。\n5.從事熔斷作業時，為防止自吹管放出過剩氧氣引起火災，應有充分通風換氣之設施。", "old": 1},
{"id": "sk-cc-52-04", "topic": "第 52 次（96.11.18）", "code": "52-04", "n": 52, "q": "某公司擬建立職業安全衛生管理系統，試依我國國家級職業安全衛生管理系統指引，列舉出 5 項可對員工進行健康評估之程序或方法？(10 分)", "ans": "", "sol": "依我國國家級職業安全衛生管理系統指引，可對員工進行健康評估之程序或方法列舉 5 項如下：\n1.健康檢查\n2.生物監測\n3.輻射檢查\n4.問卷調查\n5.健康紀錄評估"},
{"id": "sk-cc-52-05", "topic": "第 52 次（96.11.18）", "code": "52-05", "n": 52, "q": "企業應致力推動與從事安全衛生管理工作，請列出 10 項應落實或努力之面向？(10 分)", "ans": "", "sol": "1.職業災害防止計畫\n2.緊急應變計畫\n3.安全衛生管理規章\n4.安全衛生工作守則\n5.工作安全分析\n6.安全作業標準\n7.自動檢查計畫\n8.安全觀察與安全接談\n9.安全衛生教育訓練計畫\n10.事故調查"},
{"id": "sk-cc-52-06", "topic": "第 52 次（96.11.18）", "code": "52-06", "n": 52, "q": "如何防止作業場所噪音危害？請就工程改善及行政管理寫出可採取的措施。(10 分)", "ans": "", "sol": "（一）工程改善\n(1)設置吸音板等吸音設備，減低反射音波。\n(2)變更製程，設備，採用低噪音機械及材料。\n(3)設隔音罩、隔音牆等隔離噪音。\n(4)消除機械鬆動現象。\n(5)減少物料之摩擦、衝擊。\n(6)降低流體流速或加裝消音設備。\n(7)減少對振動面之作用力，並減小振動面積。\n（二）行政管理\n(1)定期實施聽力圖檢查，可及早發現聽力是否受影響。\n(2)控制勞工於高噪音場所暴露時間。\n(3)正確配戴耳塞、耳罩等防音防護具。"},
{"id": "sk-cc-52-07", "topic": "第 52 次（96.11.18）", "code": "52-07", "n": 52, "q": "有一高壓氣體事業單位，計劃設置儲存能力 3000 公斤以上丙稀高壓氣體儲槽(示意圖如下附圖)，A、B 兩座球形槽及一座儲存能力 300 立方公尺以上氧氣臥型槽 C 槽，其中 A 槽直徑 16 公尺、B 槽直徑 8 公尺、C 槽軸向直徑 4公尺，試問：下列各槽間安全距離至少為多少公尺才合格？(10 分；答案請列出計算式)\n(一) A 槽、B 槽間安全距離？\n(二) A 槽、C 槽間安全距離？\n(三) C 槽、B 槽間安全距離？", "ans": "", "sol": "依高壓氣體勞工安全規則第三十五條「自儲存能力在三百立方公尺或三千公斤以上之可燃性氣體儲槽外面至其他可燃性氣體或氧氣儲槽間應保持一公尺或以該儲槽、其他可燃性氣體儲槽或氧氣儲槽之最大直徑和之四分之一以上較大者之距離。」\n(一) A 槽、B 槽間安全距離＝（A 槽直徑＋B 槽直徑）× 1/4\n＝（16 公尺＋8 公尺）× 1/4＝6 公尺\n(二) A 槽、C 槽間安全距離＝（A 槽直徑＋C 槽直徑）× 1/4\n＝（16 公尺＋4 公尺）× 1/4＝5 公尺\n(三) C 槽、B 槽間安全距離＝（C 槽直徑＋B 槽直徑）× 1/4\n＝（4 公尺＋8 公尺）× 1/4＝3 公尺", "fig": "圖：A槽、B槽為兩座球形儲槽，A槽在左且較大，B槽在右且較小；C槽為下方之臥型圓筒儲槽。"},
{"id": "sk-cc-52-08", "topic": "第 52 次（96.11.18）", "code": "52-08", "n": 52, "q": "請列舉出移動式起重機的安全裝置。(10 分)", "ans": "", "sol": "1.過捲揚預防裝置\n2.過負荷預防裝置\n3.制動器\n4.安全閥\n5.吊鉤防滑裝置\n6.其他重要安全裝置：如外伸撐座、旋能固鎖裝置、捲筒能數計、亂捲預防裝置、風向風速計等。"},
{"id": "sk-cc-52-09", "topic": "第 52 次（96.11.18）", "code": "52-09", "n": 52, "q": "下表為附圖中導管內風扇上游\n1、2 及下游\n3、4 四個測點所測得空氣壓力（air pressure）值，試求表中 a、b、c、d 四處之相關壓力值（請列明其計算過程）。(10 分)", "ans": "", "sol": "全壓（P_{T}）、靜壓（P_{S}）、動壓或速度壓（P_{V}）之間關係如下：\nP_{S}（mmH₂O）＋P_{V}（mmH₂O）＝P_{T}（mmH₂O）\n（一）a 處之空氣壓力值＝（-7.40）＋（2.00）＝-5.40（mmH₂O）\n（二）b處之空氣壓力值＝（-6.60）－（-8.60）＝+2.00（mmH₂O）\n（三）c 處之空氣壓力值＝（+7.90）－（+2.00）＝+5.90（mmH₂O）\n（四）d處之空氣壓力值＝（+6.10）－（+4.10）＝+2.00（mmH₂O）", "fig": "圖：導管內氣流由左向右（→），風扇設於導管中段；上游依序標示測點1、2，下游依序標示測點3、4。\n空氣壓力(mm H₂O)\n| 測點 | 全壓(P_{T}) | 靜壓(P_{S}) | 動壓(P_{V}) |\n| --- | --- | --- | --- |\n| 1 | (a) | -7.40 | +2.00 |\n| 2 | -6.60 | -8.60 | (b) |\n| 3 | +7.90 | (c) | +2.00 |\n| 4 | +6.10 | +4.10 | (d) |"},
{"id": "sk-cc-52-10", "topic": "第 52 次（96.11.18）", "code": "52-10", "n": 52, "q": "試述容許濃度使用上應注意事項。(10 分)", "ans": "", "sol": "(一) 勞工作業環境空氣中有害物容許濃度使用上應注意事項：\n1.僅作為作業環境改善及管理之依據。\n2.不適宜供作判斷下列事項之用：\na.以二種不同有害物之容許濃度比作為毒性之相關指標。\nb.非工作場所之空氣污染指標。\nc.職業疾病鑑定之唯一依據。\n(二)勞工作業環境空氣中有害物之濃度使用上應符合下列規定：\n1、全程工作日之時量平均濃度不得超過相當「八小時日時量平均容許濃度」。\n2、任何一次連續十五分鐘內之平均濃度不得超過「短時間時量平均容許度」。\n3、任何時間均不得超過「最高容許濃度」。"},
{"id": "sk-cc-53-01", "topic": "第 53 次（97.3.30）", "code": "53-01", "n": 53, "q": "(一)依勞工安全衛生設施規則規定，那些有害作業環境之工作場所，雇主應禁止非從事作業有關人員進入？(7分)\n(二)雇主未實施作業環境測定，經檢查機構通知限期改善而不如期改善，其處罰規定為何？(3分)", "ans": "", "sol": "(一)一、處置大量高熱物體或顯著濕熱之場所。\n二、處置大量低溫物體或顯著寒冷之場所。\n三、強烈微波、射頻波或雷射等非游離輻射之場所。\n四、氧氣濃度未滿百分之十八之場所。\n五、有害物超過容許濃度之場所。\n六、處置特殊有害物之場所。\n七、生物病原體顯著污染之場所。\n(二)可處新臺幣三萬元以上六萬元以下罰鍰。", "old": 1},
{"id": "sk-cc-53-02", "topic": "第 53 次（97.3.30）", "code": "53-02", "n": 53, "q": "依營造安全衛生設施標準規定，請列出雇主對於施工構台及高度5公尺以上施工架之構築，應辦理事項？(10分)", "ans": "", "sol": "依營造安全衛生設施標準第四十條規定:\n(一)雇主對於施工構台及高度五公尺以上施工架之構築，應由專任工程人員或指定專人事先依預期施工時之最大荷重，依結構力學原理妥為安全設計，並簽章確認強度計算書。\n(二)雇主對前項施工構台及施工架之構築，應繪製施工圖說，並建立按施工圖說施作之查核機制；設計、施工圖說、查驗等相關資料及簽章確認紀錄，於施工構台及施工架未拆除前，應妥存備查。\n(三)前二項之設計、施工圖說等資料，由委外設計者提供時，雇主應責成所僱之專任工程人員依實際需要檢核，並簽章確認；有變更設計時，其強度計算書及施工圖說應重新製作。"},
{"id": "sk-cc-53-03", "topic": "第 53 次（97.3.30）", "code": "53-03", "n": 53, "q": "依勞工安全衛生法令規定，物質安全資料表應含有十六項內容，試列舉其中十項 (10 分)", "ans": "", "sol": "(1)物品與廠商資料。 (2)成分辨識資料。\n(3)危害辨識資料。 (4)急救措施。\n(5)滅火措施。 (6)洩漏處理方法。\n(7)安全處置與儲存方法。 (8)暴露預防措施。\n(9)物理及化學性質。 (10)安定性及反應性。\n(11)毒性資料。 (12)生態資料。\n(13)廢棄處置方法。 (14)運送資料。\n(15)法規資料。 (16)其他資料。\n(以上除第 16 項外可任選十項作答)", "old": 1},
{"id": "sk-cc-53-04", "topic": "第 53 次（97.3.30）", "code": "53-04", "n": 53, "q": "事業單位為避免勞工發生失誤操作危害，可針對事業的各項作業進行工作安全分析，分別建立其安全作業標準，請問：\n(一)依法令規定，擬定安全作業標準係屬何者之責任？(2分)\n(二)擬定一份五欄式安全作業標準應包含那五個要項？(5分)\n(三)依法令規定，擬定安全作業標準後如何實施教導？(3分)", "ans": "", "sol": "(一)依勞工安全衛生組織管理及自動檢查辦法規定，擬定安全作業標準係屬雇主之責任。\n(二)擬定一份五欄式安全作業標準應包含下列五個要項：\n1.作業步驟 2.工作方法 3.危險因素 4.安全對策 5.事故處理。\n(三)依法令規定，擬定安全作業標準後應採取下列措施實施教導：\n1.納入勞工安全衛生工作守則內,公告週知,並教導令勞工遵行。（勞安法細則 27）\n2.列入對新僱勞工或在職勞工於變更工作前之一般安全衛生教育訓練課程內教導之。（勞工安全衛生教育訓練規則附表十四）\n3.列入對各級業務主管人員於新僱或在職於變更工作前之一般安全衛生教育訓練課程內教導之。（勞工安全衛生教育訓練規則附表十四）", "old": 1},
{"id": "sk-cc-53-05", "topic": "第 53 次（97.3.30）", "code": "53-05", "n": 53, "q": "物料之堆放，應注意那些事項？(10分)", "ans": "", "sol": "依勞工安全衛生設施規則規定，雇主對物料之堆放，應依下列規定：\n一、不得超過堆放地最大安全負荷。\n二、不得影響照明。\n三、不得妨礙機械設備之操作。\n四、不得阻礙交通或出入口。\n五、不得減少自動灑水器及火警警報器有效功用。\n六、不得妨礙消防器具之緊急使用。\n七、以不倚靠牆壁或結構支柱堆放為原則。並不得超過其安全負荷。", "old": 1},
{"id": "sk-cc-53-06", "topic": "第 53 次（97.3.30）", "code": "53-06", "n": 53, "q": "解釋下列職業安全衛生管理系統各項名詞為何：\n(一)危害；\n(二)事故；\n(三)風險；\n(四)風險評估；\n(五)被動式監督。 (10分)", "ans": "", "sol": "(一)危害：能對人體造成傷害或有損健康的潛在因素。\n(二)事故：與工作有關或工作過程中發生，但未造成人員傷害的不安全事件。\n(三)風險：危害事件發生的可能性與其對人員造成傷害或危害健康的嚴重度的結合。\n(四)風險評估：評估危害在既有且適當控制措施下之風險，並決定其風險是否可接受的過程。\n(五)被動式監督：對因危害和風險的預防與控制措施、職業安全衛生管理系統的失誤而引起的傷病、不健康和事故進行檢查、辨識的過程。"},
{"id": "sk-cc-53-07", "topic": "第 53 次（97.3.30）", "code": "53-07", "n": 53, "q": "在可能缺氧環境之作業場所進行氧氣濃度測定時，須注意那些事項？(10分)", "ans": "", "sol": "測定人員在可能缺氧環境之作業場所進行氧氣濃度測定時，須注意下列事項：\n(一)測定人員應充分熟悉各種缺氧危險場所之測定方法及儀器操作方式。\n(二)測定人員應使用必要之空氣呼吸器、氧氣呼吸器或輸氣管面罩等呼吸防護具及防止墜落之安全帶、安全索與其他必要之防護具。\n(三)測定時應有兩人，一人施測，另一人為輔助監視人員，在旁監視及協助。\n(四)在有墜落之虞的處所施測時，應置備及使用梯子、安全帶或救生索。\n(五)在有甲烷可能存在場所，不能使用會放出壓縮氧氣的呼吸防護具。\n(六)照明設備及電動器具應附有固定式或攜帶式之防爆型的保護裝置。"},
{"id": "sk-cc-53-08", "topic": "第 53 次（97.3.30）", "code": "53-08", "n": 53, "q": "在機械安全的防護方法中，連鎖法的防護須具備那三項要點？(6 分)依使用原理(2 分)及裝置之形狀(2 分)各可分為那些種類？", "ans": "", "sol": "(一) 連鎖法的防護須具備下列三項要點:\n1.機器操作時，必須防護危險部份。\n2.機器停止後，防護始得開啟或取下。\n3.連鎖如失效，機器即不能操作。\n(二) 依使用原理可分為機械連鎖及電氣連鎖兩種。\n(三) 依裝置之形狀可分為罩式、門式及障礙式等連鎖方式。"},
{"id": "sk-cc-53-09", "topic": "第 53 次（97.3.30）", "code": "53-09", "n": 53, "q": "下列為丁酮作業環境測定資料：採樣時溫度25℃，氣壓760mmHg，採樣流速100 mL/min，計採8小時，實驗室分析結果為 4.8 mg，其PEL=200 ppm，分子量 72。\n(一)試以mg/m³表示其時量平均濃度。(4分)\n(二)試以ppm表示其時量平均濃度‧(4分)\n(三)是否符合法定容許濃度標準(PEL)？(2分)", "ans": "", "sol": "（一）丁酮係屬第二種有機溶劑，於 25°C，氣壓 760mmHg之一大氣壓實施八小時單一樣本連續採樣，共採樣：\n100 ml / min × 60min × 8 ＝ 48000 ml ＝ 0.048 m³\n勞工丁酮之暴露濃度＝ 4.8 mg ÷ 0.048 m³ ＝ 100 mg/m³\n（二）該勞工暴露之A(ppm)＝(24.45÷ M) × B mg/m³＝(24.45 ÷ 72)×100\n＝ 34 ppm\n（三）因丁酮法定容許濃度 PEL=200 ppm，故符合法定容許濃度標準規定。"},
{"id": "sk-cc-53-10", "topic": "第 53 次（97.3.30）", "code": "53-10", "n": 53, "q": "某一勞工暴露於噪音之測定結果如下：\n08：00 ~ 12：00 穩定性噪音，L_{A} = 90 dBA\n13：00 ~ 15：00 變動性噪音，噪音劑量 = 50％\n15：00 ~ 17：00 穩定性噪音，L_{A} = 85 dBA\n(一)試評估其暴露是否符合法令規定？(5分)‧\n(二)暴露之八小時日時量平均音壓級為多少分貝？(5分)。", "ans": "", "sol": "(一)D ＝ 4 / 8 ＋ 50 % ＋ 2 / 16 ＝ 1.13 ＞ 1上列暴露劑量和大於一超出容許暴露劑量，不符合法令規定。\n(二)暴露之八小時日時量平均音壓級 = 16.61 1og D + 90 分貝\n＝16.61 1og 1.13 ＋ 90 ＝ 90.88（dB）"},
{"id": "sk-cc-54-01", "topic": "第 54 次（97.7.27）", "code": "54-01", "n": 54, "q": "依起重升降機具安全規則規定，雇主對於移動式起重機之使用，以吊物為限，不得乘載或吊升勞工從事作業。但從事貨櫃裝卸、船舶維修、高煙囪施工等尚無其他安全作業替代方法，或臨時性、小規模、短時間、作業性質特殊，經採取防止墜落等措施者，不在此限。請問上述但書所定之防止墜落措施，應辦理事項包括那四項？(10 分)", "ans": "", "sol": "依照 97.5.8 修訂之【起重升降機具安全規則】第三十五條規定:應辦理事項如下：\n一、以搭乘設備乘載或吊升勞工，並防止其翻轉及脫落。\n二、使勞工佩戴安全帶或安全索。\n三、搭乘設備自重加上搭乘者、積載物等之最大荷重，不得超過該起重機作業半徑所對應之額定荷重之百分五十。\n四、搭乘設備下降時，採動力下降之方法。"},
{"id": "sk-cc-54-02", "topic": "第 54 次（97.7.27）", "code": "54-02", "n": 54, "q": "依營造安全衛生設施標準規定，雇主對於高度二公尺以上之工作場所，勞工作業有墜落之虞者，應依規定訂定墜落災害防止計畫，採取那些適當墜落災害防止設施？ (10分)", "ans": "", "sol": "依【營造安全衛生設施標準】第十七條規定應採取適當墜落災害防止設施:\n一、經由設計或工法之選擇，儘量使勞工於地面完成作業以減少高處作業項目。\n二、經由施工程序之變更，優先施作永久構造物之上下昇降設備或防墜設施。\n三、設置護欄、護蓋。\n四、張掛安全網。\n五、使勞工佩掛安全帶。\n六、設置警示線系統。\n七、限制作業人員進入管制區。\n八、對於因開放邊線、組模作業、收尾作業等及採取第一款至第五款規定之設施致增加其作業危險者，應訂定保護計畫並實施。"},
{"id": "sk-cc-54-03", "topic": "第 54 次（97.7.27）", "code": "54-03", "n": 54, "q": "依勞工安全衛生教育訓練規則規定，雇主對擔任下列工作之勞工，應依其工作性質，每多少年至少施以多少小時之勞工安全衛生在職教育訓練？(10分)\n(一) 勞工安全衛生業務主管。\n(二) 製程安全評估人員。\n(三) 有害作業主管。\n(四) 堆高機作業人員。\n(五) 勞工安全衛生委員會成員。", "ans": "", "sol": "依【勞工安全衛生教育訓練規則】第十七條規定: 雇主對擔任下列工作之勞工，應依其工作性質，定期辦理勞工安全衛生在職教育訓練：\n(一) 勞工安全衛生業務主管（每二年六小時）\n(二) 製程安全評估人員（每三年六小時）\n(三) 有害作業主管（每三年六小時）\n(四) 堆高機作業人員（每三年三小時）\n(五) 勞工安全衛生委員會成員（每三年三小時）", "old": 1},
{"id": "sk-cc-54-04", "topic": "第 54 次（97.7.27）", "code": "54-04", "n": 54, "q": "一般緊急應變計畫中，緊急應變包括那五個編組？(10 分)", "ans": "", "sol": "(一) 通報組\n(二) 滅火組\n(三) 避難引導組\n(四）緊急救護組\n(五）安全防護組"},
{"id": "sk-cc-54-05", "topic": "第 54 次（97.7.27）", "code": "54-05", "n": 54, "q": "依勞工安全衛生組織管理及自動檢查辦法規定，請說明下列組織及人員之職責。（10 分）\n(一) 勞工安全衛生管理單位\n(二) 勞工安全衛生委員會\n(三) 置有勞工安全(衛生)管理師、勞工安全衛生管理員事業單位之勞工安全衛生業務主管\n(四) 勞工安全(衛生)管理師、勞工安全衛生管理員\n(五) 工作場所負責人及各級主管", "ans": "", "sol": "【勞工安全衛生組織管理及自動檢查辦法規定】第五之一條規定：\n(一) 勞工安全衛生管理單位：擬訂、規劃、督導及推動安全衛生管理事項，並指導有關部門實施。\n(二) 勞工安全衛生委員會：對雇主擬訂之安全衛生政策提出建議，並審議、協調、建議安全衛生相關事項。\n(三) 置有勞工安全(衛生)管理師、勞工安全衛生管理員事業單位之勞工安全衛生業務主管：主管及督導安全衛生管理事項。\n(四) 勞工安全(衛生)管理師、勞工安全衛生管理員：擬訂、規劃及推動安全衛生管理事項，並指導有關部門實施。\n(五) 工作場所負責人及各級主管：依職權指揮、監督所屬執行安全衛生管理事項，並協調及指導有關人員實施。", "old": 1},
{"id": "sk-cc-54-06", "topic": "第 54 次（97.7.27）", "code": "54-06", "n": 54, "q": "勞工衛生之主要工作為危害之認知、評估與控制，請問在危害認知中危害因子一般分為那四大類？(4 分)每類各舉三例？(6 分)", "ans": "", "sol": "1.物理性危害因子：（1）高溫作業：熱中暑（2）噪音作業：聽力損失（3）振動作業：白手病。\n2.化學性危害因子：（1）鉛中毒：鉛齒齦（2）鉻中毒：鼻中膈彎曲（3）錳中毒：巴金森氏症（4）苯中毒：白血病（5）鎘中毒：痛痛病。\n3.生物性危害因子：（1）醫護人員為照顧病患感染愛滋病（2）礦工感染鉤蟲病（3）飼養猪隻感染布魯斯熱。\n4.人因工程危害因子：（1）不當操作姿勢操作設備引起下背部痛（2）長期負重造成脊椎傷害（3）高重複性工作造成腕道症候群。"},
{"id": "sk-cc-54-07", "topic": "第 54 次（97.7.27）", "code": "54-07", "n": 54, "q": "試述起重機類危險性機械的災害種類有那些？又其對應之災害原因為何？(10分)", "ans": "", "sol": "（一）物體飛落：係指在起重吊掛的過程中，因鋼索斷裂、吊具不當、吊掛方式不當、防脫裝置失效、過捲揚裝置失效或人為操作疏失而導致吊舉物脫落。\n（二）被夾、被撞：多因吊舉物滑脫傾倒被挾壓、遭吊舉物之撞擊或造成地面上物體的翻倒，及與機體接觸等發生人員被挾壓傷亡災害。另吊舉物吊升過程中，吊舉物離地產生瞬間滑移，人員如未退離至安全距離，易發生被撞擊災害。\n（三）墜落：由於人員於桁架上維修保養時，未確實實施作業管制，桁架尚未設護欄等防墜設施，或未使用安全帶、安全母索等防護具，不慎自機體或作業處墜落。\n（四）物體倒塌崩塌：由於吊舉物堆疊不良、未限制高度或未設置擋樁等設施而發生。\n（五）感電：原因大多由於實拖起重機維修保養時，維修人員因誤觸裸銅線，或因電氣設備電線之絕緣破壞，人體觸及外部高低壓裸線，或人體直接觸及活線造成。"},
{"id": "sk-cc-54-08", "topic": "第 54 次（97.7.27）", "code": "54-08", "n": 54, "q": "預防熱暴露危害，在輻射熱與對流熱方面各有那些工程改善方法？(10分)", "ans": "", "sol": "(一) 輻射熱工程改善方法：除從熱源改善外，可從輻射源與作業人員間利用屏障、隔離等簡單原理以遮斷輻射熱直接傳遞特性而達降低暴露水準，惟遮蔽屏障不得阻礙環境空氣流動，例如利用光亮之鋁板、不銹鋼板或其他金屬板之反射屏障；很容易吸收紅外線之吸收屏障;使用可吸熱或可反射紅外線之特殊玻璃或金屬網以降低紅外線輻射傳遞之透明屏障:或利用鋁處理之編織物之可撓性屏障。\n(二)對流工程改善方法：可利用風扇以增加空氣流動，因改變空氣流動速度能增加對流熱交換與汗水蒸發速率，而使工作人員感覺較為涼快。"},
{"id": "sk-cc-54-09", "topic": "第 54 次（97.7.27）", "code": "54-09", "n": 54, "q": "請列舉四項使勞工從事設有採光罩之屋頂作業時，雇主應提供並確保適當地使用之墜落防護裝置。(10 分)", "ans": "", "sol": "1.於石綿板、鐵皮板、瓦、木板、茅草、塑膠等材料構築之屋頂從事作業時，應於屋架上設置適當強度，且寬度在 30 公分以上之踏板或裝設安全護網為防止墜落，以防止踏穿屋頂發生墜落災害。\n2.對於高差超過一．五公尺以上之場所作業時，應設置安全上下之設備。\n3.對於在高度二公尺以上之處所進行作業，有墜落之虞者，應以架設施工架或其他方法設置工作台。\n4.對於高度在二公尺以上之工作場所邊緣及開口部份，有遭受墜落危險之虞者，應設有適當強度之圍欄、握把、覆蓋等防護措施。"},
{"id": "sk-cc-54-10", "topic": "第 54 次（97.7.27）", "code": "54-10", "n": 54, "q": "工作場所每一勞工所佔立方公尺數在5.7 至14.2 之間時，每分鐘每一勞工所需之新鮮空氣應在0.4 立方公尺以上。當每一勞工所佔立方公尺數為8，請問該工作場所之新鮮空氣換氣率為每小時至少多少次？(10 分)", "ans": "", "sol": "每一勞工所佔立方公尺數為 8，仍符合每分鐘每一勞工所需之新鮮空氣應在0.4 立方公尺以上之規定，換算成每小時則為 24 立方公尺，故以個人所站空間為 8 立方公尺來計算，所以新鮮空氣換氣率為每小時至少應為 3 次以上。"},
{"id": "sk-cc-55-01", "topic": "第 55 次（97.11.16）", "code": "55-01", "n": 55, "q": "依勞工安全衛生組織管理及自動檢查辦法規定，雇主應依事業規模、特性，訂定勞工安全衛生管理計畫，請列舉10 項應執行之勞工安全衛生事項？(10分)", "ans": "", "sol": "依照 97.1.9 修訂之【勞工安全衛生組織管理及自動檢查辦法】第十二條之一規定:雇主應依其事業規模、特性，訂定勞工安全衛生管理計畫，執行下列勞工安全衛生事項：(任選十項作答)\n1. 工作環境或作業危害之辨識、評估及控制。\n2. 機械、設備或器具之管理。\n3. 危險物與有害物之標示及通識。\n4. 有害作業環境之採樣策略規劃與測定。\n5. 危險性工作場所之製程或施工安全評估事項。\n6. 採購管理、承攬管理與變更管理事項。\n7. 安全衛生作業標準之訂定。\n8. 定期檢查、重點檢查、作業檢點及現場巡視。\n9. 安全衛生教育訓練。\n10.個人防護具之管理。\n11.健康檢查、健康管理及健康促進事項。\n12.安全衛生資訊之蒐集、分享與運用。\n13.緊急應變措施。\n14.職業災害、虛驚事故、影響身心健康事件之調查處理與統計分析。\n15.安全衛生管理記錄與績效評估措施。", "old": 1},
{"id": "sk-cc-55-02", "topic": "第 55 次（97.11.16）", "code": "55-02", "n": 55, "q": "依勞工安全衛生設施規則規定，雇主對於機械之掃除、上油、檢查、修理或調整作業，應採取措施為何？(10 分)", "ans": "", "sol": "依 96.2.14 新修訂之【勞工安全衛生設施規則】第五十七條規定:\n雇主對於機械之掃除、上油、檢查、修理或調整有導致危害勞工之虞者，應停止相關機械運轉及送料。為防止他人操作該機械之起動等裝置或誤送料，應採上鎖或設置標示等措施，並設置防止落下物導致危害勞工之安全設備與措施。\n前項機械停止運轉時，有彈簧等彈性元件、液壓、氣壓或真空蓄能等殘壓引起之危險者，雇主應採釋壓、關斷或阻隔等適當設備或措施。\n第一項工作必須在運轉狀態下施行者，雇主應於危險之部分設置護罩、護圍等安全設施或使用不致危及勞工身體之足夠長度之作業用具。對連續送料生產機組等，前項機械停止運其部分單元停機有困難，且危險部分無法設置護罩或護圍者，雇主應設置具有安全機能設計之裝置，或採取必要安全措施及書面確認作業方式之安全性，並指派現場主管在場監督。", "old": 1},
{"id": "sk-cc-55-03", "topic": "第 55 次（97.11.16）", "code": "55-03", "n": 55, "q": "依營造安全衛生設施標準規定，雇主為防止勞工有遭受墜落危險之虞，對開口部分，如採用設置護蓋方式辦理，試列舉5 項相關規定？(10 分)", "ans": "", "sol": "依【營造安全衛生設施標準】第二十一條規定:雇主設置之護蓋，應依下列規定辦理：(任選五項作答)\n1.應具有能使人員及車輛安全通過之強度。\n2.應以有效方法防止滑溜、掉落、掀出或移動。\n3.供車輛通行者，得以車輛後軸載重之二倍設計之，並不得妨礙車輛之正常通行。\n4.為柵狀構造者，柵條間隔不得大於三公分。\n5.上面不得放置機動設備或超過其設計強度之重物。\n6.臨時性開口處使用之護蓋，表面漆以黃色並書以警告訊息。"},
{"id": "sk-cc-55-04", "topic": "第 55 次（97.11.16）", "code": "55-04", "n": 55, "q": "某屬第二類事業之總公司設於臺北市，勞工計有555 人，另於南部科學管理園區之分公司勞工人數有333 人，該公司依法應於總機構及地區性事業如何設置勞工安全衛生管理單位及人員？又該等人員是否應專職？(10 分)", "ans": "", "sol": "一、總機構：總人數為555＋333＝888人，所以應設直接隸屬雇主之一級管理單位，內置甲種勞工安全衛生業務主管及勞工安全衛生管理員各一人以上。其中至少1人應為專職。\n二、南部科學管理園區之分公司：人數為 333 人，應設屬於該分公司一級單位之勞工安全衛生管理單位，內置甲種勞工安全衛生業務主管及勞工安全衛生管理員各一人，其中至少 1 人應為專職。", "old": 1},
{"id": "sk-cc-55-05", "topic": "第 55 次（97.11.16）", "code": "55-05", "n": 55, "q": "請問 N95 防塵口罩所稱之“N”及“95”各代表何種意義？（10 分）", "ans": "", "sol": "N ：N 型表非抗油之防塵口罩，其濾材僅適用於防護固體微粒。\n95：表示該防塵口罩之防護效果為 95 級，其對特定測試微粒的過濾效率為95%（穿透率小於 5 %）。"},
{"id": "sk-cc-55-06", "topic": "第 55 次（97.11.16）", "code": "55-06", "n": 55, "q": "勞工懷疑自己罹患職業病，欲向雇主申請職業災害補償，請問勞雇雙方可循何程序處理？(10 分)", "ans": "", "sol": "", "fig": "流程：勞工疑似罹患職業病 → 醫師（職業疾病／非職業疾病） → 診斷結果勞雇任一方有無異議。\n1.無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償。\n2.無異議且不屬職業疾病 → 結案。\n3.有異議 → 直轄市、縣（市）政府認定；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案。\n4.直轄市、縣（市）政府認定困難，或勞雇任一方對認定有異議 → 行政院勞工委員會（職業疾病鑑定委員會）；勞工保險機構審定職業疾病認有必要時，亦送行政院勞工委員會。\n5.行政院勞工委員會 → 診斷結果勞雇任一方有無異議；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案；有異議 → 法律訴訟。", "note": "本題有流程圖，內容已轉錄於 fig。"},
{"id": "sk-cc-55-07", "topic": "第 55 次（97.11.16）", "code": "55-07", "n": 55, "q": "請解釋下列名詞：\n(一) 矯正措施（2 分）\n(二) 預防措施（2 分）\n(三) 八小時日時量平均容許濃度（2 分）\n(四) 局限空間（2 分）\n(五) ppm (2 分)。", "ans": "", "sol": "（一）、矯正措施－消除所偵知之不符合相關工作標準，實務，程序，法規要求等及職業安全衛生管理系統要求或不期待之情況原因之措施。\n(依據：『臺灣職業安全衛生管理系統驗證規範總說明3.4』)\n（二）、預防措施－消除潛在之不符合相關工作標準，實務，程序，法規要求等及職業安全衛生管理系統要求或其他不期待之情況原因之措施。\n(依據：『臺灣職業安全衛生管理系統驗證規範總說明3.18』)\n（三）、八小時日時量平均容許濃度－為勞工每天工作八小時，一般勞工重複曝露此濃度以下，不致有不良反應者之有害物濃度值，以 PEL－TWA8h 表示。\n（四）、局限空間－指非供勞工在其內部從事經常性作業，勞工進出方法受限制，且無法以自然通風來維持充分、清淨空氣之空間。（設施則19-1）\n（五）、ppm－每立方公尺空氣中有害物之立方公分數，以cm³/m³表示。"},
{"id": "sk-cc-55-08", "topic": "第 55 次（97.11.16）", "code": "55-08", "n": 55, "q": "「規劃與實施」為臺灣職業安全衛生管理系統五大要素之一，試問其涵蓋內容包括那些？(10 分)", "ans": "", "sol": "「規劃與實施」涵蓋內容應包括下列八項：\n（一）先期審查\n（二）系統規劃、建立與實施\n（三）職業安全衛生目標\n（四）預防與控制措施\n（五）變更管理\n（六）緊急應變措施\n（七）採購\n（八）承攬"},
{"id": "sk-cc-55-09", "topic": "第 55 次（97.11.16）", "code": "55-09", "n": 55, "q": "某營造公司僱用勞工200 人，十月份總經歷工時為30,000 小時，其十月份全月事故之紀錄記載十月七日下午四時發生擋土牆崩塌，致甲勞工及乙勞工當場死亡，丙勞工受傷住院，十月二十日恢復工作，丁勞工受傷回家休養，翌日八時恢復上班工作，試計算該公司該月失能傷害頻率及失能傷害嚴重率。(10 分)", "ans": "", "sol": "總經歷工時：30,000 小時職災總人次數：1 次 × 3 人＝3 人次(勞工丁受傷不足一日，不予列計)職災總損失日數：6,000日× 2人(甲及乙)＋12日（丙自十月八日至十九日）\n＝12,012 日\n失能傷害頻率(F.R)＝3 × 1,000,000 / 30,000 ＝100\n失能傷害嚴重率（S.R）＝12,012 × 1,000,000/30,000 ＝400,400"},
{"id": "sk-cc-55-10", "topic": "第 55 次（97.11.16）", "code": "55-10", "n": 55, "q": "有一局部排氣系統，用以捕集製程上研磨作業所產生之粉塵，試運轉時測得導管內某點之全壓為 -8.0mmH₂O，靜壓為 -12mmH₂O。\n(一)請計算導管內之空氣平均輸送風速為多少m/s？(5 分)\n(二)若此導管為一圓管，導管直徑20cm，則導管內之空氣流率為多少(m^{３}/s)？(5 分)", "ans": "", "sol": "(一)導管內之空氣平均輸送風速P_{V} ＝（V /4.04）²\n因為 P_{T} ＝P_{S}＋P_{V} 即 -8.0mmH₂O＝-12mmH₂O＋P_{V}，\n所以 P_{V}＝4mmH₂O，因此V²＝4 × 4.04² 所以V ＝8.08 m/s\n(二)導管為一圓管，導管直徑 20cm，A＝πr² ＝3.1416 ×（20/2）²＝314.16cm²＝0.031416 m²\n所以導管內之空氣流率Q＝V×A＝8.08 m/s x 0.031416 m²≒0.254 m³/s"},
{"id": "sk-cc-56-01", "topic": "第 56 次（98.3.29）", "code": "56-01", "n": 56, "q": "請依勞工安全衛生法令解釋下列各項：(10分)\n(一)職業災害；\n(二)工作場所；\n(三)共同作業；\n(四)工作場所負責人；\n(五)局限空間。", "ans": "", "sol": "(一)職業災害：係稱勞工就業場所之建築物、設備、原料、材料、化學物品、蒸氣、氣體、粉塵等或作業活動及其他職業上原因所發生之勞工疾病、傷害、殘廢或死亡災害。\n(二)工作場所：係指在就業場所中，接受雇主或代理雇主指示處理勞工事務之人所能支配、管理之場所。\n(三)共同作業：係指事業單位與承攬人、再承攬人所僱用之勞工於同一期間、同一工作場所從事工作。\n(四)工作場所負責人：係於該工作場所中代表雇主從事管理、指揮或監督勞工從事工作之人。\n(五)局限空間：係指非供勞工在其內部從事經常性作業，勞工進出方法受限制，且無法以自然通風來維持充分、清淨空氣之空間。", "old": 1},
{"id": "sk-cc-56-02", "topic": "第 56 次（98.3.29）", "code": "56-02", "n": 56, "q": "依勞工安全衛生組織管理及自動檢查辦法規定，第一類事業勞工人數在三百人以上之事業單位，應參照中央主機關所定之職業安全衛生管理系統指引，建立適合該事業單位之職業安全衛生管理系統，試述於採購管理與承攬管理上分別有那些相關規定？(10分)", "ans": "", "sol": "依 97.1.9 新修訂之【勞工安全衛生組織管理及自動檢查辦法】規定:\n（一）採購管理（第十二條之四）關於機械、器具、設備、物料、原料及個人防護具等之採購、租賃，其契約內容應有符合法令及實際需要之勞工安全衛生具體規範，並於驗收、使用前確認其符合規定。\n前項事業單位將營繕工程之施工、規劃、設計及監造等交付承攬或委託，其契約內容應有防止職業災害之具體規範，並列為履約要件。\n前二項執行紀錄，應保存三年。\n（二）承攬管理（第十二條之五）該類事業單位，以其事業之全部或一部分交付承攬或與承攬人分別僱用勞工於同一期間、同一工作場所共同作業時，除應依本法第十七條或第十八條規定辦理外，應就承攬人之安全衛生管理能力、職業災害通報、危險作業管制、教育訓練、緊急應變及安全衛生績效評估等事項，訂定承攬管理計畫，並促使承攬人及其勞工，遵守勞工安全衛生法令及原事業單位所定之勞工安全衛生管理事項。\n前項執行紀錄，應保存三年。", "old": 1},
{"id": "sk-cc-56-03", "topic": "第 56 次（98.3.29）", "code": "56-03", "n": 56, "q": "依勞工安全衛生設施規則規定，吊鍊及吊掛之鋼索分別在那些情況下不得作為起重升降機具之吊掛用具？( 10分)", "ans": "", "sol": "（一）吊鍊:\n1、延伸長度超過百分之五以上者。\n2、斷面直徑減少百分之十以上者。\n3、有龜裂者。\n（二）吊掛之鋼索:\n1、鋼索一撚間有百分之十以上素線截斷者。\n2、直徑減少達公稱直徑百分之七以上者。\n3、有顯著變形或腐蝕者。\n4、已扭結者。\n（三）吊鏈或未設環結之鋼索，其兩端非設有吊鉤、鉤環、鏈環或編結環首、壓縮環首者，不能作為起重機具之吊掛用具。", "old": 1},
{"id": "sk-cc-56-04", "topic": "第 56 次（98.3.29）", "code": "56-04", "n": 56, "q": "常溫下四氫化矽(矽甲烷)具有自燃性，於處理上，除應依高壓氣體相關法規規定辦理外，依勞工安全衛生設施規則規定應辦理那些事項？( 10分)", "ans": "", "sol": "依據：勞工安全衛生設施規則第 185 條之 1 規定，於處理上應辦理事項如下：\n一、氣體設備應具有氣密之構造及防止氣體洩漏之必要設施，並設置氣體洩漏檢知警報系統。\n二、氣體容器之閥門應具有限制最大流率之流率限制孔。\n三、氣體儲存於室外安全處所，如必須於室內儲存者，應置於有效通風換氣之處所，使用時應置氣瓶櫃內。\n四、未使用之氣體容器與供氣中之容器，應分隔放置。\n五、提供必要之個人防護具，並使勞工確實使用。\n六、避免使勞工獨操作。\n七、設置火災時，提供冷却用途之灑水設備。\n八、保持逃生路線通。", "old": 1},
{"id": "sk-cc-56-05", "topic": "第 56 次（98.3.29）", "code": "56-05", "n": 56, "q": "(一)何謂八小時日時量平均容許濃度？( 2分)\n(二)容許濃度使用上應注意事項為何？( 8分)", "ans": "", "sol": "(一)八小時日時量平均容許濃度（PEL－TWA8h）：為勞工每天工作八小時，一般勞工重複曝露此濃度之下，不致有不良反應者。\n(二)容許濃度使用上應注意事項：\n1.僅作為作業環境改善及管理之依據。\n2.不適宜供作判斷下列事項之用：\n（1）以二種不同有害物之容許濃度比作為毒性之相關指標。\n（2）非工作場所之空氣污染指標。\n（3）職業疾病鑑定之唯一依據。"},
{"id": "sk-cc-56-06", "topic": "第 56 次（98.3.29）", "code": "56-06", "n": 56, "q": "預防職業性肌肉骨骼傷害的有效方法，除工程改善外，亦可利用管理方式，減少人員暴露於肌肉骨骼傷害危險因子之機會，請列舉5種常用之行政管理手段。( 10分)", "ans": "", "sol": "常用之行政管理手段如下；（以下任選五項作答）\n一、變更貨物包裝設計、搬運方式：\n(1)改變物件的大小，把體積過大的貨物分裝成小包裝來減低重量。\n(2)考量貨品包裝的大小或形狀時，應顧及攜帶或抓握的方便性及省力性。\n(3)搬運時留意貨品上標示有關資料或標籤，如重量、重心位置或內容物成分等，適度調整搬運方式。\n(4)改善貨品排列堆疊方式，減少需伸長身體、彎腰、扭轉身體的姿勢，設法縮短徒手搬運距離。\n二、改變工作方法：\n(1)搬運或移動較大型、笨重及體積不同的物件，切勿逞強去搬運超過身體負荷的物品，建議使用機械設備搬運。\n(2)若沒有輔助機械設備供使用，可用集體搬運的方式，多人共同作業，減輕個人負擔，\n三、注意工作場所周圍環境：\n(1)維持光線充足，當搬運貨物時，先觀察來回路徑通道上有無任何阻擋行進的障礙物，避免跌倒。\n(2)事先瞭解擺放貨物的位置、高度，注意搬運或放下時的動作及安全。\n四、保持正確姿勢：\n(1)提舉重物保持背部挺直，緊握重物，盡量將重物靠近身體，運用強而有力的腿部肌肉慢慢站起來，避免將貨物的力量落在腰部。\n(2)拿取遠方物品時，需身體靠近拿取。\n五、足夠休息：\n工作之餘，需要有充足和適當的休息時間，避免連續作業身心方面過度疲勞，造成精神不集中或力量無法完全發揮而受傷。\n六、個人防護裝備使用：\n在長期重複使用人力進行搬運的情況下，可穿著各種防護裝備來保護身體容易受傷的部位，減少受傷的機會，如護腰、背架、護腕，護肘，護膝等。\n七、保健運動：\n經常做一些腰部肌力訓練與伸展運動等保健運動，可保持腰部柔軟性及反應力，增加肌肉力量。上肢、下肢的主要肌肉也必須進行適度的強化運動，來增加搬運的執行力，避免受傷。對曾經有受傷經歷的人，最好先諮詢醫生或治療師的意見。"},
{"id": "sk-cc-56-07", "topic": "第 56 次（98.3.29）", "code": "56-07", "n": 56, "q": "依勞工安全衛生設施規則之規定，雇主對於電路開路後從事該電路支持物、或接近該電路工作物之敷設、建造、檢查、修理、油漆等作業時，應於確認電路開路後，就該電路採取那些設施？( 10分)", "ans": "", "sol": "依據：勞工安全衛生設施規則第254條規定：\n一、開路之開關於作業中，應上鎖或標示「禁止送電」、「停電作業中」或設置監視人員監視之。\n二、開路後之電路如含有電力電纜、電力電容器等致電路有殘留電荷引起危害之虞者，應以安全方法確實放電。\n三、開路後之電路藉放電消除殘留電荷後，應以檢電器具檢查，確認其已停電，且為防止該停電電路與其他電路之混觸、或因其他電路之感應、或其他電源之逆送電引起感電之危害，應使用短路接地器具確實短路，並加接地。\n四、前款停電作業範圍如為發電或變電設備或開關場之一部分時，應將該停電作業範圍以藍帶或網加圍，並懸掛「停電作業區」標誌；有電部分則以紅帶或網加圍，並懸掛「有電危險區」標誌，以資警示。\n前項作業終了送電時，應事先確認從事作業等之勞工無感電之虞，並於拆除短路接地器具與紅藍帶或網及標誌後為之。", "old": 1},
{"id": "sk-cc-56-08", "topic": "第 56 次（98.3.29）", "code": "56-08", "n": 56, "q": "依危險物與有害物標示及通識規則規定，請問下列危害物質應標示之危害圖示為何？請以下列各危害圖式之英文代號答題，不用畫圖。( 10分)\n(一)致癌物質第 2 級。\n(二)有機過氧化物 C 型。\n(三)加壓氣體之壓縮氣體。\n(四)不穩定爆炸物。\n(五)氧化性固體第 1 級。", "ans": "", "sol": "(一)致癌物質第 2 級──( D )\n(二)有機過氧化物 C 型──( G )\n(三)加壓氣體之壓縮氣體──( E )\n(四)不穩定爆炸物──( H )\n(五)氧化性固體第 1 級──( F )", "fig": "圖式代號：A＝腐蝕（液體由試管滴到手及金屬）；B＝骷髏與交叉骨；C＝驚嘆號；D＝胸口有星狀標記之人形；E＝氣體鋼瓶；F＝圓圈上方火焰；G＝火焰；H＝爆炸。\n說明：以上各圖式之外框皆為紅色。"},
{"id": "sk-cc-56-09", "topic": "第 56 次（98.3.29）", "code": "56-09", "n": 56, "q": "(一)安全一行程式安全裝置應具有之機能為何？( 5分)\n(二)某一全轉式動力衝剪機械之離合器嚙合處數目有2個，且其曲柄軸旋轉一週所需時間為0.5 sec，若設置雙手起動式安全裝置，則其按鈕與危險界限間之距離至少為多少公分？( 5分)", "ans": "", "sol": "依據機械器具防護標準第 12 條及第 14 條規定：\n(一)安全一行程式安全裝置應具有之機能：\n1. 防護式安全裝置：滑塊、刃物或撞錘（以下簡稱滑塊等）在動作中，能使勞工身體不致介入危險界限之虞。\n2. 雙手操作式安全裝置、在手指自按下起動按鈕或操作控制桿（以下簡稱按鈕等，脫手後至該手達到危險界限前，能使滑塊等停止動作（安全一行程式安全裝置）。又，以雙手操作按鈕等，於滑塊等動作中，手離開按鈕等時手無法達到危險界限（雙手起動式安全裝置）。\n3. 感應式安全裝置：滑塊等在動作中，遇身體之一部接近危險界限時，能使滑塊等停止動作。\n4. 拉開式或掃除式安全裝置：遇身體之一部介入危險界限時，能隨著滑塊之動作使其脫離危險界限。\n(二) D：雙手起動式安全裝置者為自按鈕等至危險界限間之距離，以公厘表示。\nTm：手指離開按鈕等至滑塊抵達下死點時之最大時間，以毫秒表示。\nTm＝（1/2＋1/2）× 0.5 ＝0.5 sec＝ 500 毫秒\n因為 D >1.6Tm，所以按鈕與危險界限間之距離至少為 1.6×500＝800\n公厘＝80 公分"},
{"id": "sk-cc-56-10", "topic": "第 56 次（98.3.29）", "code": "56-10", "n": 56, "q": "有一外裝式無凸緣(flange)氣罩，開口面積為 1 平方公尺，請計算距離該氣罩開口中心線外 1 公尺處之捕捉風速（capture velocity），是氣罩開口處中心線風速之幾分之一？( 10分)【參考公式：Q=V(10X²+A)，應列出計算過程】", "ans": "", "sol": "假設開口處中心線風速為V₀，通風量不變為Q距離該氣罩開口中心線外 1 公尺處之捕捉風速為V₁V₀＝Q/(10X²+A)＝Q/(10×0²+1)＝Q\nV₁＝Q/(10X²+A)＝Q/(10×1²+1)＝1/11 Q\n所以 V₁＝1/11 V₀ ，即距離開口中心線外 1 公尺處之捕捉風速，是開口處中心線風速之十一分之一。"},
{"id": "sk-cc-57-01", "topic": "第 57 次（98.7.26）", "code": "57-01", "n": 57, "q": "依勞工安全衛生組織管理及自動檢查辦法之規定，雇主應依其事業規模、特性，訂定勞工安全衛生管理計畫，試說明該計畫應包括那些勞工安全衛生事項，請列舉10項。(10分)", "ans": "", "sol": "一、工作環境或作業危害之辨識、評估及控制。\n二、機械、設備或器具之管理。\n三、危險物與有害物之標示及通識。\n四、有害作業環境之採樣策略規劃與測定。\n五、危險性工作場所之製程或施工安全評估事項。\n六、採購管理、承攬管理與變更管理事項。\n七、安全衛生作業標準之訂定。\n八、定期檢查、重點檢查、作業檢點及現場巡視。\n九、安全衛生教育訓練。\n十、個人防護具之管理。\n十一、健康檢查、健康管理及健康促進事項。\n十二、安全衛生資訊之蒐集、分享與運用。\n十三、緊急應變措施。\n十四、職業災害、虛驚事故、影響身心健康事件之調查處理與統計分析。\n十五、安全衛生管理記錄與績效評估措施。\n（以上任選十項作答）", "old": 1},
{"id": "sk-cc-57-02", "topic": "第 57 次（98.7.26）", "code": "57-02", "n": 57, "q": "依勞工安全衛生設施規則之規定，雇主對於有車輛出入、使用道路作業、鄰接道路作業或有導致交通事故之虞之工作場所，應如何設置適當交通號誌、標示、柵欄或措施，請列舉5項。(10分)。", "ans": "", "sol": "一、交通號誌、標示應能使受警告者清晰獲知。\n二、交通號誌、標示或柵欄之控制處，須指定專人負責管理。\n三、新設道路或施工道路，應於通車前設置號誌、標示、柵欄、反光器、照明或燈具等設施。\n四、道路因受條件限制，永久裝置改為臨時裝置時，應於限制條件終止後即時恢復。\n五、使用於夜間之柵欄，應設有照明或反光片等設施。\n六、信號燈應樹立在道路之右側，清晰明顯處。\n七、號誌、標示或柵欄之支架應有適當強度。\n八、設置號誌、標示或柵欄等設施，尚不足以警告防止交通事故時，應置交通引導人員。\n（以上任選五項作答）", "old": 1},
{"id": "sk-cc-57-03", "topic": "第 57 次（98.7.26）", "code": "57-03", "n": 57, "q": "請依勞工安全衛生法令回答下列問題：\n(一)勞工安全衛生設施規則所稱可燃性氣體包括那些物質？(3分)\n(二)危險性設備包括那些設備？(3分)\n(三)何謂事業單位？(2分)\n(四)何謂就業場所？(2分)", "ans": "", "sol": "(一)可燃性氣體包括：\n1、氫。\n2、乙炔、乙烯。\n3、甲烷、乙烷、丙烷、丁烷。\n4、其他於一大氣壓下攝氏十五度時，具有可燃性之氣體。\n(二)危險性設備包括：\n1、鍋爐。\n2、壓力容器。\n3、高壓氣體特定設備。\n4、高壓氣體容器。\n5、其他經中央主管機關指定具有危險性之設備。\n(三)事業單位：勞工安全衛生法適用範圍內僱用勞工從事工作之機構。\n(四)就業場所：係指於勞動契約存續中，由雇主所提示，使勞工履行契約提供勞務之場所。", "old": 1},
{"id": "sk-cc-57-04", "topic": "第 57 次（98.7.26）", "code": "57-04", "n": 57, "q": "請回答下列問題：\n(一)局限空間作業主要危害？(5分)\n(二)雇主使勞工從事局限空間作業，如有危害之虞，應訂定危害防止計畫，其內容應包括那些事項？(5分)", "ans": "", "sol": "(一) 1.缺氧、中毒。2.感電。3.塌陷。4.被夾、被捲。5.火災、爆炸。\n(二)危害防止計畫，應依作業可能引起之危害訂定下列事項：\n1、局限空間內危害之確認。\n2、局限空間內氧氣、危險物、有害物濃度之測定。\n3、通風換氣實施方式。\n4、電能、高溫、低溫及危害物質之隔離措施及缺氧、中毒、感電、塌陷、被夾、被捲等危害防止措施。\n5、作業方法及安全管制作法。\n6、進入作業許可程序。\n7、提供之防護設備之檢點及維護方法。\n8、作業控制設施及作業安全檢點方法。\n9、緊急應變處置措施。"},
{"id": "sk-cc-57-05", "topic": "第 57 次（98.7.26）", "code": "57-05", "n": 57, "q": "試簡答下列問題：\n(一)噪音100分貝時容許暴露時間為何？(2分)\n(二)短時間時量平均容許濃度為多少時間之時量平均濃度不得超過之濃度？ (2分)\n(三)第一類事業之事業單位勞工人數在100人以上者，應設直接隸屬雇主之何種勞工安全衛生管理單位？(2分)\n(四)第二類事業之事業單位勞工人數在300人以上者，應設直接隸屬雇主之何種勞工安全衛生管理單位？(2分)\n(五)何謂職業安全衛生管理系統？(2分)", "ans": "", "sol": "(一) 2小時。\n(二)15分鐘。\n(三)專責一級勞工安全衛生管理單位。\n(四)一級勞工安全衛生管理單位。\n(五)係組織整體管理系統的一部分，用以發展及實施其職業安全衛生政策，並管理其職業安全衛生風險。", "old": 1},
{"id": "sk-cc-57-06", "topic": "第 57 次（98.7.26）", "code": "57-06", "n": 57, "q": "(一)請寫出失能傷害頻率(FR)及失能傷害嚴重率(SR)之計算公式。(5分)\n(二)某事業單位97年度之FR為40，SR為10,000，請依中央勞工主管機關之規定，計算該年度之總合傷害指數。(5分)", "ans": "", "sol": "(一)失能傷害頻率(F.R)＝失能傷害人次數 × 1,000,000 /總經歷工時\n失能傷害嚴重率（S.R）＝失能傷害總損失日數 × 1,000,000/總經歷工時\n(二)總合傷害指數＝√(失能傷害頻率×失能傷害嚴重率÷1000)\n＝√(40×10,000÷1000)\n＝20"},
{"id": "sk-cc-57-07", "topic": "第 57 次（98.7.26）", "code": "57-07", "n": 57, "q": "為防範HlNl新型流感等傳染病，雇主應提供肥皂等供勞工洗手。請說明洗手五步驟依序為何？(10分)", "ans": "", "sol": "1.濕：開水龍頭把手淋濕並抹上肥皂或洗手液。\n2.搓：肥皂或洗手液起泡後，將手心、手背、指縫搓揉 20 秒。\n3.沖：用清水將雙手沖洗乾淨。\n4.捧：捧水沖洗水龍頭後關閉水龍頭。\n5.擦：用乾淨的紙巾將手擦乾或用烘乾機將手烘乾。"},
{"id": "sk-cc-57-08", "topic": "第 57 次（98.7.26）", "code": "57-08", "n": 57, "q": "依我國職業安全衛生管理系統(TOSHMS)指引中之「預防與控制措施」項目要求，事業單位應建立及維持適當的程序，以持續辨識和評估各種影響員工安全衛生的危害及風險，試依優先順序說明其預防及控制之措施：(10分)", "ans": "", "sol": "1.清除危害及風險。\n2.經由工程控制或管理控制從源頭控制危害及風險。\n3.設計安全的作業制度，包括行政管理措施將危害及風險的影響減到最低。\n4.當綜合上述方法仍然不能控制殘餘的危害及風險時，雇主應免費提供適當的個人防護具，並採取措施確保防護具的使用和維護。"},
{"id": "sk-cc-57-09", "topic": "第 57 次（98.7.26）", "code": "57-09", "n": 57, "q": "某勞工在工作場所從事作業，其作業時間噪音之暴露如下：\n08:00～12:00 穩定性噪音，LA=90dBA 13:00～14:00 變動性噪音，噪音劑量為40％\n14:00～18:00 穩定性噪音，LA=85 dBA\n(一)該勞工噪音暴露八小時日時量平均音壓級為何？(3分)\n(二)是否為特別危害健康作業(請敘明理由)(2分)\n(三)該勞工噪音暴露工作日時量平均音壓級為何？(5分)", "ans": "", "sol": "(一) D ＝ t₁ / T₁ ＋ t₂ / T₂ ＋t₃ / T₃\n＝ 4/8 ＋ 0.4 ＋ 4/16\n＝ 1.15八小時日時量平均音壓級TWA\n＝16.61log 100 × D / (12.5 × t ) + 90\n＝16.61log 100 × 1.15 / (12.5 × 8 ) + 90\n＝16.61log 1.15 ＋ 90 ＝ 91(dB)\n(二)因已達「勞工健康保護規則」所稱：勞工噪音暴露工作日八小時日時量平均音壓級在八十五分貝以上之噪音作業，故是特別危害健康作業。\n(三)該勞工噪音暴露工作日時量平均音壓級TWA\n＝16.61log 100 × D / (12.5 × t ) + 90\n＝16.61log 100 × 1.15 / (12.5 × 9 ) + 90\n＝16.61log 1.15 ＋ 90 ＝ 90.16(dB)"},
{"id": "sk-cc-57-10", "topic": "第 57 次（98.7.26）", "code": "57-10", "n": 57, "q": "試列舉五種應考慮使用呼吸防護具之場合：(10分)", "ans": "", "sol": "1、有機溶劑作業場所。\n2、鉛作業場所。\n3、特定化學物質作業場所。\n4、缺氧作業場所。\n5、粉塵作業場所。"},
{"id": "sk-cc-58-01", "topic": "第 58 次（98.11.15）", "code": "58-01", "n": 58, "q": "試回答下列問題：\n(一)勞工安全衛生法所規定具有特殊危害之作業，包括那些作業？(5 分)\n(二)何謂化學品全球調和系統(GHS)？(5分)", "ans": "", "sol": "(一)高溫作業、異常氣壓作業、高架作業、精密作業、重體力勞動作業。\n(二)所謂化學品全球調和系統(GHS)，為全球各國在化學品危害的主要架構，作為本國化學品危害分類與標示之法令依據。", "old": 1},
{"id": "sk-cc-58-02", "topic": "第 58 次（98.11.15）", "code": "58-02", "n": 58, "q": "依危險性工作場所審查暨撿查辦法規定，針對已發掘工作場所重大潛在危害所實施之安全評估，包括那些方法？(10 分)", "ans": "", "sol": "(一)檢核表(Check list)。\n(二)如果-結果分析(What If)。\n(三)危害及可操作性分析(Hazardand Operability Studies)。\n(四)故障樹分析(Fault Tree Analysis)。\n(五)失誤模式與影響分析(Failure Modesand Effects Analysis)。"},
{"id": "sk-cc-58-03", "topic": "第 58 次（98.11.15）", "code": "58-03", "n": 58, "q": "甲公司承造某一道路工程標案，全長共 35 公里，並僱用 25 名勞工於現場與承攬包商乙公司勞工 145 人及承攬包商丙公司勞工 135 人，於同一期間，同一工作場所共同作業，試問依勞工安全衛生組織管理及自動檢查辦法規定，甲公司應設何種勞工安全衛生管理組織？（2 分）及如何置勞工安全衛生人員？（8 分）", "ans": "", "sol": "(一) 甲公司勞工人數＝25人 ＋ 145人 ＋135人 ＝305 人甲公司屬營造業故須設置勞工安全衛生管理組織如下：\n1.勞工安全衛生管理單位\n2.勞工安全衛生委員會\n(二) 1.甲公司勞工人數305人應置勞工安全衛生人員：\n（1）營造業甲種勞工安全衛生業務主管1人\n（2）勞工安全或衛生管理師1人\n（3）勞工安全衛生管理員2人\n2.乙公司勞工人數145人應置勞工安全衛生人員：\n（1）營造業甲種勞工安全衛生業務主管1人\n（2）勞工安全衛生管理員1人\n3.丙公司勞工人數135人應置勞工安全衛生人員：\n（1）營造業甲種勞工安全衛生業務主管1人\n（2）勞工安全衛生管理員1人\n4.甲公司承造某一道路工程標案，全長共35公里應增置營造業丙種勞工安全衛生業務主管4人。", "old": 1},
{"id": "sk-cc-58-04", "topic": "第 58 次（98.11.15）", "code": "58-04", "n": 58, "q": "某一事業單位，其作業活動包括缺氧作業、3 公噸以上移動式起重機起重及吊掛作業、荷重在一公噸以上堆高機作業、高空工作車作業、局限空間作業，假如您是該事業之勞工安全衛生管理人員，在擬訂勞工安全衛生在職教育訓練計畫時，依勞工安全衛生教育訓練規則規定：\n(一)應使該等作業勞工(含作業主管)接受何種勞工安全衛生在職教育訓練？(6分)\n(二)上述之勞工安全衛生在職教育訓練應每幾年實施一次？每次幾小時(4分)", "ans": "", "sol": "(一) 1.缺氧作業：\n（1）缺氧作業人員勞工安全衛生在職教育訓練\n（2）有害作業主管勞工安全衛生在職教育訓練\n2. 3公噸以上移動式起重機：\n（1）3公噸以上移動式起重機起重：具有危險性之機械或設備操作人員勞工安全衛生在職教育訓練\n（2）移動式起重機吊掛作業：特殊作業人員勞工安全衛生在職教育訓練\n3.荷重在一公噸以上堆高機作業：特殊作業人員勞工安全衛生在職教育訓練\n4.高空工作車作業：高空工作車作業人員勞工安全衛生在職教育訓練\n5.局限空間作業：局限空間作業人員勞工安全衛生在職教育訓練\n(二) 以上勞工安全衛生在職教育訓練其訓練期間及時數如下：\n1.缺氧作業：\n（1）缺氧作業人員：每3年至少3小時\n（2）缺氧作業主管：每3年至少6小時\n2. 3公噸以上移動式起重機操作人員：每3年至少3小時\n3.移動式起重機吊掛作業人員：每3年至少3小時\n4.荷重在一公噸以上堆高機作業操作人員：每3年至少3小時\n5.高空工作車作業人員：每3年至少3小時\n6.局限空間作業人員：每3年至少3小時", "old": 1},
{"id": "sk-cc-58-05", "topic": "第 58 次（98.11.15）", "code": "58-05", "n": 58, "q": "為預防被夾、被捲等職災之發生，請依勞工安全衛生設施規則規定回答下列問題：\n(一) 對於機械之原動機、轉軸、齒輪、帶輪、飛輪、傳動輪、傳動帶等有危害勞工之虞之部分，應有那些安全防護設備？（4 分）\n(二) 對於每一具機械應分別設置那些動力遮斷裝置？（3 分）\n(三) 對於使用動力運轉之機械，具有顯著危險者，為能立即遮斷動力並與制動系統連動，能於緊急時快速停止機械之運轉，應於適當位置設置有明顯標誌之何種裝置？（3 分）", "ans": "", "sol": "(一)護罩、護圍、套胴、跨橋等設備。\n(二)應分別設置開關、離合器、移帶裝置等動力遮斷裝置。\n(三)緊急制動裝置。", "old": 1},
{"id": "sk-cc-58-06", "topic": "第 58 次（98.11.15）", "code": "58-06", "n": 58, "q": "依勞工安全衛生組織管理及自動檢查辦法規定回答下列問題：\n(一) 第一類事業勞工人數在三百人以上之事業單位，關於機械、器具、設備、物料、原料及個人防護具等之採購、租賃規定為何？（4 分）\n(二) 第一類事業勞工人數在三百人以上之事業單位，將營繕工程之施工、規劃、設計及監造等交付承攬或委託之規定為何？（4 分）\n(三) 關於上述執行紀錄之規定為何？（2分）", "ans": "", "sol": "(一)其契約內容應有符合法令及實際需要之勞工安全衛生具體規範，並於驗收、使用前確認其符合規定。\n(二)其契約內容應有防止職業災害之具體規範，並列為履約要件。\n(三)執行紀錄，應保存三年。", "old": 1},
{"id": "sk-cc-58-07", "topic": "第 58 次（98.11.15）", "code": "58-07", "n": 58, "q": "依世界衛生組織(WHO)之致癌物分類，第一類（Group 1）為致癌物，第三類（Group 3）為目前尚無足夠的動物或人體資料，以供分類該物質是否為人類致癌物，請區別下列各項為上述之 Group 1 或 Group3：(10 分)\n(一)含酒精飲料（alcoholic beverages）\n(二)咖啡因（caffeine）\n(三)太陽輻射（solar radiation）\n(四)吸煙（tobacco smoking）\n(五)二甲笨（xylenes）", "ans": "", "sol": "Group 1：\n(一)含酒精飲料（alcoholic beverages）\n(三)太陽輻射（solar radiation）\n(四)吸煙（tobacco smoking）Group 3：\n(二)咖啡因（caffeine）\n(五)二甲笨（xylenes）。"},
{"id": "sk-cc-58-08", "topic": "第 58 次（98.11.15）", "code": "58-08", "n": 58, "q": "林君從事有機溶劑作業，在某工作日內暴露最嚴重時段測定十五分鐘，測定結果如下表(25°C，一大氣壓下)。設該場所除甲苯、丁酮及正已烷外無其他有害物之暴露，若以相加效應評估時，該勞工暴露是否符合勞工作業環境空氣中有害物容許濃度標準規定？（請列出計算過程） (10 分)", "ans": "", "sol": "甲有害物成分之濃度/甲有害物成分之容許濃度 ＋ 乙有害物成分之濃度/乙有害物成分之容許濃度 ＋ 丙有害物成分之濃度/丙有害物成分之容許濃度 …… ＜／＝／＞ １\n其和大於１時，即屬超出容許濃度之規定。\n甲苯：200mg / M³＝（200 × 24.45）÷ 92＝53.2 ppm\n丁酮：250mg / M³＝（250 × 24.45）÷ 72＝84.9 ppm\n正己烷：100mg / M³＝（100×24.45）÷ 86＝28.4 ppm\n甲苯短時間時量平均容許濃度為：100 × 1.25＝125（ppm）\n丁酮短時間時量平均容許濃度為：200 × 1.25＝250（ppm）\n正已烷短時間時量平均容許濃度為：50 × 15＝75（ppm）計算如下：\n（53.2 ÷ 125）＋（84.9 ÷ 250）＋（28.4 ÷ 75）＝1.144 ＞ 1\n其和大於1超出容許濃度之規定。", "fig": "| 暴露物質 | 甲苯 | 丁酮 | 正己烷 |\n| --- | --- | --- | --- |\n| 暴露濃度 | 200mg / M3 | 250mg / M3 | 100mg / M3 |\n| 八小時日時量平均容許濃度 | 100PPM | 200PPM | 50PPM |\n| 變量係數 | 1.25 | 1.25 | 1.5 |\n| 分子量 | 92 | 72 | 86 |"},
{"id": "sk-cc-58-09", "topic": "第 58 次（98.11.15）", "code": "58-09", "n": 58, "q": "(一)某工廠廠房長 10 公尺、寬 6 公尺、高 4 公尺，使用甲苯(第二種有機溶劑)從事產品之清洗與擦拭．如未裝設整體換氣裝置，則其容許消費量為每小時多少公克？(請列出計算過程)(5 分)\n(二)某一室內作業場所，如每小時甲苯之消費量為 0.5 公斤，欲使用整體換氣裝置以避免該作業環境中甲苯之濃度超過容許濃度，試問其換氣量需多少m³/min？(甲苯之分子量為 92；八小時日時量平均容許濃度為 100ppm；設克分子體積為 24.45 L)。(5 分)", "ans": "", "sol": "(一) 作業場所之氣積＝10m × 6m × 4m＝240m³氣積超過 150m³者，概以 150m³計算\n甲苯之容許消費量＝2 / 5 × 作業場所之氣積\n＝2 / 5 × 150m³\n＝60 g/hr\n(二) 甲苯之換氣量Q＝(24.45 × 1000 × W) ÷ (60 × C_{ppm}× M)\n＝(24.45×1000×500)÷(60×100×92)＝22.15m³/min"},
{"id": "sk-cc-58-10", "topic": "第 58 次（98.11.15）", "code": "58-10", "n": 58, "q": "為避免局部振動危害，在工程控制方面有那些方法？ (10 分)", "ans": "", "sol": "1、減低設備之振動情形\n2、使用防振緩衝材料\n3、降低振動傳導\n4、調整作業姿勢及加強手部保溫"},
{"id": "sk-cc-59-01", "topic": "第 59 次（99.3.28）", "code": "59-01", "n": 59, "q": "甲鋼鐵公司平時勞工人數有3,500人，已設直接隸屬總經理之勞工安全衛生管理單位「工安環保處」，辦理勞工安全衛生管理、消防安全及環保等業務，\n試回答下列問題：(10分)？\n(一)甲公司所設勞工安全衛生管理單位是否符合法令規定？(2分)原因為何？(2分)\n(二)甲公司如欲維持現有勞工安全衛生管理組織，依勞工安全衛生組織管理及自動檢查辦法之規定，應採取措施為何？(6分)", "ans": "", "sol": "(一) 甲公司所設勞工安全衛生管理單位不符合法令規定。因甲公司為第一類事業單位其所設勞工安全衛生管理單位應為一級專責單位，除辦理勞工安全衛生管理外，不得兼任消防安全及環保等業務。\n(二) 第一類事業單位或其總機構所設置之勞工安全衛生管理單位，如已實施職業安全衛生管理系統相關管理制度，管理績效並經中央主管機關認可者，得不受一級管理單位應為專責之限制。（依據勞工安全衛生組織管理及自動檢查辦法第 2-1 條及 6-1 條）", "old": 1},
{"id": "sk-cc-59-02", "topic": "第 59 次（99.3.28）", "code": "59-02", "n": 59, "q": "請依勞工安全衛生法令回答下列問題：(10 分)\n(一)事業單位之勞工安全衛生管理人員，應如何設置才能符合「專職」之規定？(5 分)\n(二)應符合機械器具安全防護標準規定之高危害性機械包括那些？(5 分)", "ans": "", "sol": "(一)第一類事業之事業單位僱用勞工人數在一百人以上者，所置管理人員應為專職；第二類事業之事業單位僱用勞工人數在三百人以上者，所置管理人員應至少一人為專職。依規定所置專職管理人員，應常駐廠場執行業務，不得兼任其他與勞工安全衛生無關之工作。（依據勞工安全衛生組織管理及自動檢查辦法第 3 條）\n(二)應符合機械器具安全防護標準規定之高危害性機械包括：動力衝剪機械、手推刨床、木材加工用圓盤鋸、動力堆高機、研磨機、研磨輪、其他經中央主管機關指定之機械或器具。（依據勞工安全衛生法施行細則第 7 條）", "old": 1},
{"id": "sk-cc-59-03", "topic": "第 59 次（99.3.28）", "code": "59-03", "n": 59, "q": "(一)乙食品加工廠某日於工作場所發生勞工死亡職業災害，請問雇主應於多久時間內向那一個單位報告？(3 分)\n(二)如該雇主未依勞工安全衛生法之規定報告，其罰則為何？(4 分)\n(三)發生上述職業災害，雇主除採取必要之急救、搶救等措施外，並應實施那些措施，以避免類似災害再發生？(3 分)", "ans": "", "sol": "(一)雇主應於 24 小時內向當地勞動檢查機構報告。（依據勞工安全衛生法第 28條第二項）\n(二)如該雇主未依勞工安全衛生法之規定報告，處一年以下有期徒刑、拘役或科或併科新臺幣九萬元以下罰金。（依據勞工安全衛生法第 32 條）\n(三)發生上述職業災害，雇主除採取必要之急救、搶救等措施外，並應實施調查、分析及作成紀錄。以避免類似災害再發生。（依據勞工安全衛生法第 28條第一項）", "old": 1},
{"id": "sk-cc-59-04", "topic": "第 59 次（99.3.28）", "code": "59-04", "n": 59, "q": "第一類事業勞工人數在 300 人以上之事業單位，以其事業之全部或一部份分交付承攬或與承攬人分別僱用勞工於同一期間、同一工作場所共同作業時，除應依勞工安全衛生法第十七條或第十八條規定辦理外，並應訂定承攬管理計畫，其內容包含那些事項？(10 分)", "ans": "", "sol": "承攬管理計畫其內容應包含：\n（1）承攬人之安全衛生管理能力\n（2）職業災害通報\n（3）危險作業管制\n（4）教育訓練\n（5）緊急應變\n（6）安全衛生績效評估等事項。\n（依據勞工安全衛生組織管理及自動檢查辦法第 12-5 條）", "old": 1},
{"id": "sk-cc-59-05", "topic": "第 59 次（99.3.28）", "code": "59-05", "n": 59, "q": "雇主對於起重機具之運轉作業時，為防止吊掛物掉落，依勞工安全衛生設施規則規定，應辦理事項為何？(10 分)", "ans": "", "sol": "雇主對於起重機具之運轉作業時，為防止吊掛物掉落，應依下列規定辦理：\n一、吊掛物使用吊耳時，吊耳設置位置及數量，應能確保吊掛物之平衡。\n二、吊耳與吊掛物之結合方式，應能承受所吊物體之整體重量，使其不致脫落。\n三、使用吊索（繩）、吊籃等吊掛用具或載具時，應有足夠強度。（依據勞工安全衛生設施規則第 92 條第二項）", "old": 1},
{"id": "sk-cc-59-06", "topic": "第 59 次（99.3.28）", "code": "59-06", "n": 59, "q": "依勞工安全衛生設施規則規定，雇主應於明顯易見之處所標明，並禁止非從事作業有關之人員進入之工作場所為何？請列舉5種。(10分)", "ans": "", "sol": "雇主應於明顯易見之處所標明，並禁止非從事作業有關之人員進入下列工作場所：\n1、處置大量高熱物體或顯著濕熱之場所。\n2、處置大量低溫物體或顯著寒冷之場所。\n3、強烈微波、射頻波或雷射等非游離輻射之場所。\n4、氧氣濃度未滿百分之十八之場所。\n5、有害物超過容許濃度之場所。\n6、處置特殊有害物之場所。\n7、生物病原體顯著污染之場所。\n（以上任選 5 種，依據勞工安全衛生設施規則第 299 條）", "old": 1},
{"id": "sk-cc-59-07", "topic": "第 59 次（99.3.28）", "code": "59-07", "n": 59, "q": "近年來升降機相關的職業災害案件時有所聞，試列舉造成升降機災害的常見原因有那些？(10 分)", "ans": "", "sol": "1、升降機之升降路各樓出入口，未裝置構造堅固平滑之門，及未有安全裝置，致使升降搬器及升降路出入口之任一門開啟時，升降機也能開動，及升降機在開動中任一門開啟時，不能停止上下運作。\n2、升降機各樓出入口及搬器內，未明顯標示其積載荷重或乘載之最高人數，且未規定使用時不得超過限制，以致超載墜落。\n3、升降機之升降路各樓出入口門，未有連鎖裝置，致使搬器地板與樓板相差七．五公分以上時，升降路出入口門也能開啟，使進出搬器之勞工或物件被夾。\n4、升降機，未設置終點極限開關、緊急剎車及其他安全裝置。\n5、起重升降機具所使用之吊掛構件，未使其具足夠強度，使用之吊鉤或鉤環及附屬零件，其斷裂荷重與所承受之最大荷重比之安全係數未達四以上。\n（依據勞工安全衛生設施規則第\n93、\n94、\n95、\n96、97 條）", "old": 1},
{"id": "sk-cc-59-08", "topic": "第 59 次（99.3.28）", "code": "59-08", "n": 59, "q": "某勞工於有機溶劑甲苯作業環境中工作 10 小時，經測定該場所之甲苯濃度320 mg/m³，又甲苯之 8 小時日時量平均容許濃度為 100 ppm，分子量為 92。\n試問該勞工之暴露狀況是否符合規定？(假設大氣條件為一大氣壓、25℃)(10 分)", "ans": "", "sol": "(1)甲苯濃度 320mg/m³經換算ppm濃度為：\nppm=(mg/m³×24.45)/分子量=(320×24.45)/92=85.04ppm\n(2)將原來該有害物之八小時時量平均容許濃度轉換為相當於8小時的時量平均容許濃度再比較：\n相當 8 小時的時量平均容許濃度 = 該有害物之八小時時量平均容許濃度 ×8/超過八小時之實際時間\n相當於 8 小時的時量平均容許濃度=100ppm × 8/10 = 80ppm\n(3)工作 10 小時實際暴露濃度為 85.04ppm 大於工作 10 小時相當 8 小時的時量平均容許濃度 80ppm，故不符合規定。"},
{"id": "sk-cc-59-09", "topic": "第 59 次（99.3.28）", "code": "59-09", "n": 59, "q": "假設某作業環境小粒徑 10 微米及粒徑 0.3 微米之厭惡性粉塵濃度分別為 50 mg/m³及 100 mg/m³，今有一勞工佩戴密合度 100%之N95 口罩，請計算該勞工對此兩種粉塵之暴露濃度。(10 分)", "ans": "", "sol": "(1)N型濾材僅適用於防護固體微粒，使用NaCl微粒進行穿透測試。\n(2)N型濾材依防護效果，95代表對特定測試0.3微米微粒的過濾效率為95%(即穿透率必須小於5%)。\n(3)粒徑10微米之厭惡性粉塵濃度為50mg/m³，佩戴密合度100％之N95口罩，該勞工暴露濃度為50×0.05=2.5mg/m³\n(4)粒徑0.3微米之厭惡性粉塵濃度為100mg/m³，佩戴密合度100％之N95口罩，該勞工暴露濃度為100×0.05=5mg/m³\n(5)依規定厭惡性粉塵之可呼吸性粉塵為5mg/m³，兩者均未超過，故符合規定。"},
{"id": "sk-cc-59-10", "topic": "第 59 次（99.3.28）", "code": "59-10", "n": 59, "q": "依勞工安全衛生設施規則規定，雇主對於工作場所有生物病原體危害之虞者，應採取感染預防措施，請列出 5 項。(10 分)", "ans": "", "sol": "1、危害暴露範圍之確認。\n2、相關機械、設備、器具等之管理及檢點。\n3、警告傳達及標示。\n4、健康管理。\n5、感染預防作業標準。\n6、感染預防教育訓練。\n7、扎傷事故之防治。\n8、個人防護具之採購、管理及配戴演練。\n9、緊急應變。\n10、感染事故之報告、調查、評估、統計、追蹤、隱私權維護及紀錄。\n11、感染預防之績效檢討及修正。\n（以上任選5項）（依據勞工安全衛生設施規則第 297-1 條）", "old": 1},
{"id": "sk-cc-60-01", "topic": "第 60 次（99.7.25）", "code": "60-01", "n": 60, "q": "甲金屬加工廠最近擬招募勞工安全衛生管理員，試問\n(一)該雇主可從其勞工當中選擇具備那些資格者擔任之？(8 分)\n(二)該工廠如應設勞工安全衛生委員會，其勞工人數至少在多少人以上？(2 分)(請依勞工安全衛生組織管理及自動檢查辦法相關規定作答)", "ans": "", "sol": "(一)1. 具有勞工安全管理師或勞工衛生管理師資格者。\n2. 領有勞工安全衛生管理乙級技術士證照者。\n3. 曾任勞動檢查員，具有勞動檢查工作經驗滿二年以上者。\n4. 曾修畢工業安全衛生相關科目十八學分以上，並具有國內外大專以上校院工業安全衛生相關科系畢業。\n(二) 其勞工人數至少在100人以上。", "old": 1},
{"id": "sk-cc-60-02", "topic": "第 60 次（99.7.25）", "code": "60-02", "n": 60, "q": "乙電子公司為一廠辦大樓，最近擬新設一台升降機供員工作業及訪客使用，\n(一)請問該升降機之檢查及管理歸那一機關主管？(2 分)\n(二)該公司想採用吊籠來清洗大樓外牆，請問人員在清洗作業中，雇主應採取那些安全管理措施？(至少列舉4項)(8分)(請依起重升降機具安全規則相關規定作答)", "ans": "", "sol": "(一)內政部營建署\n(二)1.對於吊籠之使用，不得超過積載荷重。\n2.對於吊籠之構造，應符合吊籠安全檢查構造標準。\n3.對於可搬式吊籠懸吊於建築物或構造物等時，應考量吊籠自重、積載荷重及風力等受力情形，妥為固定於具有足夠支撐強度之處。\n4.於吊籠之工作台上，不得設置或放置腳墊、梯子等供勞工使用。\n5.於吊籠運轉中，應禁止操作人員擅離操作位置。\n6.對勞工於吊籠工作台上作業時，應使勞工佩戴適當之安全帶及安全帽。\n7.於吊籠使用時，應禁止無關人員進入作業場所下方之危險區域，並設置警告標示。\n8.對吊籠於強風、大雨、大雪等惡劣氣候，勞工作業有發生危險之虞時，應禁止工作。\n9.使用吊籠作業時，於夜間或光線不良之場所，應提供安全作業所必要之照度。（以上任選 4 項）"},
{"id": "sk-cc-60-03", "topic": "第 60 次（99.7.25）", "code": "60-03", "n": 60, "q": "丁營造公司將鋼構組配作業交由戊公司承欖，講問依勞工安全衛生法及勞動基準法有關承欖作業之職業災害補償規定為何？(10 分)", "ans": "", "sol": "(一)勞工安全衛生法及勞動基準法均有規定：原事業單位、與最後承攬人，連帶負本法所定雇主應負職業災害補償之責任。\n(二)勞動基準法再規定如下：\n1.中間承攬人，就各該承攬部分所使用之勞工，均應與最後承攬人，連帶負本法所定雇主應負職業災害補償之責任。\n2.事業單位或承攬人或中間承攬人，為前項之災害補償時，就其所補償之部分，得向最後承攬人求償。\n3.事業單位違背勞工安全衛生法有關對於承攬人、再承攬人應負責任之規定，致承攬人或再承攬人所僱用之勞工發生職業災害時，應與該承攬人、再承攬人負連帶補償責任。", "old": 1},
{"id": "sk-cc-60-04", "topic": "第 60 次（99.7.25）", "code": "60-04", "n": 60, "q": "(一)依勞工安全衛生法令規定，雇主對於所僱勞工應實施體格檢查、定期健康檢查或特定項目之特殊健康檢查，試分別敘述該三項檢查之意義。(6分)\n(二)如健康檢查發現某位勞工因職業原因導致不能適應原有工作時，雇主應採取那些適當措施？(4 分)", "ans": "", "sol": "(一)1.體格檢查：係指於僱用勞工或變更其工作時，為識別勞工工作適性，考量其是否有不適合作業之疾病所實施之健康檢查。\n2.定期健康檢查： 係指依在職勞工之年齡層， 於一定期間所實施之一般健康檢查。\n3.特定項目之健康檢查：係指對從事特別危害健康作業之勞工， 依其作業危害性，於一定期間所實施之特殊健康檢查。\n(二)體格檢查發現應僱勞工不適於從事某種工作時，不得僱用其從事該項工作。\n健康檢查發現勞工因職業原因致不能適應原有工作者，除予醫療外，並應變更其作業場所，更換其工作，縮短其工作時間及為其他適當措施。", "old": 1},
{"id": "sk-cc-60-05", "topic": "第 60 次（99.7.25）", "code": "60-05", "n": 60, "q": "丙公司製造一課從事甲苯作業，請製作 1 份實施局部排氣裝置的定期檢查表。(10 分)", "ans": "", "sol": "", "fig": "局部排氣裝置的定期檢查表\n| 檢查項目 | 結果：合格 | 結果：不合格 | 不合格改善措施 |\n| --- | --- | --- | --- |\n| 氣罩、導管及排氣機之磨損、腐蝕、凹凸及其他損害之狀況及程度 |  |  |  |\n| 導管或排氣機之塵埃聚積狀況 |  |  |  |\n| 排氣機之注油潤滑狀況 |  |  |  |\n| 導管接觸部分之狀況 |  |  |  |\n| 連接電動機與排氣機之皮帶之鬆弛狀況 |  |  |  |\n| 吸氣及排氣之能力 |  |  |  |\n| 設置於排放導管上之採樣設施是否牢固、鏽蝕、損壞、崩塌或其他妨礙作業安全事項 |  |  |  |\n| 其他保持性能之必要事項 |  |  |  |"},
{"id": "sk-cc-60-06", "topic": "第 60 次（99.7.25）", "code": "60-06", "n": 60, "q": "衝剪機械安全防護不足常造成勞工肢體受傷或失能，請列舉 5 種衝剪機械常用之安全裝置或設施。(10 分)", "ans": "", "sol": "1.防護式安全裝置：護罩(欄、柵)、防護門。\n2.雙手操作式安全裝置：雙手同操安全裝置。\n3.感應式安全裝置：光電式安全裝置、投光器、受光器。\n4.拉開式安全裝置：拉護帶。\n5.掃除式安全裝置：掃護桿。"},
{"id": "sk-cc-60-07", "topic": "第 60 次（99.7.25）", "code": "60-07", "n": 60, "q": "(一)何謂升降機之積載荷重？(5 分)\n(二)某一牽引式載貨用升降機其搬器內淨長 2.2 公尺、淨寬 2.0 公尺，試問該升降機在設計時其積載荷重至少應取多少公斤？(請列出計算過程)(5 分)", "ans": "", "sol": "(一)積載荷重：在升降機，指依其構造及材質，於搬器上乘載人員或荷物上升之最大荷重。\n(二) 依升降機安全檢查構造標準第 29 條之規定：\n（1）載貨用ω＝250 × A A＝2.2×2＝4.4 m²\n得ω＝250×4.4＝1100 (公斤) …………本題解答\n（2）另補充：如客貨兩用(底面積超過 3 平方公尺者)，以載人用計算之：\nω=600×(A-3)+1300＝600×(4.4-3)+1300＝2140 (公斤)"},
{"id": "sk-cc-60-08", "topic": "第 60 次（99.7.25）", "code": "60-08", "n": 60, "q": "依勞工作業環境測定實施辦法規定，請說明下列作業場所．雇主應定期實施作業環境測定項目及期間。(10 分)\n(一)設有中央空調之商業銀行。\n(二)八小時日時量平均音壓級 91 分貝之作業場所。\n(三)使用丙酮之作業場所。\n(四)含鉛、鉛塵設備內部之作業。\n(五)從事蒸汽操作連續作業，日時量平均 WBGT 值 33.2 者。", "ans": "", "sol": "", "fig": "| 作業場所 | 作業環境測定項目 | 作業環境測定期間 |\n| --- | --- | --- |\n| 設有中央空調之商業銀行 | 二氧化碳濃度 | 6個月 |\n| 八小時日時量平均音壓級91分貝之作業場所 | 音壓級 | 6個月 |\n| 使用丙酮之作業場所 | 丙酮濃度 | 6個月 |\n| 含鉛、鉛塵設備內部之作業 | 鉛濃度 | 1年 |\n| 從事蒸汽操作連續作業，日時量平均WBGT值33.2者 | 綜合溫度熱指數 | 3個月 |"},
{"id": "sk-cc-60-09", "topic": "第 60 次（99.7.25）", "code": "60-09", "n": 60, "q": "一氧化碳與二氧化碳皆為窒息性物質，其中二氧化碳被歸類為單純性之窒息性物質，而一氧化碳則非屬單純性之窒息性物質。請問：\n(一)何謂單純性之窒息性物質?(5 分)\n(二)一氧化碳未被歸類為單純性之窒息性物質之主要原因?(5 分)", "ans": "", "sol": "(一)單純性之窒息性物質不具化學活潑性，不易與其他物質反應，本身不會燃燒爆炸，如大量外洩時，可使作業場所氧氣稀釋導致缺氧環境，無其他反應，此缺氧窒息為單純性之窒息性物質，如二氧化碳。\n(二) 一氧化碳如與血紅素結合為時，氧氣就無法與血紅素結合，導致氧氣無法運送而缺氧窒息，此為化學性缺氧窒息，故CO未被歸類為單純性之窒息性物質而是歸類為丁類特定化學物質。"},
{"id": "sk-cc-60-10", "topic": "第 60 次（99.7.25）", "code": "60-10", "n": 60, "q": "某一勞工工作場所以機械通風方式引進新鮮空氟。此新鮮空氟之二氧化碳濃度為 400ppm，由工作場所回風之空氣，其二氧化碳濃度為 1000ppm，如欲使新鮮空氣及回風空氣混合後之二氧化碳濃度為 900ppm，則新鮮空氣換氣量應為回風風量之多少百分比?(請列出計算過程)(10 分)", "ans": "", "sol": "設新鮮空氣換氣量為Q₁(m³)\n∵ppm＝cm³/m³故新鮮空氣之二氧化碳量為400(cm³/m³)×Q₁(m³)設回風風量為Q₂(m³)故回風之二氧化碳量為1000(cm³/m³)×Q₂(m³)新鮮空氣及回風空氣混合後之二氧化碳總量為900(cm³/m³)×(Q₁＋Q₂)\n∵新鮮空氣之二氧化碳量+回風之二氧化碳量=混合後之二氧化碳總量\n∴(400×Q₁＋1000×Q₂)=900×(Q₁＋Q₂)\n故100Q₂=500Q₁\nQ₁：Q₂=1：5\n新鮮空氣換氣量：回風風量=1：5\n則新鮮空氣換氣量＝回風風量之百分之二十"},
{"id": "sk-cc-61-01", "topic": "第 61 次（99.11.14）", "code": "61-01", "n": 61, "q": "甲造紙工廠預定於近期進行紙漿槽清理作業，為避免造成人員缺氧或硫化氫中毒災害，該事業單位應採取那些安全防範措施?(至少列舉 5 項)(10 分)", "ans": "", "sol": "1、局限空間內危害之確認。\n2、局限空間內氧氣、危險物、有害物濃度之測定。\n3、通風換氣實施方式。\n4、電能、高溫、低溫及危害物質之隔離措施及缺氧、中毒、感電、塌陷、被夾、被捲等危害防止措施。\n5、作業方法及安全管制作法。\n6、進入作業許可程序。\n7、提供之防護設備之檢點及維護方法。\n8、作業控制設施及作業安全檢點方法。\n9、緊急應變處置措施。"},
{"id": "sk-cc-61-02", "topic": "第 61 次（99.11.14）", "code": "61-02", "n": 61, "q": "乙營造公司承造某地下 3 層。地上 20 層 SRC(鋼筋混凝土構造)住宅工程，採順打工法，並分別將各分項工程交付承攬，該公司要工地主任陳大明擔任工作場所負責人，試問：\n(一)依勞工安全衛生法規定，陳大明須擔負那些重要職責？(4 分)\n(二)陳大明欲協助及指導上述承攬商辦理安全衛生教育訓練，該工程須具有哪些營造作業主管之資格?(至少列舉 3 項)(6 分)", "ans": "", "sol": "(一) 依勞工安全衛生法規定，本工程屬共同作業，陳大明須擔負重要職責如下：\n1、設置協議組織，並指定工作場所負責人，擔任指揮及協調之工作。\n2、工作之連繫與調整。\n3、工作場所之巡視。\n4、相關承攬事業間之安全衛生教育之指導及協助。\n5、其他為防止職業災害之必要事項。\n(二) 該工程須具有營造作業主管之資格如下：\n1、擋土支撐作業主管。\n2、露天開挖作業主管。\n3、模板支撐作業主管。\n4、施工架及施工構台組配作業主管。", "old": 1},
{"id": "sk-cc-61-03", "topic": "第 61 次（99.11.14）", "code": "61-03", "n": 61, "q": "甲半導體製造公司勞工人數達 3,250 人，依勞工安全衛生組織管理及自動檢查辦法的規定．該公司除應訂定勞工安全衛生管理計畫之外，尚須訂定勞工安全衛生管理規章，試問：\n(一)勞工安全衛生管理計畫與勞工安全衛生管理規章兩者之性質差異為何？(4 分)\n(二)如該公司想加強營繕工程及勞務之承攬管理，請列舉至少 3 種有關承攬商管理規章，以提供該公司參考？(6 分)(請參考中央主管機關公告之勞工安全衛生管理規章及勞工安全衛生管理計畫大綱作答)", "ans": "", "sol": "(一)\n1、勞工安全衛生管理規章：指事業單位為有效防止職業災害，促進勞工安全與健康，所訂定要求各級主管及管理、指揮、監督等有關人員執行與勞工安全衛生有關之內部管理程序、準則、要點或規範等文件。\n2、勞工安全衛生管理計畫：指事業單位為執行安衛管理辦法第十二條之一所定勞工安全衛生事項，訂定之各項工作目標、期程、採行措施、資源需求及績效考核等具體實施內容。\n(二) 如該公司想加強營繕工程及勞務之承攬管理，提供該公司參考有關承攬商管理規章如下：\n1、承攬商勞工安全衛生組織設置要點。\n2、勞務之承攬管理要點。\n3、共同作業協議組織設置規範。\n4、營繕工程工地管理準則。\n(出自勞委會在網站公告之勞工安全衛生管理規章及勞工安全衛生管理計畫)", "old": 1},
{"id": "sk-cc-61-04", "topic": "第 61 次（99.11.14）", "code": "61-04", "n": 61, "q": "依高壓氣體之定義，試判斷下列敘述中是否為高壓氣體勞工安全規則所稱之高壓氣體。(答案應附說明或計算)(10 分)\n(一)在 15°C時表壓力 1.8kg/cm²之乙炔氣體。\n(二)在 20°C時表壓力 9.9kg/cm²之氫氣。", "ans": "", "sol": "(一) 在 15°C時表壓力 1.8kg/cm²之乙炔氣體不是高壓氣體，須溫度在攝氏十五度時之壓力可達每平方公分二公斤以上之壓縮乙炔氣才算高壓氣體。\n(二) 在20°C時表壓力9.9kg/cm²之氫氣不是高壓氣體，須在常溫下（20°C），表壓力達每平方公分十公斤以上之氫氣(壓縮氣體)才算高壓氣體。\n（出自高壓氣體勞工安全規則第2條-第\n1、2款）"},
{"id": "sk-cc-61-05", "topic": "第 61 次（99.11.14）", "code": "61-05", "n": 61, "q": "一路發化學有限公司生產過程使用異丙醇、二甲苯及氮氣等化學物質，為防止勞工未確實知悉危害物質之危害資訊，而引起職業災窖，應採取那些必要措施 (10 分)", "ans": "", "sol": "使用異丙醇、二甲苯及氮氣等化學物質，應採取必要措施如下：\n1、訂定危害通識計畫。\n2、製作危害物質清單。\n3、提供物質安全資料表。\n4、張貼危害物質標示。\n5、辦理危害通識教育訓練等。"},
{"id": "sk-cc-61-06", "topic": "第 61 次（99.11.14）", "code": "61-06", "n": 61, "q": "依據統計資料顯示，「被夾、被捲」為全產業職業災害類型之前三位，依勞工安全衛生設施規則規定，試舉出 5 種車床作業(如圖所示)預防「被夾、被捲」的防範設施？(10 分)", "ans": "", "sol": "預防車床作業「被夾、被捲」的防範設施如下：\n1、設置護罩。\n2、設置護圍。\n3、設置具有連鎖性能之安全門設備。\n4、對車床之高度，超過從事作業勞工之身高時，應設置供勞工能安全使用，且為適當高度之工作台。\n5、應禁止勞工攀登運轉中之立式車床之床台。\n（出自勞工安全衛生設施規則第\n58、\n59、60 條）", "note": "題目寫「如圖所示」，但原PDF該題未見對應圖。", "old": 1},
{"id": "sk-cc-61-07", "topic": "第 61 次（99.11.14）", "code": "61-07", "n": 61, "q": "請列舉 4 種移動式起重機的安全裝置。 (10 分)", "ans": "", "sol": "移動式起重機的安全裝置如下：\n1、過捲揚預防裝置\n2、過負荷預防裝置\n3、制動器\n4、安全閥\n5、吊鉤防滑裝置\n6、其他重要安全裝置：如外伸撐座、風向風速計等。"},
{"id": "sk-cc-61-08", "topic": "第 61 次（99.11.14）", "code": "61-08", "n": 61, "q": "(一)一般而言，人體有那 3 種排出體熱之方式?(6 分)\n(二)熱危害主要有熱中暑、熱衰竭、熱痙攣 3 項，今有一勞工有熱危害，症狀為皮膚乾熱且乏汗，請問該勞工可能有上述那一種熱危害?(2 分)\n(三)請問上述勞工有無可能導致死亡，並說明理由。(2 分)", "ans": "", "sol": "(一)人體排出體熱之方式：皮下微血管擴張、心跳加速及增加出汗。\n(二)症狀為皮膚乾熱且乏汗之熱危害：熱中暑\n(三)熱中暑會使皮膚乾且熱的異常高溫，若體溫上升太高將導致死亡。"},
{"id": "sk-cc-61-09", "topic": "第 61 次（99.11.14）", "code": "61-09", "n": 61, "q": "以交流電焊機從事鋼板材質圓筒型儲槽(內徑 2.4 公尺)之製造，作業項目有電焊及儲槽組裝作業，請分別說明該 2 項作業之主要危害，並分別提出至少 3 項防止對策。(10 分)", "ans": "", "sol": "", "fig": "| 作業項目／危害及對策 | 電焊（交流電焊機） | 儲槽組裝 |\n| --- | --- | --- |\n| 主要危害 | 感電 | 中毒、缺氧 |\n| 防止對策 | 1.加裝自動電擊防止裝置<br>2.接地<br>3.裝設漏電斷路器 | 1.危害物測定<br>2.儲槽內通風換氣<br>3.戴用空氣呼吸器 |"},
{"id": "sk-cc-61-10", "topic": "第 61 次（99.11.14）", "code": "61-10", "n": 61, "q": "勞工之噪音暴露經測定結果如下，試回答下列問題：\n08：00~12：00 穩定性噪音 90dBA 15：00~16：00 變動性噪音 D＝20%16：00~17：00 穩定性噪音 95dBA\n17：00~19：00 衝擊性燥音 D＝10%\n(一)該勞工之噪音暴露劑量為多少%？(講列出計算式)(5 分)\n(二)該作業是否屬特別危害健康作業?(請說明埋由)(2 分)\n(三)依勞工安全衛生設施規則規定，請列出僱主應採取之三項措施?(3 分)", "ans": "", "sol": "(一)D＝t₁ / T₁ ＋ t₂ / T₂ ＋ t₃ / T₃＋ t₄ / T₄\n＝ 4 / 8 ＋ 20 % ＋ 1 / 4＋10 %\n＝50 %＋ 20 % ＋25 %＋10 %＝105 %＝1.05 ＞ 1上列暴露劑量和大於一超出容許暴露劑量，不符合法令規定。\n(二)該作業是屬特別危害健康作業，原因如下：\n暴露之八小時日時量平均音壓級L_{TWA}＝16.61 log 100 × D / (12.5 × t ) + 90（dB）\n＝16.61 1og 1.05 ＋ 90 ＝ 90.35（dB）＞85（dB）屬勞工噪音暴露工作日八小時日時量平均音壓級在85 dB以上之噪音作業\n(三)依勞工安全衛生設施規則規定，應採取之三項措施：\n1、應採取工程控制。\n2、減少勞工噪音暴露時間。\n3、戴用有效之耳塞、耳罩等防音防護具。", "old": 1},
{"id": "sk-cc-62-01", "topic": "第 62 次（100.3.27）", "code": "62-01", "n": 62, "q": "甲公司員工1200人，依勞工健康保護規則規定(該公同屬第一類事業，且無特危害健康作業)，須僱用或特約從事勞工健康服務之醫護人員為其員工辦理臨廠健康服務，試問：\n(一)醫護人員應具那些資格？(3分)\n(二)醫師臨廠服務之頻率為何？(2分)\n(三)醫護人員臨廠服務辦理之事項為何？(至少列舉5項)(5分)", "ans": "", "sol": "(一)1.職業醫學科專科醫師。\n2.具醫師資格，並經中央主管機關指定之訓練合格者。\n3.具護理人員資格，並經中央主管機關指定之訓練合格者。\n(二)每月至少3次。\n(三)1.勞工之健康教育、健康促進與衛生指導之策劃及實施。\n2.職業傷病及一般傷病之防治、健康諮詢與急救及緊急處置。\n3.勞工之預防接種及保健。\n4.協助雇主選配勞工從事適當之工作。\n5.勞工體格、健康檢查紀錄之分析、評估、管理與保存及健康管理。\n6.職業衛生之研究報告及傷害、疾病紀錄之保存。\n7.協助雇主與勞工安全衛生人員實施職業病預防及工作環境之改善。\n（出自100/1/21新修正勞工健康保護規則第\n4、7條及附表二）", "old": 1},
{"id": "sk-cc-62-02", "topic": "第 62 次（100.3.27）", "code": "62-02", "n": 62, "q": "工作場所風險評估是用來辨識和瞭解工作環境及作業活動過程可能出現的危害，並避免或降低這些危害對人員造成職業災害之風險。如以一家勞工超過1000人以上之汽車生產工廠而言，試回答下列問題：\n(一)其執行風險評估的適當時機為何？(4分)\n(二)請協助該工廠訂出記錄風險評估結果所需的表單？(6分)(請參考中央主管機關發布之「風險評估技術指引」作答)", "ans": "", "sol": "(一) 執行風險評估的時機，如下：\n1.建立安全衛生管理計畫或職業安全衛生管理系統時。\n2.新的化學物質、機械、設備、或作業活動等導入時。\n3.機械、設備、作業方法或條件等變更時。\n(二) 風險評估表（基本版）（出自中央主管機關發布之「風險評估技術指引」）", "fig": "| 公司名稱 | 部門 | 評估日期 | 評估人員 | 審核者 |\n| --- | --- | --- | --- | --- |\n|  |  |  |  |  |\n| 1.作業/流程名稱 | 2.辨識危害及後果(危害可能造成後果之情境描述) | 3.現有防護設施 | 4.降低風險所採取之控制措施 |\n| --- | --- | --- | --- |\n|  |  |  |  |"},
{"id": "sk-cc-62-03", "topic": "第 62 次（100.3.27）", "code": "62-03", "n": 62, "q": "乙影劇公司共有員工525人，承辦市政府跨年晚會活動，須搭設高度超過5公尺的舞台施工架，及使用吊升荷重5公噸以上之移動式起重機吊裝施工架，試問：\n(一)乙公司應如何設置勞工安全衛生管理組織及人員，並陳報勞動檢查機構備查？(4分)\n(二)乙公司如將該舞台組裝交付承攬時，應要求承攬人所僱從事上述作業之勞工必須經過那幾種勞工安全衛生教育訓練合格，始可進場作業？(6分)", "ans": "", "sol": "(一)影劇公司為大眾傳播業，屬第三類為低度風險之事業，員工 525 人不需設勞工安全衛生管理單位，應設置下列人員：1.甲種勞工安全衛生業務主管及勞工安全衛生管理員各 1 人。\n(二)下列人員應接受工作所必要之教育訓練：\n1.營造業甲種勞工安全衛生業務主管。\n2.勞工安全衛生管理員。\n3.吊升荷重在5公噸以上之移動式起重機操作人員。\n4.使用起重機具從事吊掛作業人員。\n5.施工架及施工構臺組配作業主管。\n6.急救人員。\n7.一般安全衛生教育訓練六小時(含營造作業安全至少三小時)。\n(依勞工安全衛生組織管理及自動檢查辦法、勞工安全衛生教育訓練規則規定作答)", "old": 1},
{"id": "sk-cc-62-04", "topic": "第 62 次（100.3.27）", "code": "62-04", "n": 62, "q": "李小明在鐵工廠工作，該作業場所連續噪音量 8 時至 10 時為 90 分貝，10時至 12 時為 95 分貝，12 時至 13 時為休息時間，13 時至 14 時為 100 分貝，14 時至 17 時為 90 分貝，請問李小明之噪音暴露是否符合法令規定？(請列出計算公式) (10 分)", "ans": "", "sol": "基本公式T=8/2^{(L-90)/5}\nD=(t₁/T₁)+(t₂/T₂)+…+(t_{n}/T_{N})\nL=16.61logD＋90 90 dB容許暴露時間為8小時\n95 dB容許暴露時間為T=8/2^{(L-90)/5}=4小時\n100 dB容許暴露時間為T=8/2^{(L-90)/5}=2小時\nD=【(2/8)＋(2/4)＋(1/2)+(3/8)】=1.25\n因為D＞1 所以不符合法令規定"},
{"id": "sk-cc-62-05", "topic": "第 62 次（100.3.27）", "code": "62-05", "n": 62, "q": "如下圖所示勞工在高度1.5公尺的梯子上作業，依據勞工安全衛生設施規則，該梯子應符合那些規定？(10分)", "ans": "", "sol": "1、具有堅固之構造。\n2、其材質不得有顯著之損傷、腐蝕等。\n3、梯腳與地面之角度應在七十五度以內，且兩梯腳間有繫材扣牢。\n4、有安全之梯面。\n（出自依據勞工安全衛生設施規則第 230 條）", "note": "題目寫「如下圖所示」，但原PDF該題未見對應圖。", "old": 1},
{"id": "sk-cc-62-06", "topic": "第 62 次（100.3.27）", "code": "62-06", "n": 62, "q": "丙工廠因業務需要，擬於廠內新設一座吊升荷重為20公噸之架空式起重機，請回答與該架空式起重機之相關問題：\n(一)簡要說明架空式起重機吊升荷重與額定荷重之定義。(6分)\n(二)該事業單位須向檢查機構申請何種檢查？(4分)", "ans": "", "sol": "(一)1.吊升荷重係指依固定式起重機、移動式起重機、人字臂起重桿等之構造及材質，所能吊升之最大荷重。\n2.額定荷重係指依其構造及材質、伸臂之傾斜角及長度、吊運車之位置，決定其足以承受之最大荷重後，扣除吊鉤、抓斗等吊具之重量所得之荷重。\n(二)設置完成後向當地勞動查機構申請竣工檢查。"},
{"id": "sk-cc-62-07", "topic": "第 62 次（100.3.27）", "code": "62-07", "n": 62, "q": "試列舉 5 種防止動力衝剪機械危害常用之安全裝置。(10 分)", "ans": "", "sol": "1.安全護圍：其性能以不使勞工身體之一部介入滑塊或刃物動作範圍之危險界限為度。\n2.防護式安全裝置：滑塊在動作中，能使勞工身體不致介入危險界限之虞。\n3.雙手操作式安全裝置：在手指自按下起動按鈕或操作控制桿脫手後；至該手達到危險界限前，能使滑塊等停止動作，又以雙手操作按鈕等，於滑塊動作中，手離開按鈕等時無法達到危險界限。\n4.拉開式或掃除式安全裝置：遇身體之一部份介入危險界限時，能隨著滑塊之動作使其脫離危險界限。\n5.感應式安全裝置：滑塊等在動作中，遇身體之一部介入危險界限時，能使滑塊停止動作。"},
{"id": "sk-cc-62-08", "topic": "第 62 次（100.3.27）", "code": "62-08", "n": 62, "q": "雇主對於作業中遭生物病原體污染之針具或尖銳物品扎傷之勞工，應建立扎傷感染災害調查制度及採取3項措施。請問：\n(一)本措施依何法令規定？(1分)\n(二)此3項措施之內容。(9分)", "ans": "", "sol": "(一)依勞工安全衛生設施規則第297-2條規定。\n(二)1.指定專責單位或專人負責接受報告、調查、處理、追蹤及紀錄等事宜，相關紀錄應留存三年。\n2.調查扎傷勞工之針具或尖銳物品之危害性及感染源。但感染源之調查需進行個案之血液檢查者，應經當事人同意後始得為之。\n3.調查結果勞工有感染之虞者，應使勞工接受特定項目之健康檢查，並依醫師建議，採取對扎傷勞工採血檢驗與保存、預防性投藥及其他必要之防治措施。", "old": 1},
{"id": "sk-cc-62-09", "topic": "第 62 次（100.3.27）", "code": "62-09", "n": 62, "q": "請製作局部排氣裝置氣罩之吸氣能力測定紀錄表。(10 分)", "ans": "", "sol": "", "fig": "局部排氣裝置氣罩之吸氣能力測定紀錄表\n| 事業單位名稱 |  | 地址 |  |\n| --- | --- | --- | --- |\n| 檢查時間年月日 |  | 檢查者 |  |\n| 系統所在之場所 |  | 系統略圖 |  |\n| 測定孔 | 氣罩及導管之狀況(凹凸缺損閉塞應加修繕等情形 | 氣罩之吸氣：檢查時 靜壓 mmH₂O | 氣罩之吸氣：檢查時 風量 m³/min | 氣罩之吸氣：設計時 靜壓 mmH₂O | 氣罩之吸氣：設計時 風量 m³/min |\n| --- | --- | --- | --- | --- | --- |\n| A |  |  |  |  |  |\n| B |  |  |  |  |  |\n| C |  |  |  |  |  |"},
{"id": "sk-cc-62-10", "topic": "第 62 次（100.3.27）", "code": "62-10", "n": 62, "q": "某營造公司僱用勞工 100 人，一月份總經歷工時為 20000 小時，其 1 月份全月災變紀錄僅記載於1月6日上午8時發生事故，致甲勞工左手臂截肢(損失日數 3000 日)；乙勞工受傷於事發當日住院，並於 1 月 13 日恢復；丙勞工受傷回家休養，翌日 8 時恢復上班工作，試計算該公司該月失能傷害頻率及失能傷害嚴重率？(計算時應列出公式)(10 分)", "ans": "", "sol": "1.甲勞工左手臂截肢，損失日數3000日。\n2.乙勞工受傷於1月6日事發當日住院，並於1月13日恢復，計算1月7日至1月12日，共計6日。\n3.丙勞工受傷回家休養，翌日8時恢復上班工作，屬輕傷害，不列入統計。\n4.失能傷害人次數為2次。\n5.失能傷害損失日數為3006日。\n6.失能傷害頻率(FR)=(失能傷害人次數×1000000)/總歷經工時\n=(2×1000000)/20000=100\n7.失能傷害嚴重率(SR)=(失能傷害損失日數×1000000)/總歷經工時\n=(3006×1000000)/20000=150300"},
{"id": "sk-cc-63-01", "topic": "第 63 次（100.7.24）", "code": "63-01", "n": 63, "q": "甲鑄造公司現埸有固定式起重機一部，某日雇主指示勞工使用纖維索從事模具吊掛作業時，因吊鉤未有防止吊物脫落之裝置，導致纖維索從吊鉤滑出，吊起之模具掉落，撞擊在旁作業之另一名勞工致死，試問：\n(一)依勞工安全衛生法所定罰則，造成此種職業災害，得對該公司負責人及該公司分別處以何種刑事責任?(4 分)\n(二)該公司如改以鋼索作為吊掛用具，依勞工安全衛生設施規則規定，該鋼索在那些情況下不能使用?(至少列 3 項)(6 分)", "ans": "", "sol": "(一)對該公司負責人處以三年以下有期徒刑、拘役或科或併科新臺幣十五萬元以下罰金。對該公司亦科以新臺幣十五萬元以下罰金。（出自安衛法31條）\n(二)該鋼索在下列情況下不能使用：（出自勞工安全衛生設施規則第99條）\n1、鋼索一撚間有百分之十以上素線截斷者。\n2、直徑減少達公稱直徑百分之七以上者。\n3、有顯著變形或腐蝕者。\n4、已扭結者。", "old": 1},
{"id": "sk-cc-63-02", "topic": "第 63 次（100.7.24）", "code": "63-02", "n": 63, "q": "試以下列圖示某一建築工程，其各公司勞工共同作業之情形為例，回答下列問題：\n(一)依勞工安全衛生組織管理及自動檢查辦法規定，說明 A、B、C 公司應如何設置勞工安全衛生單位及人員?(6 分)\n(二)該工程如樓板高度超過 50 公尺以上者，依危險性工作場所審查暨檢查辦法規定，A 公司應於事前檢附何種資料及文件向當地勞動檢查機構申請審查?(4 分)", "ans": "", "sol": "(一) A 公司（共 105 人）：應設置直接隸屬雇主之專責一級勞工安全衛生單位及設置管理人員為營造業甲種勞工安全衛生業務主管及勞工安全衛生管理員各 1 人。\nB 公司（共 25 人）：應設置營造業丙種勞工安全衛生業務主管 1 人。\nC 公司（共 70 人）：應設置營造業乙種營造安全衛生業務主管及勞工安全衛生管理員各 1 人。\n(二) A 公司應於事前填具申請書，並檢附下列資料、施工安全評估人員簽認文件及相關專業技師簽證文件各三份，向當地勞動檢查機構申請審查：（出自危險性工作場所審查暨檢查辦法第17 條 ）\n一、施工計畫書。\n二、施工安全評估報告書。", "fig": "組織圖：建築公程 A公司，10人 → 施工架組配工程 B公司，25人／結構工程 C公司，20人。\n結構工程 C公司，20人 → 模板組立 D公司，35人／鋼筋組立 E公司，15人。", "old": 1},
{"id": "sk-cc-63-03", "topic": "第 63 次（100.7.24）", "code": "63-03", "n": 63, "q": "乙石化廠準備進行塔槽之年度歲修作業，須搭設高度超過5公尺之施工架，為防止勞工作業時發生墜落災害，依營造安全衛生設施標準規定，該事業單位在擬定墜落災害防止計畫時，應依那些項目訂定適當災害防止設施?(至少列出5項)(10分)", "ans": "", "sol": "(依據營造安全衛生設施標準第17條)擬定墜落災害防止計畫時，應依下列項目訂定適當災害防止設施：\n1、經由施工程序之變更，優先施作永久構造物之上下昇降設備或防墜設施。\n2、設置護欄、護蓋。\n3、張掛安全網。\n4、使勞工佩掛安全帶。\n5、設置警示線系統。\n6、限制作業人員進入管制區。"},
{"id": "sk-cc-63-04", "topic": "第 63 次（100.7.24）", "code": "63-04", "n": 63, "q": "國際潮流趨向「源頭管制」的概念來消除危害，依勞工安全街衛生組織管理及自動檢查辦法規定，採購管理應包含哪些項目?(10 分)", "ans": "", "sol": "第一類事業勞工人數在三百人以上之事業單位，採購管理應包含下列項目：\n1、機械、器具、設備、物料、原料及個人防護具等之採購、租賃，其契約內容應有符合法令及實際需要之勞工安全衛生具體規範，並於驗收、使用前確認其符合規定。\n2、將營繕工程之施工、規劃、設計及監造等交付承攬或委託，其契約內容應有防止職業災害之具體規範，並列為履約要件。\n3、執行紀錄應保存三年。\n(依據勞工安全街衛生組織管理及自動檢查辦法第12－4條)"},
{"id": "sk-cc-63-05", "topic": "第 63 次（100.7.24）", "code": "63-05", "n": 63, "q": "製造業常使用堆高機從事零配件或物料搬運，試簡述發生勞工被堆高機撞擊的5項主要災害原因。(10分)", "ans": "", "sol": "（依據勞工安全衛生設施規則第 124~128 條）\n1.對於荷重在一公噸以上之堆高機，未指派經特殊安全衛生教育、訓練合格人員操作。\n2.對於堆高機之操作，超過該機械所能承受之最大荷重，且其載運之貨物未保持穩固狀態，以致翻倒撞擊。\n3.未妥善規劃堆高機行車動線及人員作業活動區域。\n4.搬運物品堆疊太高致妨礙操作員視線。\n5.勞工違規站立於堆高機貨叉上從事作業，因操作員失誤而被堆高機撞擊。\n6.堆高機用畢後，未將貨叉放下、鑰匙拔起及手煞車拉起致停放斜坡上容易移動翻倒。", "old": 1},
{"id": "sk-cc-63-06", "topic": "第 63 次（100.7.24）", "code": "63-06", "n": 63, "q": "丙化學有限公司儲存及使用某一種化學物質，其容器危害標示如下。依據危險物與有害物標示及通識規則規定，此圖示可能代表危害物質之危害分類(例如：易燃氣體)為何?\n(至少列出5種，不含易燃氣體)(10分)", "ans": "", "sol": "可能代表危害物質之危害分類為：(任選五種作答)\n1.易燃氣膠\n2.易燃液體\n3.易燃固體\n4.發火性液體\n5.發火性固體\n6.自熱物質\n7.禁水性物質", "fig": "圖式：紅色菱形外框內為黑色火焰。"},
{"id": "sk-cc-63-07", "topic": "第 63 次（100.7.24）", "code": "63-07", "n": 63, "q": "在工業火災、爆炸災害中，靜電火花是主要危害源之一，請簡述預防靜電危害所造成火災、爆炸之方法有那些?(至少列出 5 種方法)(10 分)", "ans": "", "sol": "1.接地及搭接：製程中因摩擦、感應或傳導等產生的靜電危害藉由接地及搭接將能量釋放。\n2.增加濕度：在高溼度環境中，可降低物質的表面電阻，增加電荷散逸速度，達成電荷蓄積程度降低。\n3.使用抗靜電材料：使用物質表面或體積電阻係數愈低的材料，即可避免物質蓄積過量的靜電，如棉、碳粉等。\n4.使用靜電消除器：利用高壓電將空氣電離產生帶電離子，可使帶靜電物體的電荷被中和達成蓄積電荷至最低。\n5.限制速度：對於易燃液體的輸送作業限制其流速以消除製程中潛在靜電的來源。"},
{"id": "sk-cc-63-08", "topic": "第 63 次（100.7.24）", "code": "63-08", "n": 63, "q": "勞工作業環境空氣中粉麈之粒徑大小，會影響其化學性危害程度。試問：\n(一)同－種粉麈，較大粒徑與較小粒徑者，何者之化學性危害較高?(2 分)\n(二)其原因為何?(至少列出 2 項)(8 分)", "ans": "", "sol": "(一)較小粒徑者之化學性危害較高。\n(二)其原因如下：粉麈為粒狀物質，係固體粒子之浮游於空氣中者，一般粒徑在 100μm 以下，但粒徑在 10μm 以上者進入至肺部之機會不大，但粒徑在 10μm 以下者，鼻孔無法截留，會進入呼叫器官，少部附著於氣管，可藉纖毛運動排出，但 0.1μm 左右之粉麈則進入肺部沉著，經久累積後形成塵肺症，危害人體健康。"},
{"id": "sk-cc-63-09", "topic": "第 63 次（100.7.24）", "code": "63-09", "n": 63, "q": "有關高溫作業熱危害預防，以綜合溫度熱指數(WBGT)作為熱危害評估之指標‧試問：\n(一)其考量之氣候因素有那些?(4 分)\n(二)計算公式為何?(6 分)", "ans": "", "sol": "(一)考量之氣候因素：空氣溫度、空氣濕度、氣流及與輻射熱(溫濕四要素)\n(二) WBGT(綜合溫度熱指數)，Tnwb(自然濕球溫度)，Tgb(黑球溫度)，Tdb(乾球溫度)\n1.戶內或戶外無日曬時：WBGT＝0.7×Tnwb＋0.3Tgb\n2.戶外有日曬時：WBGT＝0.7Tnwb+ 0.2 Tgb＋0.1Tdb"},
{"id": "sk-cc-63-10", "topic": "第 63 次（100.7.24）", "code": "63-10", "n": 63, "q": "某－外裝型氣罩之開口面積(A)為 1 平方公尺，控制點與開口距離(x)為 1公尺。今將氣罩開口與控制點之距離縮短為 0.5 公尺，則風量(Q)可減少為原來之幾倍時，仍可維持控制點原有之吸引風速(v)?\n(參考公式Q＝v(10x²+A))(請列出計算過程)(10 分)", "ans": "", "sol": "設原控制點的風速為V₀，風量為 Q₀，x為 1則該處之風量 Q₀＝V₀(10×1²+1)= 11 V₀距離x若縮短為 0.5 公尺，設此新控制點之風速為V₁，風量為 Q₁\n則此控制點之風量 Q₁=V₁(10×0.5²+1)= 3.5 V₁\n若仍須維持控制點原有之吸引風速(v)，則V₁＝V₀\n因此 Q₁=V₁(10×0.5²+1)= 3.5 V₁＝3.5 V₀\nQ₁：Q₀＝3.5 V₀：11 V₀＝3.5÷11＝0.318\nQ₁＝0.318 Q₀亦即風量(Q)可減少為原來之 0.318 倍。"},
{"id": "sk-cc-64-01", "topic": "第 64 次（100.11.13）", "code": "64-01", "n": 64, "q": "某化工廠內設有殺菌鍋(容器內壓力已超過 1 大氣壓)及蒸汽鍋爐(傳熱面積為 350cm²)各 1 台，試回答下列問題：\n(一)依勞工安全衛生教育訓練規則規定，其操作人員應分別經何種安全衛生教育訓練合格始得擔任?( 6 分)\n(二)該工廠最近新購 1 部高空工作車，依勞工安全衛生組織管理及自動檢查辦法規定，每月應實施自動檢查的項目包括那些?(至少列 2 項，6 分)", "ans": "", "sol": "(一)\n1.容器內壓力已超過 1 大氣壓的殺菌鍋，屬第一種壓力容器，應經具有危險性設備操作人員之安全衛生教育訓練之第一種壓力容器操作人員訓練合格者擔任。（依據勞工安全衛生教育訓練規則第13 條）\n2.傳熱面積 350cm²＝0.35 m²之蒸汽鍋爐為小型鍋爐應經特殊安全衛生教育訓練之小型鍋爐操作人員訓練合格者擔任。（依據勞工安全衛生教育訓練規則第14 條）\n(二) （依據勞工安全衛生組織管理及自動檢查辦法第15-2 條，任選2 項）\n1.制動裝置、離合器及操作裝置有無異常。\n2.作業裝置及油壓裝置有無異常。\n3.安全裝置有無異常。", "old": 1},
{"id": "sk-cc-64-02", "topic": "第 64 次（100.11.13）", "code": "64-02", "n": 64, "q": "雇主對於固定式起重機之使用，以吊物為限，不得乘載或吊升勞工從事作業。但所從事之作業尚無其他安全作業替代方法，或臨時性，小規模、短時間、作業性質特殊，經採取防止墜落等措施，不在此限。依起重升降機具安全規則規定，有關此防止墜落措施，請至少列出 4 項搭乘設備應規定或辦理之事項。( 12 分)", "ans": "", "sol": "（依據起重升降機具安全規則第20條）\n1、搭乘設備應有足夠強度，其使用之材料不得有影響構造強度之損傷、變形或腐蝕等瑕疵。\n2、搭乘設備周圍設置高度九十公分以上之扶手，並設中欄杆及腳趾板。\n3、搭乘設備之懸吊用鋼索或鋼線之安全係數應在十以上；吊鏈、吊帶及其支點之安全係數應在五以上。\n4、依搭乘設備之構造及材質，計算積載之最大荷重，並於搭乘設備之明顯易見處，標示自重及最大荷重。"},
{"id": "sk-cc-64-03", "topic": "第 64 次（100.11.13）", "code": "64-03", "n": 64, "q": "快樂化學公司指派勞工王大明進入儲存硫酸儲槽內部從事內襯檢查作業，依特定化學物質危害預防標準規定，請至少列舉 6 項應採取之措施。(18 分)", "ans": "", "sol": "硫酸屬特定化學丁類物質，快樂化學公司指派勞工王大明進入儲存硫酸儲槽內部從事內襯檢查作業，應依下列規定：\n1、派遣特定化學物質作業主管從事監督作業。\n2、決定作業方法及順序，於事前告知從事作業之勞工。\n3、確實將該物質自該作業設備排出。\n4、為使該設備連接之所有配管不致流入該物質，應將該閥、旋塞等設計為雙重開關構造或設置盲板等。\n5、依前款規定設置之閥、旋塞應予加鎖或設置盲板，並將「不得開啟」之標示揭示於顯明易見之處。\n6、作業設備之開口部，不致流入該物質至該設備者，均應予開放。\n7、使用換氣裝置將設備內部充分換氣。\n8、以測定方法確認作業設備內之該物質濃度未超過容許濃度。\n9、拆卸第四款規定設置之盲板等時，有該物質流出之虞者，應於事前確認在該盲板與其最接近之閥或旋塞間有否該物質之滯留，並採取適當措施。\n10、在設備內部應置發生意外時能使勞工立即避難之設備或其他具有同等性能以上之設備。\n11、供給從事該作業之勞工穿著不浸透性防護衣、防護手套、防護長鞋、呼吸用防護具等個人防護具。\n(依據特定化學物質危害預防標準第30條，任選6項)", "fig": "圖：直立圓筒形儲槽，槽頂有開口，槽側上方與下方各有連接配管及閥；一名勞工站在儲槽右下方。"},
{"id": "sk-cc-64-04", "topic": "第 64 次（100.11.13）", "code": "64-04", "n": 64, "q": "祥好油漆公司指派勞工李小玲從事甲苯與二甲苯拌合作業，作業前已做好整理及清潔工作，您是勞工安全衛生管理員，試列出現場除火災爆炸外之主要的安全與健康危害各 1 項? ( 4 分)該項危害應探取那些主要工程改善措施？(試列出 3 項，6 分)", "ans": "", "sol": "(一)主要危害\n1.安全危害：被捲被夾。\n2.健康危害：引起皮膚炎。\n(二) 主要工程改善措施甲苯與二甲苯均屬第二種有機溶劑，從事甲苯與二甲苯拌合作業應設置：\n1.密閉設備\n2.局部排氣裝置\n3.整體換氣裝置(依據有機溶劑中毒預防規則第6條規定)", "fig": "圖：一個上方開口的拌合槽，槽內有由上方馬達帶動之攪拌葉片；勞工站在槽旁。", "old": 1},
{"id": "sk-cc-64-05", "topic": "第 64 次（100.11.13）", "code": "64-05", "n": 64, "q": "在實務上，－般常提到所謂標準作業程序(SOP)，而在工安方面所強調是安全作業標準(Safety Operation Standard)，試問在訂定安全作業標準之前必須進行何項分析?( 2 分)，其進行之 4 項主要程序為何?( 8 分)", "ans": "", "sol": "(一)在訂定安全作業標準之前必須進行「工作安全分析」。\n(二)1.決定要分析的工作\n2.將工作步驟分解\n3.辨識出潛在的危害\n4.決定安全的工作方法"},
{"id": "sk-cc-64-06", "topic": "第 64 次（100.11.13）", "code": "64-06", "n": 64, "q": "試列舉4種有發生勞工墜落之虞之場所或設備( 8分)，並分別說明2種預防墜落之方法( 8分)", "ans": "", "sol": "1.高度二公尺以上工作場所邊緣及開口部分預防：（1）設置適當之護欄、握把、覆蓋等防護措施。\n（2）採取讓勞工使用安全帶。\n2.石綿、鐵皮板、瓦、木板、茅草、塑膠等材料構築之屋頂。\n預防：（1）於屋架上設置適當強度且寬度在三十公分以上之踏板。\n（2）裝設安全護網。\n3.以船舶運輸勞工前往作業場所預防：（1）不得超載。\n（2）備置救生衣及其他救生用具。\n4.水上作業預防：（1）使勞工穿上救生衣。\n（2）設置監視人員及救生設備。"},
{"id": "sk-cc-64-07", "topic": "第 64 次（100.11.13）", "code": "64-07", "n": 64, "q": "推動職場健康促進有許多優點，請依下列對象各提出 3 項益處：\n(一)企業組織( 6 分)\n(二)員工( 6 分)", "ans": "", "sol": "(一)企業組織的益處(以下任選3項)\n1.提升工作效率及服務品質\n2.降低健康照護與醫療保險支出\n3.減少罰款與訴訟之風險\n4.降低病假率\n5.降低員工流動率\n6.提振員工士氣\n7.正面企業形象\n(二)員工的益處(以下任選3項)\n1.促進健康\n2.提升工作效率及士氣\n3.維持勞動力、延長工作年限\n4.增加就業滿意度\n5.增加維護健康的技巧與知識\n6.健康的家庭與和樂的社區"},
{"id": "sk-cc-64-08", "topic": "第 64 次（100.11.13）", "code": "64-08", "n": 64, "q": "某工作場所有機械 1 台，經於 4 公尺遠處測定噪音為 85 分貝，如另 1 台相同之機械噪音於 4 公尺處測定亦為 85 分貝，假設各機械皆視為點音源，請回答下列問同題：(請列出計算過程)\n(一)如二機械置於同一處，於 4 公尺遠處測定之音壓級應為多少?(5 分)\n(二)又若共有 4 台同樣之機械置於該處時，測定結果應為若干?(5 分)(提示：噪音值L_{I}－L₂＝0 分貝時，修正值L＝3 分貝)", "ans": "", "sol": "(一) L_{I}－L₂＝85-85＝0 分貝，因修正值L＝3 分貝，故L＝85＋3＝88 分貝\n(二) 將 4 台分成兩組，每組之噪音均為 88 分貝，此時L_{I}－L₂＝88-88＝0 分貝，因修正值L＝3 分貝，故L＝88＋3＝91 分貝\n※另解：音源相加公式：\n(一)LP₁ = 10 log (10^{L1/10}＋10^{L2/10}＋……＋10^{LN/10})\n= 10 log (10^{85/10}＋10^{85/10})\n= 10 log10^{8.5} (1＋1)\n= 88.01（dB）\n(二)LP₂ = 10 log (10^{L1/10}＋10^{L2/10}＋……＋10^{LN/10})\n= 10 log (10^{85/10}＋10^{85/10}＋10^{85/10}＋10^{85/10})\n= 10 log10^{8.5} (1＋1＋1＋1)\n= 91.02（dB）"},
{"id": "sk-cc-65-01", "topic": "第 65 次（101.3.25）", "code": "65-01", "n": 65, "q": "某事業單位使勞工從事桿上變壓器更換作業(停電中)，採取由積載型吊卡車(移動式起重機)配合使用高空工作車從事作業，請問對於使用高空工作車作業應辦理那些事項？(至少列舉5項，10分)", "ans": "", "sol": "雇主對於使用高空工作車從事作業，應依下列事項辦理：\n1、除行駛於道路上外，應於事前依作業場所之狀況、高空工作車之種類、容量等訂定包括作業方法之作業計畫，使作業勞工周知，並指定專人指揮監督勞工依計畫從事作業。\n2、除行駛於道路上外，為防止高空工作車之翻倒或翻落，危害勞工，應將其外伸撐座完全伸出，並採取防止地盤不均勻沉陷、路肩之崩塌等必要措施。\n3、在工作台以外之處所操作工作台時，為使操作者與工作台上之勞工間之連絡正確，應規定統一指揮信號，並指定人員依該信號從事指揮作業等必要措施。\n4、不得搭載勞工。但乘坐席位及工作台，不在此限。\n5、不得超過高空工作車之積載荷重及能力。\n6、不得使高空工作車供為主要用途以外之用途。但無危害勞工之虞時，不在此限。\n7、除工作台相對於地面作垂直上升或下降之高空工作車外，使用高空工作車從事作業時，雇主應使該高空工作車工作台上之勞工佩帶安全帶。\n(依勞工安全衛生設施規則第128-1條規定，以上任選 5 項作答)", "old": 1},
{"id": "sk-cc-65-02", "topic": "第 65 次（101.3.25）", "code": "65-02", "n": 65, "q": "依勞工健康保護規則規定，試回答下列問題：\n(一)健康檢查紀錄應至少保存多少年？(2分)\n(二)雇主使勞工從事高溫作業，游離輻射作業、鉛作業等特別危害健康之作業，所建立健康管理資料庫，共分四級執行健康管理，請說明上述四級之定義。(8分)", "ans": "", "sol": "(一)健康檢查紀錄應至少保存 7 年。（依據勞工健康保護規則第12條）\n(二)特別危害健康作業四級健康管理之定義如下：（依據勞工健康保護規則第14條）\n1、第一級管理：特殊健康檢查或健康追蹤檢查結果，全部項目正常，或部分項目異常，而經醫師綜合判定為無異常者。\n2、第二級管理：特殊健康檢查或健康追蹤檢查結果，部分或全部項目異常，經醫師綜合判定為異常，而與工作無關者。\n3、第三級管理：特殊健康檢查或健康追蹤檢查結果，部分或全部項目異常，經醫師綜合判定為異常，而無法確定此異常與工作之相關性，應進一步請職業醫學科專科醫師評估者。\n4、第四級管理：特殊健康檢查或健康追蹤檢查結果，部分或全部項目異常，經醫師綜合判定為異常，且與工作有關者。"},
{"id": "sk-cc-65-03", "topic": "第 65 次（101.3.25）", "code": "65-03", "n": 65, "q": "對於車輛流通頻繁之道路上從事臨時性、短期性作業，為避免因車輛突入造成作業勞工被撞傷亡災害，應採取那些安全措施？(至少列舉 5 項，10 分)。", "ans": "", "sol": "雇主對於使用道路作業之工作場所，為防止車輛突入等引起之危害，應依下列規定辦理：\n1、從事挖掘公路施工作業，應依所在地直轄市、縣（市）政府審查同意之交通維持計畫，設置交通管制設施。\n2、作業人員應戴有反光帶之安全帽，及穿著顏色鮮明有反光帶之施工背心，以利辨識。\n3、與作業無關之車輛禁止停入作業場所。但作業中必須使用之待用車輛，其駕駛常駐作業場所者，不在此限。\n4、使用道路作業之工作場所，應於車流方向後面設置車輛出入口。但依周遭狀況設置有困難者，得於平行車流處設置車輛出入口，並置交通引導人員，使一般車輛優先通行，不得造成大眾通行之障礙。\n5、於勞工從事道路挖掘、施工、工程材料吊運作業、道路或樹養護等作業時，應於適當處所設置交通引導人員。\n6、所設置之交通引導人員如有被撞之虞時，應於該人員前方適當距離，另設置具有顏色鮮明施工背心、安全帽及指揮棒之電動旗手。\n(依勞工安全衛生設施規則第21-2條規定，以上任選 5 項作答)", "old": 1},
{"id": "sk-cc-65-04", "topic": "第 65 次（101.3.25）", "code": "65-04", "n": 65, "q": "臺灣職業安全衛生管理系統(TOSHMS)包括「政策」、「組織設計」、「規劃與實施」、「評估」及「改善措施」等五大要素，試說明「規劃與實施」中有那些重要事項？(請至少列出 5 項，10分)", "ans": "", "sol": "（一）先期審查組織應對現有的職業安全衛生管理系統及相關作法進行先期審查，並將結果予以文件化，且傳達給員工及利害相關者。\n（二）系統規劃、建立與實施組織應根據先期審查、管理審查的結果或其它可獲得的資料，訂定能夠滿足遵守國家法令規章，持續改善職業安全衛生績效，且有助於保護作業場所員工的職業安全衛生管理系統作法。\n（三）職業安全衛生目標組織依據職業安全衛生政策、先期審查或管理審查的結果，及利害相關者關切的課題，訂定符合相關安全衛生法令規章，具體、可量測且能達成的職業安全衛生目標。\n（四）預防與控制措施組織應建立及維持適當的程序，以持續辨識和評估各種影響員工安全衛生的危害及風險。\n（五）變更管理組織對於內部及外部的變化應評估其對職業安全衛生管理所產生的影響，並在變化之前採取適當的預防措施。\n（六）緊急應變措施組織應訂定維持緊急應變措施的作法，並提供全體員工相關的資訊和訓練，包括緊急應變措施的定期演練。\n（七）採購組織應訂定維持程序，確保在採購貨物與接受服務前確認符合國家法令規章及組織本身職業安全衛生的要求，且在使用前可達成各項安全衛生要求。\n（八）承攬組織應訂定維持程序，以確保組織的各項安全衛生要求適用於承攬商及其員工。\n(依據臺灣職業安全衛生管理系統指引，以上任選 5 項作答)"},
{"id": "sk-cc-65-05", "topic": "第 65 次（101.3.25）", "code": "65-05", "n": 65, "q": "下列左欄為有害物，請從右邊疾病欄中選出可能導致之相關疾病(單選)，答法如5E、2B(作答參考，非正確答案)。(10分)", "ans": "", "sol": "1 E、2 A、3 B、4 C、5 D", "fig": "| 有害物 | 疾病 |\n| --- | --- |\n| 1.石綿 | A.失明 |\n| 2.甲醇 | B.中樞神經中毒 |\n| 3.四烷基鉛 | C.白血病 |\n| 4.苯 | D.皮膚癌 |\n| 5.煤焦油 | E.肺癌 |"},
{"id": "sk-cc-65-06", "topic": "第 65 次（101.3.25）", "code": "65-06", "n": 65, "q": "某一化學原料製造廠，廠內有一地下水池，容積約2000公升，已密封兩年未使用，現在您接獲主管指示，需於三日內把水抽光，並入池刷洗乾淨。\n依照上述工作情境，您如何採取措施，確保工作安全順利完成。(請至少列出 4 項，10分)", "ans": "", "sol": "1、局限空間內危害之確認。\n2、局限空間內氧氣、危險物、有害物濃度之測定。\n3、通風換氣實施方式。\n4、電能、高溫、低溫及危害物質之隔離措施及缺氧、中毒、感電、塌陷、被夾、被捲等危害防止措施。\n5、作業方法及安全管制作法。\n6、進入作業許可程序。\n7、提供之防護設備之檢點及維護方法。\n8、作業控制設施及作業安全檢點方法。\n9、緊急應變處置措施。\n(依勞工安全衛生設施規則第 29-1 條規定，以上任選 5 項作答)", "old": 1},
{"id": "sk-cc-65-07", "topic": "第 65 次（101.3.25）", "code": "65-07", "n": 65, "q": "由職業傷害嚴重率及傷害頻率所呈現之指標，可瞭解事業單位過去年度之安全衛生工作績效，請說明「失能傷害頻率(Frequency Rate，FR)」及「失能傷害嚴重率(Severity Rate，SR)」之定義為何。(10 分)", "ans": "", "sol": "(一)失能傷害頻率(FR)：每百萬經歷工時中，所有失能傷害之人次數。\nFR＝失能傷害人次數x10⁶/總經歷工時\n(二)失能傷害嚴重率(SR)：每百萬經歷工時中，所有失能傷害之總損失日數。\nSR＝失能傷害總損失日數x10⁶/總經歷工時"},
{"id": "sk-cc-65-08", "topic": "第 65 次（101.3.25）", "code": "65-08", "n": 65, "q": "某一清洗作業勞工使用三氯乙烷為清潔劑，在25°C、一大氣壓下其暴露於三氯乙烷之情形如下：\n(一)08：00~12：00 C₁=350ppm\n(二)13：00~14：00 C₂=489ppm\n(三)14：00~17：00 C₃=100ppm\n已知：三氯乙烷之8小時日時量平均容許濃度為350ppm，不同容許濃度之變量係數值如下表：\n試回答下列問題：\n(一)該勞工全程工作日之時量平均暴露濃度為多少ppm？(6分)\n(二)試評估該作業勞工之三氯乙烷暴露是否符合規定？(4分)", "ans": "", "sol": "(一)依據勞工作業環境空氣中有害物容許濃度標準第4條\n時量平均暴露濃度＝(第一次某有害物空氣中濃度×工作時間＋第二次某有害物空氣中濃度×工作時間+…＋第ｎ次某有害物空氣中濃度×工作時間)/總工作時間\n＝(350 x 4 ＋489 x 1 ＋100 x 3)/8＝2189/8＝273.6 ppm\n(二) 依據勞工作業環境空氣中有害物容許濃度標準第8條勞工作業環境中三氯乙烷之濃度應符合下列規定：\n1.三氯乙烷之8小時日時量平均濃度273.6 ppm並未超過8小時日時量平均容許濃度350ppm，因此未超標。\n2.任何一次連續15分鐘內之時量平均濃度不得超過短時間時量平均容許濃度。\n三氯乙烷之短時間時量平均容許濃度(PEL-STEL)\n＝8小時日時量平均容許濃度(PEL-TWA) × 變量係數(EL)\n＝350 × 1.25 ＝437.5 ppm\n而在13：00~14：00 間C₂= 489ppm顯已超過標準。\n故整體評估該作業勞工之三氯乙烷暴露不符合規定。", "fig": "| 容許濃度(ppｍ或mg/m³) | ＜1 | ≧1，＜10 | ≧10，＜100 | ≧100，＜1000 | ≧1000 |\n| --- | --- | --- | --- | --- | --- |\n| 變量係數 | 3 | 2 | 1.5 | 1.25 | 1.0 |"},
{"id": "sk-cc-65-09", "topic": "第 65 次（101.3.25）", "code": "65-09", "n": 65, "q": "某家金屬加工廠為確保作業安全，欲採購一批已通過型式檢定的動力衝剪機械及研磨輪，請問：\n(一)何謂型式檢定？(5分)\n(二)採購人員應如何辨別該等機械、器具已通過型式檢定？(5分)", "ans": "", "sol": "(一)「型式檢定」，係為檢定經大量生產之機械、器具等製成品，能符合該防護標準之要求，於成品中以一定比例數為樣品檢定外，並對為同一型式製品間之品質穩定，檢定其製造、檢查設備及檢查組織體系等，以確認製品之安全性，對與檢定合格製品同一型式之製品，將合格之標示張貼於該機械、器具供辨識，而非逐台實施之「個別檢定」。(依台勞安二字第 4269 號解釋令)\n(二)凡經型式檢定合格之動力衝剪機械及研磨輪之本體明顯處，會張貼型式檢定合格標章，以資識別。但如因本體太小或有其他特殊原因無法標示時，也會以中央主管機關認可之其他方式標示之。(依機械器具型式檢定實施辦法第14條規定)"},
{"id": "sk-cc-65-10", "topic": "第 65 次（101.3.25）", "code": "65-10", "n": 65, "q": "為預防感電災害，常採取各項電氣接地措施，試說明何謂系統接地及設備接地。(10 分)", "ans": "", "sol": "(依據屋內線路裝置規則第 24 條)\n(一) 系統接地：可分為下列兩種\n1、內線系統接地：屋內線路屬於被接地一線之再行接地。\n2、低壓電源系統接地：配電變壓器之二次側低壓線或中性線之接地。\n(二) 設備接地：高低壓用電設備非帶電金屬部分之接地。亦即將電氣設備得金屬製外箱(殼)等，以導體與大地作良好的電氣性連接(例如馬達外殼接地)，希能維持該外箱(殼)與大地是同電位。"},
{"id": "sk-cc-66-01", "topic": "第 66 次（101.7.22）", "code": "66-01", "n": 66, "q": "依勞動檢查法規定，勞動檢查機構之勞動檢查員到廠場實施安全衛生檢查時，發現勞工有立即發生危險之虞時，得就該場所以書面通知逕予先行停工。\n(一)請列出有立即發生危險之虞之 5 種災害類型。(5 分)\n(二)勞動檢查員執行那 3 項檢查事項，得事先通知事業單位?(3 分)", "ans": "", "sol": "(一)【依勞動檢查法第二十八條所定勞工有立即發生危險之虞認定標準第2條規定】\n1、墜落。\n2、感電。\n3、倒塌、崩塌。\n4、火災、爆炸。\n5、中毒、缺氧。\n(二)【依勞動檢查法第13條規定】\n1、勞動檢查法第二十六條規定之危險性工作場所審查或檢查。\n2、危險性機械或設備檢查。\n3、職業災害檢查。", "old": 1},
{"id": "sk-cc-66-02", "topic": "第 66 次（101.7.22）", "code": "66-02", "n": 66, "q": "某物流公司擬將物料儲存於鋼筋混凝土造之庫房內堆放，則其應注意不得有那些不當的危險作為?請依勞工安全衛生設施規則規定至少列出5項。(10分)", "ans": "", "sol": "【依勞工安全衛生設施規則第159條規定】雇主對物料之堆放，應依下列規定：\n1、不得超過堆放地最大安全負荷。\n2、不得影響照明。\n3、不得妨礙機械設備之操作。\n4、不得阻礙交通或出入口。\n5、不得減少自動灑水器及火警警報器有效功用。\n6、不得妨礙消防器具之緊急使用。\n7、以不倚靠牆壁或結構支柱堆放為原則。並不得超過其安全負荷。\n（以上任選5項作答）", "old": 1},
{"id": "sk-cc-66-03", "topic": "第 66 次（101.7.22）", "code": "66-03", "n": 66, "q": "張先生的舊公寓準備重新裝潢，便委由某土木包工業承攬施作室內磚造隔間牆之拆除，請問該土木包工業者對於磚牆之拆除，依規定應採取那 5項安全措施?(10 分)", "ans": "", "sol": "【依營造安全衛生設施標準第 161 條規定】\n1、自上至下，逐次拆除。\n2、拆除無支撐之牆時，應以適當支撐或控制，避免其任意倒塌。\n3、以拉倒方式進行拆除時，應使勞工站立於作業區外，並防範破片之飛擊。\n4、無法設置作業區時，應設置承受台、施工架或採取適當防範措施。\n5、以人工方式切割時，應採取防止粉塵之適當措施。"},
{"id": "sk-cc-66-04", "topic": "第 66 次（101.7.22）", "code": "66-04", "n": 66, "q": "某石化工廠，勞工人數達 350 人，已建制及推動職業安全衛生管理系統多年，最近擬向中央主管機關提出職業安全衛生管理系統績效之認可。依事業單位職業安全衛生管理系統績效認可作業要點規定，必須檢附職業安全衛生管理系統績效自評表，請至少列出 7 項自評項目。(14 分)", "ans": "", "sol": "【依事業單位職業安全衛生管理系統績效認可作業要點附件三內容】\n1、安全衛生政策。\n2、危害辨識、評估及風險控制。\n3、重大風險之作業管制。\n4、變更管理。\n5、採購管理。\n6、承攬管理。\n7、作業環境測定。\n8、事件通報與統計。\n9、職場健康管理與健康促進。\n(以上任選7項作答)"},
{"id": "sk-cc-66-05", "topic": "第 66 次（101.7.22）", "code": "66-05", "n": 66, "q": "目前中央主管機關已經陸續公告勞工安全衛生教育訓練結訓測驗須採技術士技能檢定方式辦理之訓練種類，請至少列出 4 種。(8 分)", "ans": "", "sol": "目前已經陸續公告如下：\n1、荷重在一公噸以上之堆高機操作人員(自 98.9.1 生效)\n2、吊升荷重在三公噸以上之固定式起重機操作人員(自 100.7.1 生效)\n3、吊升荷重在三公噸以上之移動式起重機操作人員(自 100.7.1 生效)\n4、第一種壓力容器操作人員(自 101.9.1 生效)\n5、乙級鍋爐操作人員(自 102.1.1 生效)\n6、丙級鍋爐操作人員(自 102.1.1 生效)(以上任選 4 項作答，括弧內時間供參考)", "old": 1},
{"id": "sk-cc-66-06", "topic": "第 66 次（101.7.22）", "code": "66-06", "n": 66, "q": "(一)請至少列出 5 種不同防護類型之手套。(5 分)\n(二)作業環境有使用氫氟酸、硝酸、硫酸，某作業人員感覺手指疼痛，並發現手套疑似有裂縫。您如何對該傷患做緊急處置?(5 分)", "ans": "", "sol": "(一)不同防護類型之手套：\n1、從事物料搬運作業之棉紗手套。\n2、從事酸、鹼、礦植物油及化學藥品等職業衛生用防護手套。\n3、從事熔接、電焊用防護皮手套。\n4、從事 X 射線診療時所用之 X 射線輻射防護手套。\n5、從事局部振動作業之防振手套。\n6、從事電氣活線作業之絕緣橡膠手套。\n7、從事成衣裁剪作業之鐵手套。\n(以上任選 5 項作答)\n(二)作業環境有使用酸鹼化學物質致腐蝕皮膚，應對該傷患做如下緊急處置：\n1、沖：用流動的冷水沖洗該疼痛之手指 15~30 分鐘。\n2、脫：在水中小心地除去手套。\n3、泡：將手指放在冷水中浸泡 15~30 分鐘。\n4、蓋：覆蓋乾淨的毛巾。\n5、送：趕快送醫診治。"},
{"id": "sk-cc-66-07", "topic": "第 66 次（101.7.22）", "code": "66-07", "n": 66, "q": "有輛硝酸槽車預備在工廠經由管線將硝酸自槽車抽出，並灌裝於場區硝酸槽體，槽車開口距地面約 3 公尺，請至少列出 5 項有關槽車卸收安全作業要項。(10 分)", "ans": "", "sol": "【依勞工安全衛生設施規則第\n186、178 條規定】\n1、使用槽車從事灌注或卸收作業前，槽車之引擎應熄火，且設置適當之輪擋，以防止作業時車輛移動。作業結束後，並確認不致因引擎啟動而發生危害後，始得發動。\n2、應事先確定軟管結合部分已確實連接牢固始得作業。作業結束後，應確認管線內已無引起危害之殘留物後，管線始得拆離。\n3、指定輸送操作人員操作輸送設備，並監視該設備及其儀表。\n4、輸送腐蝕性物質管線，應標示該物質之名稱、輸送方向及閥之開閉狀態。\n5、槽車卸放時（槽車開口距地面約3公尺）操作人員應繫掛安全帶，以防墜落。", "old": 1},
{"id": "sk-cc-66-08", "topic": "第 66 次（101.7.22）", "code": "66-08", "n": 66, "q": "為預防化學性危害，請針對該危害發生源，至少列出5項預防對策。(10分)", "ans": "", "sol": "【參考中華民國工業安全衛生協會教材/化學性危害預防/化學因子危害之預防】\n1、以低毒性、低危害性物料取代。\n2、作業方法、作業程序之變更。\n3、製程之隔離，包括時間與空間。\n4、製程之密閉。\n5、濕式作業。\n6、局部排氣裝置之設置。\n7、控制設備之良好維護保養計畫，維持有效控制能力。\n(以上任選 5 項作答)"},
{"id": "sk-cc-66-09", "topic": "第 66 次（101.7.22）", "code": "66-09", "n": 66, "q": "依職業促發腦血管及心臟疾病(外傷導致者除外)之認定參考指引，評估工作負荷與過勞之相關，應考量勞工於發病前是否有異常的事件，短期工作過重、長期工作過重三要件。請說明此三要件，分別係指勞工發病前多少期間內之工作負荷。 (10分)", "ans": "", "sol": "【依勞委會職業促發腦血管及心臟疾病(外傷導致者除外)之認定參考指引】\n1、異常的事件：評估發病當時至發病前一天的期間內。(是否持續工作或遭遇到天災或火災等嚴重之異常事件，且能明確的指出狀況發生時的時間及場所。當遭遇事件時會引起急遽的血壓波動及血管收縮，導致腦血管及心臟疾病發病，即可證實異常事件、負荷過重之存在，而此事件的過重程度可以事故的大小、被害或加害的程度、恐懼感或異常性的程度等綜合且客觀的判斷。)\n2、短期工作過重：評估發病前（包含發病日）約 1 週內。(勞工是否從事特別過重的工作，該過重的工作係指與日常工作相比，客觀的認為造成身體上、精神上負荷過重的工作，其評估內容除可考量工作量、工作內容、工作環境等因素外，亦可由同事或同業是否認為負荷過重的觀點給予客觀且綜合的判斷。)\n3、長期工作過重：評估發病前約 6 個月內。(是否因長時間勞動造成明顯疲勞的累積。其間，是否從事特別過重之工作及有無負荷過重因子係以「短期工作過重」為標準。而評估長時間勞動之工作時間，係以每兩週 84 小時工時以外之時數計算加班時數。)(以上括弧內說明供參考)"},
{"id": "sk-cc-66-10", "topic": "第 66 次（101.7.22）", "code": "66-10", "n": 66, "q": "下表為某一固定管徑之導管內4個測點所測得空氣壓力(air pressure)值，試求表中a、b、c、d、e等5項之相關壓力值(請列出計算過程)。(10分)", "ans": "", "sol": "因為全壓(TP)、靜壓（SP）、動壓（VP）之間關係如下:\nTP＝SP+VP\n(一)在測點 1 之a處之空氣壓力值＝（＋3）＋（＋2）＝＋5 (mm H₂O)\n(二)在測點 2 之b處之空氣壓力值＝（－6）－（＋2）＝－8 (mm H₂O)\n(三)在測點 3 之c處之空氣壓力值＝（＋7）－（＋2）＝＋5 (mm H₂O)\n(四)又因為該導管為固定管徑，故在導管內之空氣流率 Q＝V X A 式中之 A是導管截面積為定值，而從測點 1 至 3 之 VP 值亦均為+2，故由公式\nVP＝(V /4.04)²可得知平均風速V亦為定值，因此可推論：\n在測點 4 之e處之空氣壓力值＝＋2 (mm H₂O)\n(五)在測點 4 之d處之空氣壓力值＝（－4）＋（＋2）＝－2 (mm H₂O)", "fig": "空氣壓力(mmH₂O)\n| 測點 | 全壓(TP) | 靜壓(SP) | 動壓(VP) |\n| --- | --- | --- | --- |\n| 1 | (a) | +3 | +2 |\n| 2 | -6 | (b) | +2 |\n| 3 | +7 | (c) | +2 |\n| 4 | (d) | -4 | (e) |"},
{"id": "sk-cc-67-01", "topic": "第 67 次（101.11.11）", "code": "67-01", "n": 67, "q": "某五星級大飯店員工數340 人，請依勞工安全衛生法及其附屬法規規定，回答下列問題：\n(一) 列舉3 項應向當地勞動檢查機構報備之文件。(3 分)\n(二) 勞工安全衛生委員會應由那些人員組成？(至少列舉5 種，5 分)\n(三) 勞工安全衛生委員會之成員中，何者不應由雇主指定？(2 分)", "ans": "", "sol": "(一) 應向當地勞動檢查機構報備之文件：\n1. 勞工安全衛生管理單位(人員)設置(變更)報備書\n2. 勞工安全衛生工作守則\n3. 職業災害統計月報表\n(二) 勞工安全衛生委員會應下列人員組成：(任選五項)\n1、事業經營負責人或其代理人。\n2、勞工安全衛生人員。\n3、事業內各部門之主管、監督、指揮人員。\n4、與勞工安全衛生有關之工程技術人員。\n5、醫護人員。\n6、工會或勞工選舉之代表\n(三) 勞工安全衛生委員會之成員中，工會或勞工選舉之代表不應由雇主指定。", "old": 1},
{"id": "sk-cc-67-02", "topic": "第 67 次（101.11.11）", "code": "67-02", "n": 67, "q": "使用移動式起重機從事作業中，常易發生翻倒、被夾、感電等危害，為防止上述危害，依起重升降機具安全規則規定，雇主應於事前調查那些事項，以採取相關必要措施？（請列舉 5 項，10 分）", "ans": "", "sol": "【依起重升降機具安全規則第 29 條規定】雇主對於移動式起重機，為防止其作業中發生翻倒、被夾、感電等危害，應事前調查下列事項該起重機作業範圍之事項以採取相關必要措施：\n1.地形\n2.地質狀況\n3.作業空間\n4.運搬物重量\n5.所用起重機種類、型式及性能"},
{"id": "sk-cc-67-03", "topic": "第 67 次（101.11.11）", "code": "67-03", "n": 67, "q": "某公司內部擬建立、實施及維持符合職業安全衛生管理系統相關規範要求之採購管理制度，試依採購管理技術指引所定原則，回答下列問題：\n(一) 採購大致可分為那3 類？(6 分)\n(二) 在請購及交貨驗收階段應分別考量之安全衛生事項為何？(4 分)", "ans": "", "sol": "【依採購管理技術指引規定】\n（一）採購大致可分為以下三類：\n1、工程採購：係指在地面上下新建、增建、改建、修建、拆除構造物與其所屬設備及改變自然環境之工程。\n2、財物採購：係指各種物品、材料、設備、機具與其他動產、不動產、權利及其他經主管機關認定之財物。\n3、勞務採購：係指專業服務、技術服務、資訊服務、研究發展、營運管理、維修、訓練、勞力及其他經主管機關認定之勞務。\n(二) 在請購及交貨驗收階段應分別考量之安全衛生事項為：\n1、請購階段：訂定工程、財務或勞務之安全衛生規格，且應考量供應商提供的所有工程、財物或勞務之所有可能潛在危險。\n2、交貨驗收階段：依據契約相關規定及量測程序，確認供應商所提供的工程、財物或勞務符合相關安全衛生規格。"},
{"id": "sk-cc-67-04", "topic": "第 67 次（101.11.11）", "code": "67-04", "n": 67, "q": "有關壓氣沉箱、壓氣沉筒及壓氣潛盾等施工作業，請列舉 5 項高壓室內作業主管應注意採取之措施。(10 分)", "ans": "", "sol": "【依營造安全衛生設施標準第 106 條規定，雇主藉壓氣沉箱施工法、壓氣沉筒施工法、壓氣潛盾施工法等作業時，應選任高壓室內作業主管，辦理下列事項：】\n1.應就可燃物品於高氣壓狀況下燃燒之危險性，告知勞工。\n2.禁止攜帶火柴、打火機等火源，並將上項規定揭示於氣閘室外明顯易見之地點。\n3.禁止從事氣體熔接、熔斷或電焊等具有煙火之作業。\n4.禁止藉煙火、高溫或可燃物供作暖氣之用。\n5.禁止使用可能造成火源之機械器具。\n6.禁止使用可能發生火花或電弧之電源開關。\n7.規定作業人員穿著不易引起靜電危害之服裝及鞋靴。\n8.作業人員離開異常氣壓作業環境時，依異常氣壓危害預防標準辦理。\n(以上任選5項作答)"},
{"id": "sk-cc-67-05", "topic": "第 67 次（101.11.11）", "code": "67-05", "n": 67, "q": "請列舉 4 種屬於丁類危險性工作場所之營造工程。(10 分)", "ans": "", "sol": "1.建築物頂樓樓板高度在五十公尺以上之建築工程。\n2.橋墩中心與橋墩中心之距離在五十公尺以上之橋樑工程。\n3.採用壓氣施工作業之工程。\n4.長度一千公尺以上或需開挖十五公尺以上之豎坑之隧道工程。\n5.開挖深度達十五公尺以上或地下室為四層樓以上，且開挖面積達五百平方公尺之工程。\n6.工程中模板支撐高度七公尺以上、面積達一百平方公尺以上且佔該層模板支撐面積百分之六十以上者。\n(以上任選 5 項作答)"},
{"id": "sk-cc-67-06", "topic": "第 67 次（101.11.11）", "code": "67-06", "n": 67, "q": "雇主使勞工於缺氧危險場所作業時，應將那些注意事項公告於該作業場所入口明顯處，使作業勞工周知？(請列出5 項，10 分)", "ans": "", "sol": "【依缺氧症預防規則第 18 條規定】\n1.有罹患缺氧症之虞之事項。\n2.進入該場所時應採取之措施。\n3.事故發生時之緊急措施及緊急聯絡方式。\n4.空氣呼吸器等呼吸防護具、安全帶等、測定儀器、換氣設備、聯絡設備等之保管場所。\n5.缺氧作業主管姓名。"},
{"id": "sk-cc-67-07", "topic": "第 67 次（101.11.11）", "code": "67-07", "n": 67, "q": "依危險物與有害物標示及通識規則規定，雇主應提供物質安全資料表，試回答下列問題：\n(一) 列出4 種物質安全資料表之項目。(8 分)\n(二) 若裝有危險物之容器其容積在100 毫升以下，得如何標示？(2 分)", "ans": "", "sol": "(一)物質安全資料表應列內容項目：(任選四項)\n1.物品與廠商資料\n2.危害辨識資料\n3.成分辨識資料\n4.急救措施\n5.滅火措施\n6.洩漏處理方法\n7.安全處置與儲存方法\n8.暴露預防措施\n9.物理及化學性質\n10.安定性及反應性\n11.毒性資料\n12.生態資料\n13.廢棄處置方法\n14.運送資料\n15.法規資料\n16.其他資料\n(二) 若裝有危險物之容器其容積在 100 毫升以下者，得僅標示名稱、危害圖式及警示語。"},
{"id": "sk-cc-67-08", "topic": "第 67 次（101.11.11）", "code": "67-08", "n": 67, "q": "針對一般中央空調系統 60 公分× 60 公分之進氣口(air supply)，其風量之測定有2種方式，請簡述之。(10 分)", "ans": "", "sol": "1.風速測定法：以風速儀(Anemometer)量測此60cmx60cm正方形進氣口等分為16個方格面積(每個方格為15cm x 15cm)中心之風速為代表性之風速Va，再以下列公式計算出風量：\nV_{a}＝(∑_{i=1}^{n}V_{i})/n\n此處 n=16\n風量 Q(m3/min) ＝60 Va(m/s) x A (m) x B(m)\n＝60 Va(m/s) x 0.6 (m) x 0.6(m)＝21.6 Va\n2.壓力測定法：同樣將 60cmx60cm正方形進氣口等分為 16個方格面積(每個方格為15cm x 15cm)，然後使用皮氏管壓力計（pitot tube）、文氏管壓力計等壓力計測量各個進氣口方格之動壓（PV），再以 V＝4.04√PV公式換算成各個進氣口方格之風速 Vi；另以下列公式求得具代表性之平均風速(Va)，最後算出風量(Q)\nV_{a}＝(∑_{i=1}^{n}V_{i})/n\nQ(m³/min) =60×Va(m/s)×A(m²)\n＝60 × Va × ( 0.6 × 0.6 )\n＝21.6 Va", "fig": "圖：60cm×60cm正方形進氣口等分為4×4共16個方格，每格15cm×15cm；各格中心有一測點，箭頭標示「測點」。"},
{"id": "sk-cc-67-09", "topic": "第 67 次（101.11.11）", "code": "67-09", "n": 67, "q": "依勞工安全衛生設施規則規定，雇主對於作業中遭生物病原體污染之針具或尖銳物品扎傷之勞工，請列出4 項應有之作為。(10 分)", "ans": "", "sol": "【依勞工安全衛生設施規則第 297-2 條規定】\n1.指定專責單位或專人負責接受報告、調查、處理、追蹤及紀錄等事宜，相關紀錄應留存三年。\n2.調查扎傷勞工之針具或尖銳物品之危害性及感染源。但感染源之調查需進行個案之血液檢查者，應經當事人同意後始得為之。\n3.調查結果勞工有感染之虞者，應使勞工接受特定項目之健康檢查，並依醫師建議，採取對扎傷勞工採血檢驗與保存、預防性投藥及其他必要之防治措施。\n4.扎傷事故，於中央主管機關指定之事業單位，應依中央主管機關公告之期限、格式及方式通報。", "old": 1},
{"id": "sk-cc-67-10", "topic": "第 67 次（101.11.11）", "code": "67-10", "n": 67, "q": "有一框式鋼管施工架構築之移動式施工架，每層框架短邊(W)寬0.7 公尺、高1.8公尺，共組搭4 層框架，其腳部接續使用0.12 公尺高之腳輪(圖示如下)，試問：\n(一) 頂層工作台高度為幾公尺？(5 分)\n(二) 為防止使用移動式施工架作業之傾倒危險，該施工架短邊方向補助撐材之地面撐點與施工架之水平距離應至少幾公尺？(5 分)[參考公式：15.4X(水平距離)≧H(頂層工作台高度)+5-7.7W(短邊寬度)]", "ans": "", "sol": "(一) 頂層工作台高度 H＝ 0.12＋1.8×4＝7.32公尺\n(二) 為防止使用移動式施工架作業之傾倒危險，該施工架短邊方向補助撐材之地面撐點與施工架之水平距離應至少為：\n套用公式 15.4X(水平距離)≧H(頂層工作台高度)+5-7.7W(短邊寬度)]即 X ≧ ( H + 5 - 7.7 × W ) / 15.4將 H 及 W 值代入 ( 7.32 + 5 - 7.7 × 0.7 ) / 15.4＝0.45\n所以 X ≧0.45 公尺", "fig": "圖：四層框式移動施工架，下方有腳輪，兩側有向外伸出之斜向補助撐材；圖中標示頂層工作台高度H、短邊寬度W、撐材地面撐點與施工架之水平距離X。"},
{"id": "sk-cc-68-01", "topic": "第 68 次（102.3.24）", "code": "68-01", "n": 68, "q": "請依勞工安全衛生法之規定，回答下列問題：\n(一) 勞工安全衛生法適用範圍除該法所列舉及中央主管機關指定之各種事業外，中央主管機關亦得就事業之何部分指定適用？(4分)\n(二) 勞工如發現事業單位違反有關安全衛生之規定時，得向那些對象申訴？(3分)\n(三) 某位勞工經健康檢查發現其因職業原因導致不能適應原有工作時，雇主應採何種措施？", "ans": "", "sol": "(一) 中央主管機關得就事業之部分工作場所或特殊機械、設備指定適用本法。(勞工安全衛生法第4條)\n(二) 得向雇主、主管機關或檢查機構申訴。(勞工安全衛生法第30條)\n(三) 除予醫療外，並應變更其作業場所，更換其工作，縮短其工作時間及為其他適當措施。(勞工安全衛生法第 13 條)", "old": 1},
{"id": "sk-cc-68-02", "topic": "第 68 次（102.3.24）", "code": "68-02", "n": 68, "q": "勞工安全衛生教育訓練規則所規定之安全衛生教育訓練，大致可分為管理職類及技術職類，其中針對營造作業所訂定的主管類教育訓練有那些？請列舉 5 項。(10 分)", "ans": "", "sol": "【依勞工安全衛生教育訓練規則第 10 條規定】營造作業所訂定的主管類教育訓練如下：(以下任選五項作答)\n(一)擋土支撐作業主管。\n(二)露天開挖作業主管。\n(三)模板支撐作業主管。\n(四)隧道等挖掘作業主管。\n(五)隧道等襯砌作業主管。\n(六)施工架組配作業主管。\n(七)鋼構組配作業主管。", "old": 1},
{"id": "sk-cc-68-03", "topic": "第 68 次（102.3.24）", "code": "68-03", "n": 68, "q": "某工廠之生產線配置有空壓機、傳動馬達、傳動鏈條等，屬於會產生噪音之工作場所。請依勞工安全衛生設施規則規定，回答下述問題：\n(一) 若勞工8小時日時量平均音壓級超過85分貝，雇主應採取何種措施？(2分)\n(二) 若噪音超過90分貝，雇主應採取何種措拖？(8分)", "ans": "", "sol": "【依勞工安全衛生設施規則第 300 條規定】\n(一)對於勞工八小時日時量平均音壓級超過八十五分貝或暴露劑量超過百分之五十時，雇主應使勞工戴用有效之耳塞、耳罩等防音防護具。\n(二)勞工工作場所因機械設備所發生之聲音超過九十分貝時，雇主應採取工程控制、減少勞工噪音暴露時間，使勞工噪音暴露工作日八小時日時量平均不超過規定值或相當之劑量值，且任何時間不得暴露於峰值超過一百四十分貝之衝擊性噪音或一百十五分貝之連續性噪音；噪音超過九十分貝之工作場所，應標示並公告噪音危害之預防事項，使勞工周知。", "old": 1},
{"id": "sk-cc-68-04", "topic": "第 68 次（102.3.24）", "code": "68-04", "n": 68, "q": "某農產品加工公司勞工人數 1,500 人，已設安全衛生部門，並置有甲種勞工安全業務主管、勞工安全管理師及勞工安全衛生管理員。請依勞工安全衛生組織管理及自動檢查辦法規定，回答下列問題：\n(一) 分別說明勞工安全衛生業務主管與勞工安全衛生管理員之職責。(4分)\n(二) 該公司屬第一類事業，應訂定那些安全衛生管理文件？(請至少列舉3種，6分)", "ans": "", "sol": "（一）【依勞工安全衛生組織管理及自動檢查辦法第 5-1 條規定】勞工安全衛生業務主管及勞工安全衛生管理員之職責如下列：\n1.置有勞工安全（衛生）管理師、勞工安全衛生管理員事業單位之勞工安全衛生業務主管：主管及督導安全衛生管理事項。\n2.勞工安全（衛生）管理師、勞工安全衛生管理員：擬訂、規劃及推動安全衛生管理事項，並指導有關部門實施。\n（二）【依勞工安全衛生組織管理及自動檢查辦法第12-1~12-6條規定】應訂定之安全衛生管理文件如下：(以下任選三項作答)\n1.勞工安全衛生管理計畫\n2.勞工安全衛生管理規章\n3.承攬管理計畫\n4.緊急狀況預防、準備及應變之計畫", "old": 1},
{"id": "sk-cc-68-05", "topic": "第 68 次（102.3.24）", "code": "68-05", "n": 68, "q": "(一) 某工廠所使用之機械設備包括：1.具有捲入點之滾軋機 2.研磨機 3.離心機械依勞工安全衛生設施規則規定，其各應裝設何種安全防護裝置？\n(6分)\n(二) 雇主對於滾輾橡膠之滾輾機，應設置何種裝置，當災害發生時，使被害者能自行易於操縱，以降低災害程度？(4分)", "ans": "", "sol": "(一) 1.具有捲入點之滾軋機：護圍、導輪等。(設施規則78條)\n2.研磨機：防護罩(設施規則63條)\n3.離心機械：護蓋及連鎖裝置。(設施規則73條)\n(二)應於適當位置設置緊急制動裝置，立即遮斷動力並與剎車系統運動，於緊急時能立即停止原動機或動力傳動裝置之轉動。(設施規則79條)", "old": 1},
{"id": "sk-cc-68-06", "topic": "第 68 次（102.3.24）", "code": "68-06", "n": 68, "q": "張老闆為擴大產能，購買一間廠房，想把廁所之一面隔間牆及柱拆除。請問張老闆於拆除作業時，依營造安全衛生設施標準規定，應特別注意那些事項？(10分)", "ans": "", "sol": "【營造安全衛生設施標準 161 條規定】雇主於拆除結構物之牆、柱或其他類似構造物時，應依下列規定辦理：\n1、自上至下，逐次拆除。\n2、拆除無支撐之牆、柱或其他類似構造物時，應以適當支撐或控制，避免其任意倒塌。\n3、以拉倒方式進行拆除時，應使勞工站立於作業區外，並防範破片之飛擊。\n4、無法設置作業區時，應設置承受台、施工架或採取適當防範措施。\n5、以人工方式切割牆、柱或其他類似構造物時，應採取防止粉塵之適當措施。"},
{"id": "sk-cc-68-07", "topic": "第 68 次（102.3.24）", "code": "68-07", "n": 68, "q": "靜電之火花放電，常引起環境之可燃性氣體、易燃液體之蒸氣或粉塵發生火災爆炸，請列舉5種預防靜電災害之方法。(10分)", "ans": "", "sol": "1、接地與搭接：將所有具導電性之物件實施接地；另將隔離之金屬物件先以導線連接起來(搭接)再接地。\n2、增加濕度：以加濕器或水蒸氣噴出等方式，增加作業環境中空氣的相對濕度。\n3、使用抗靜電材料：使用本身具有抗靜電能力之物質、在絕緣材料的表面塗佈抗靜電物質或在絕緣材料製程中加入導電或抗靜電物質。\n4、使用靜電消除器：利用高壓電將空氣電離產生帶電離子，將帶靜電物體的電荷中和。\n5、限制速度：多應用於易燃性液體輸送作業，可減少液體穿過液面時的磨擦，以及引起液體擾動，避免因過多磨擦產生大量的靜電。"},
{"id": "sk-cc-68-08", "topic": "第 68 次（102.3.24）", "code": "68-08", "n": 68, "q": "防止有害物質危害之方法，可從A.發生源、B.傳播途徑、及C.暴露者等三處著手，請問下列各方法分屬上述何者？請依序回答。(本題各小項均為單選，答題方式如：\n(一)A、\n(二)B……) (10分)\n(一) 設置整體換氣裝置。\n(二) 設置局部排氣裝置。\n(三) 製程之密閉。\n(四) 實施勞工安全衛生教育訓練。\n(五) 擴大發生源與接受者之距離。\n(六) 以低毒性、低危害性物料取代。\n(七) 實施輪班制度，減少暴露時間。\n(八) 製程之隔離。\n(九) 使用正確有效之個人防護具。\n(十) 變更製程方法、作業程序。", "ans": "", "sol": "(一)B、\n(二)A、\n(三)A、\n(四)C、\n(五)B、\n(六)A、\n(七)C、\n(八)A、\n(九)C、\n(十)A", "old": 1},
{"id": "sk-cc-68-09", "topic": "第 68 次（102.3.24）", "code": "68-09", "n": 68, "q": "生物性危害可概分成A.感染、B.過敏、及C.中毒等三大類。請問下列各危害分屬上述何者？請依序回答。(本題各小項均為單選，答題方式如：\n(一)A、\n(二)B……)(10分)\n(一) 花粉熱。\n(二) 退伍軍人病。\n(三) SARS。\n(四) 細菌內毒素。\n(五) 黴菌毒素。\n(六) 愛滋病(AIDS)。\n(七) 禽流感。\n(八) 針扎。\n(九) 鉤蟲症。\n(十) 室塵蟎。", "ans": "", "sol": "(一)B、\n(二)A、\n(三)A、\n(四)C、\n(五)A、\n(六)A、\n(七)A、\n(八)A、\n(九)A、\n(十)B"},
{"id": "sk-cc-68-10", "topic": "第 68 次（102.3.24）", "code": "68-10", "n": 68, "q": "使用可燃性氣體測定器測定時，如指針指在 30％LEL 位置，而該可燃性氣體之爆炸下限(LEL)如為 1％ 時，則此氣體在環境中之濃度約為多少％？\n(10分；應列出計算式)", "ans": "", "sol": "氣體濃度＝爆炸下限濃度×測定器讀值氣體濃度\n＝1％ × 30％\n＝0.3％經計算後得知此氣體在環境中之濃度約為 0.3％。"},
{"id": "sk-cc-69-01", "topic": "第 69 次（102.7.21）", "code": "69-01", "n": 69, "q": "試依勞工安全衛生法令解釋下列名詞：(10分)\n(一) 車輛機械。(2分)\n(二) 總合傷害指數。(2分)\n(三) 特別危害健康之作業。(3分)\n(四) 職業災害定義中所稱「職業上原因」。(3分)", "ans": "", "sol": "(一) 車輛機械：係指能以動力驅動且自行活動於非特定場所之車輛、車輛系營建機械、堆高機等。(勞工安全衛生設施規則第6條)\n(二) 總合傷害指數＝【(失能傷害頻率×失能傷害嚴重率)÷1000】^{1/2}\n(三) 特別危害健康之作業：係指勞工所從事之作業對健康特別會造成危害的如：高溫作業、噪音作業、有機溶劑作業等。(勞工安全衛生法施行細則第 17 條)\n(四) 職業上原因：係指隨作業活動所衍生，於就業上一切必要行為及其附隨行為而具有相當因果關係者。(勞工安全衛生法施行細則第4條)", "old": 1},
{"id": "sk-cc-69-02", "topic": "第 69 次（102.7.21）", "code": "69-02", "n": 69, "q": "某工廠設有多部固定式起重機，依勞工安全衛生組織管理及自動檢查辦法規定，雇主對該固定式起重機每月定期實施檢查，請問其應檢查那些裝置及設備有無損害或異常？(10 分)", "ans": "", "sol": "(依勞工安全衛生組織管理及自動檢查辦法第 19 條規定)\n1、過捲預防裝置、警報裝置、制動器、離合器及其他安全裝置有無異常。\n2、鋼索及吊鏈有無損傷。\n3、吊鉤、抓斗等吊具有無損傷。\n4、配線、集電裝置、配電盤、開關及控制裝置有無異常。\n5、對於纜索固定式起重機之鋼纜等及絞車裝置有無異常。", "old": 1},
{"id": "sk-cc-69-03", "topic": "第 69 次（102.7.21）", "code": "69-03", "n": 69, "q": "(一) 依勞工安全衛生教育訓練規則對在職教育訓練規定，請說明勞工健康服務護理人員及急救人員各應接受之訓練頻率及時數？(4分)\n(二) 雇主辦理急救人員在職教育訓練，應於幾日前(2分)檢附那些文件(4分)，報請當地主管機關備查？(8分)", "ans": "", "sol": "(一) (依勞工安全衛生教育訓練規則第 17 條規定)\n1、勞工健康服務護理人員在職教育訓練：每 2 年至少 6 小時\n2、急救人員在職教育訓練：每 3 年至少 3 小時\n(二) (依勞工安全衛生教育訓練規則第 22 條規定)雇主辦理急救人員在職教育訓練，應於 15 日前檢附下列文件，報請當地主管機關備查：\n1、教育訓練計畫報備書。\n2、教育訓練課程表。\n3、講師概況。\n4、學員名冊。", "old": 1},
{"id": "sk-cc-69-04", "topic": "第 69 次（102.7.21）", "code": "69-04", "n": 69, "q": "適當的執行風險評估，可協助廠場建置完整妥適的勞工安全衛生管理計畫或職業安全衛生管理系統，有效預防或減少災害發生。試依中央主管機關公告之相關技術指引，說明風險評估之作業流程。(10分)", "ans": "", "sol": "（一）【依勞委會中部辦公室網站刊登風險評估技術指引第 4 條規定】\n1.辨識出所有的作業或工程。\n2.辨識危害及後果。\n3.確認現有防護設施。\n4.評估危害的風險。\n5.決定降低風險的控制措施。\n6.確認採取控制措施後的殘餘風險。", "old": 1},
{"id": "sk-cc-69-05", "topic": "第 69 次（102.7.21）", "code": "69-05", "n": 69, "q": "依營造安全衛生設施標準規定訂定墜落災害防止計畫時，應採取下列災害防止措施，請列出其優先順序？(請以英文代號答題，10分)\nA.經由施工程序之變更，優先施作永久構造物之上下昇降設備或防墜設施。\nB.使勞工佩掛安全帶。\nC.經由設計或工法之選擇，儘量使勞工於地面完成作業以減少高處作業項目。\nD.設置警示線系統、限制作業人員進入管制區。\nE.設置護欄、護蓋、安全網。", "ans": "", "sol": "(依營造安全衛生設施標準第 17 條規定)C ＞A ＞E ＞B ＞D"},
{"id": "sk-cc-69-06", "topic": "第 69 次（102.7.21）", "code": "69-06", "n": 69, "q": "依機械器具安全防護標準規定，動力衝剪機械應具有安全護圍或安全裝置，其中安全裝置包括那5種型式？ (10分)", "ans": "", "sol": "(依機械器具安全防護標準第 12 條規定)\n1、防護式安全裝置\n2、雙手操作式安全裝置\n3、光電感應式安全裝置\n4、拉開式安全裝置\n5、掃除式安全裝置"},
{"id": "sk-cc-69-07", "topic": "第 69 次（102.7.21）", "code": "69-07", "n": 69, "q": "火災爆炸危險區域劃分使用之電氣機械、器具或設備，應具有防爆性能構造，請列舉5種電氣設備防爆構造。(10分)", "ans": "", "sol": "(依中華民國工業安全衛生協會勞工安全衛生管理員教材『電氣安全』出題)\n1.耐壓型防爆構造。\n2.正壓型防爆構造。\n3.油入型防爆構造。\n4.增加安全型防爆構造。\n5.特殊型防爆構造。\n6.本質安全型防爆構造。\n7.填粉型防爆構造。\n8.模鑄型防爆構造。（以上任選5項作答）", "old": 1},
{"id": "sk-cc-69-08", "topic": "第 69 次（102.7.21）", "code": "69-08", "n": 69, "q": "依危險物與有害物標示及通識規則規定，請問下列危害物質應標示之危害圖式為何？請以下列各危害圖式之英文代號答題，不用畫圖。(10分)\n(一)易燃氣膠。\n(二)嚴重損傷/刺激眼睛物質第1級。\n(三)自熱物質。\n(四)有機過氧化物A型。\n(五)致癌物質。", "ans": "", "sol": "(依危險物與有害物標示及通識規則附表二)\n(一)易燃氣膠：G\n(二)嚴重損傷/刺激眼睛物質第1級：A\n(三)自熱物質：G\n(四)有機過氧化物A型：H\n(五)致癌物質：D", "fig": "圖式代號：A＝腐蝕（液體由試管滴到手及金屬）；B＝骷髏與交叉骨；C＝驚嘆號；D＝胸口有星狀標記之人形；E＝氣體鋼瓶；F＝圓圈上方火焰；G＝火焰；H＝爆炸。\n說明：以上各圖式之外框皆為紅色。"},
{"id": "sk-cc-69-09", "topic": "第 69 次（102.7.21）", "code": "69-09", "n": 69, "q": "依職業促發腦血管及心臟疾病（外傷導致者除外）之認定參考指引，請列舉5種促發此類疾病之工作負荷型態。(10分)", "ans": "", "sol": "(依中華民國工業安全衛生協會勞工安全衛生管理員教材『職場健康促進』出題)\n1.不規則的工作。\n2.工作時間長的工作。\n3.經常出差的工作。\n4.輪班工作或夜班工作。\n5.工作環境(異常溫度環境、噪音、時差)。\n6.伴隨精神緊張的工作。（以上任選 5 項作答）", "old": 1},
{"id": "sk-cc-69-10", "topic": "第 69 次（102.7.21）", "code": "69-10", "n": 69, "q": "距離一雷達天線1公尺所測得之電磁波通量密度(flux density)為90 mW/cm²。\n在距離雷達天線為3公尺時之電磁波通量密度應為多少mW/cm²？(10分；應列出計算過程)", "ans": "", "sol": "電磁波通量密度係指每平方公分面積上所接受的 mW 能量通常以 E 表示。\n由於電磁波為非游離輻射危害，而游離輻射或非游離危害能量大小係與距離平方成反比，因此在距離雷達天線為 3 公尺時之電磁波通量密度應為：\nE＝90 mW/cm² × 1/r²\n＝90 mW/cm² × 1/3²\n＝90 mW/cm² × 1/9\n＝10 mW/cm²"},
{"id": "sk-cc-70-01", "topic": "第 70 次（102.11.10）", "code": "70-01", "n": 70, "q": "請依勞工安全衛生法規回答下列問題：\n(一)為使勞工周知勞工安全衛生法規相關規定時，雇主得以何種方式宣導？\n(請列舉4種，4分)\n(二)雇主實施作業環境測定時，應僱用或委由何者辦理？(6分)", "ans": "", "sol": "(一)雇主得以教育、公告、分發印刷品、集會報告、電子郵件、網際網路或其他足使勞工周知之方式為之。(勞工安全衛生法施行細則第 26 條)\n(二)雇主實施作業環境測定時，應由下列人員或機構辦理：(勞工作業環境測定實施辦法第 8 條)\n1.僱用乙級以上之作業環境測定人員。\n2.委由執業之工礦衛生技師。\n3.委由經中央主管機關認可之作業環境測定機構。", "old": 1},
{"id": "sk-cc-70-02", "topic": "第 70 次（102.11.10）", "code": "70-02", "n": 70, "q": "請依勞工健康保護規則規定，回答下列問題:\n(一)事業單位應如何置急救人員？(6分)\n(二)前項急救人員不得有那些健康缺失項目，以免妨礙急救事宜。(請至少列出4項，4分)", "ans": "", "sol": "(依勞工健康保護規則第6條規定)\n(一)事業單位應參照工作場所大小、分布、危險狀況及勞工人數，置合格急救人員辦理急救事宜。每一輪班次應至少置一人、勞工人數超過五十人者，每增加五十人，應再置一人。\n(二)急救人員不得有失能、耳聾、色盲、心臟病、兩眼裸視或矯正視力後均在零點六以下等體能及健康不良，足以妨礙急救事宜者。"},
{"id": "sk-cc-70-03", "topic": "第 70 次（102.11.10）", "code": "70-03", "n": 70, "q": "一般道路常見到露天開挖工程，對於開挖場所有地面崩塌或土石飛落之虞時，請依營造安全衛生設施標準規定，回答下列問題:\n(一)如垂直開挖深度達1.5公尺以上，雇主除應指定何人於現場指揮勞工作業？(2分)。\n(二)雇主應依地質及環境狀況採取何種設施，以防止崩塌、倒塌或土石飛落？(至少列舉4種，8分)", "ans": "", "sol": "(一)應指定露天開挖作業主管於現場指揮勞工作業。(依營造安全衛生設施標準第 66 條規定)\n(二)設置適當擋土支撐、反循環樁、連續壁、邊坡保護等方法或張設防護網等設施，以防止崩塌、倒塌或土石飛落。 (任選4項作答。依營造安全衛生設施標準第77條規定)"},
{"id": "sk-cc-70-04", "topic": "第 70 次（102.11.10）", "code": "70-04", "n": 70, "q": "請依我國職業安全衛生管理系統(T0SHMS)指引，回答下列問題：\n(一)事業單位所建立的職業安全衛生管理系統，應包括那5要素？(5分)\n(二)所稱「與工作有關的傷病和不健康(ill health)」之定義為何？(5分)", "ans": "", "sol": "(一)事業單位所建立的職業安全衛生管理系統，應包括政策、組織設計、規劃與實施、評估和改善措施五個主要要素。\n(二)「與工作有關的傷病和不健康(ill health)」之定義為作業時因暴露於化學性、生物性、物理性或人體工學的環境下，或因作業組織和心理等因素的作用而對健康產生的負面影響。"},
{"id": "sk-cc-70-05", "topic": "第 70 次（102.11.10）", "code": "70-05", "n": 70, "q": "依勞工安全衛生設施規則規定，所稱可燃性氣體係指那些物質？(請至少列出5項，10分)", "ans": "", "sol": "可燃性氣體係指氫、乙炔、乙烯、甲烷、乙烷、丙烷、丁烷及其他於一大氣壓下攝氏十五度時，具有可燃性之氣體。\n(任選5項作答。勞工安全衛生設施規則第15條)", "old": 1},
{"id": "sk-cc-70-06", "topic": "第 70 次（102.11.10）", "code": "70-06", "n": 70, "q": "請依勞工安全衛生設施規則規定，回答下列問題:\n(一)高差超過幾公尺以上之場所作業時，雇主應設置安全上下之設備？(2分)\n(二)若使用移動梯當成勞工之上下設備時，移動梯應符合那些安全規定？(8分)", "ans": "", "sol": "(一)雇主對勞工於高差超過一．五公尺以上之場所作業時，應設置能使勞工安全上下之設備。(勞工安全衛生設施規則第 228 條)\n(二)雇主對於使用之移動梯，應符合下列之規定：(勞工安全衛生設施規則第 229 條)\n1.具有堅固之構造。\n2.其材質不得有顯著之損傷、腐蝕等現象。\n3.寬度應在三十公分以上。\n4.應採取防止滑溜或其他防止轉動之必要措施。", "old": 1},
{"id": "sk-cc-70-07", "topic": "第 70 次（102.11.10）", "code": "70-07", "n": 70, "q": "(一)小陳要使用研磨機研磨車刀時，依勞工安全衛生設施規則規定，對研磨機之使用，雇主應遵守那些安全規定？(8 分)\n(二)前項作業後，小陳要清除研磨機上之鐵屑，除停機外，為防止其他人誤起動，雇主應採取何種措施？(2 分)", "ans": "", "sol": "(一)雇主對於研磨機之使用，應依下列規定：(勞工安全衛生設施規則第 62 條)\n1、研磨輪應採用經速率試驗合格且有明確記載最高使用周速度者。\n2、規定研磨機之使用不得超過規定最高使用周速度。\n3、規定研磨輪使用，除該研磨輪為側用外，不得使用側面。\n4、規定研磨輪使用，應於每日作業開始前試轉一分鐘以上，研磨輪更換時應先檢驗有無裂痕，並在防護罩下試轉三分鐘以上。\n(二) 除停機外，為防止其他人誤起動，雇主應採取上鎖或設置標示等措施，並設置防止落下物導致危害勞工之安全設備與措施。(勞工安全衛生設施規則第 57 條)", "old": 1},
{"id": "sk-cc-70-08", "topic": "第 70 次（102.11.10）", "code": "70-08", "n": 70, "q": "(一)依粉塵危害預防標準規定，雇主設置之局部排氣裝置，有關氣罩、導管、排氣機及排氣口之規定，分別為何？(8 分)\n(二)前項 4 種裝置中，那一種有例外排除之規定？(2 分)", "ans": "", "sol": "(一)局部排氣裝置，應依下列之規定：(粉塵危害預防標準第15條)\n(1)氣罩宜設置於每一粉塵發生源，如採外裝型氣罩者﹐應儘量接近發生源。\n(2)導管長度宜儘量縮短，肘管數應儘量減少，並於適當位置開啟易於清掃及測定之清潔口及測定孔。\n(3)局部排氣裝置之排氣機，應置於空氣清淨裝置後之位置。\n(4)排氣口應設於室外。\n(二)前項4種裝置中，有設置過濾除塵方式或靜電除塵方式者，不在此限。"},
{"id": "sk-cc-70-09", "topic": "第 70 次（102.11.10）", "code": "70-09", "n": 70, "q": "針對化學性因子危害之預防，可從發生源、傳播路徑及暴露者採取對策，試列出 5 項有關傳播路徑方面之對策。(10 分)", "ans": "", "sol": "1.廠場整潔，立即清理，避免二次發生源之發生。\n2.整體換氣裝置之設置，稀釋有害物濃度。\n3.供給必要之新鮮空氣稀釋換氣。\n4.擴大發生源與接受者之距離如自動化、遙控，減少不必要之人員曝露。\n5.自動偵測監視裝置之設置以提出警訊，減少人員曝露。\n6.作業場所之整理整頓，減少作業振動再發散。\n(參閱中華民國工業安全衛生協會勞工安全衛生管理員教材p.946)", "old": 1},
{"id": "sk-cc-70-10", "topic": "第 70 次（102.11.10）", "code": "70-10", "n": 70, "q": "某有機溶劑作業場所每小時四氯化碳消費量為5公斤，依有機溶劑中毒預防規則規定，試問：\n(一)四氯化碳是屬何種有機溶劑？(2 分)\n(二)其需要之換氣能力，應為每分鐘多少立方公尺換氣量？(8 分；應列出計算式)", "ans": "", "sol": "(一)四氯化碳是屬第一種有機溶劑。(有機溶劑中毒預防規則附表一)\n(二)第一種有機溶劑每分鐘換氣量＝作業時間內一小時之有機溶劑或其混存物之物之消費量 × 0.3 (有機溶劑中毒預防規則附表四)(註：每分鐘換氣量之單位為立方公尺，作業時間內一小時之有機溶劑或其混存物之消費量之單位為公克。)\n因本有機溶劑作業場所每小時四氯化碳消費量為 5 公斤＝5,000 公克\n所以換氣量 Q＝5,000 × 0.3 ＝1,500 立方公尺/每分鐘"},
{"id": "sk-cc-71-01", "topic": "第 71 次（103.3.23）", "code": "71-01", "n": 71, "q": "雇主依勞工安全衛生教育訓練規則規定，對新僱勞工或在職勞工於變更工作前，應使其至少接受 3 小時的必要安全衛生教育訓練，試問：\n(一)對於從事那些作業時，應再各增列3小時訓練課程？(至少列出4項，8分)\n(二)對於各級業務主管人員於新僱或在職於變更工作前，應增列幾小時課程？(2分)", "ans": "", "sol": "(一) 從事使用生產性機械或設備、車輛系營建機械、高空工作車、捲揚機等之操作及營造作業、缺氧作業、電焊作業等，以及對製造、處置或使用危險物、有害物者均應增列三小時。(依勞工安全衛生教育訓練規則附表十四共有 8 項，任選 4 項作答)\n(二)應增列六小時課程。", "old": 1},
{"id": "sk-cc-71-02", "topic": "第 71 次（103.3.23）", "code": "71-02", "n": 71, "q": "某一工程公司欲使用中型移動式起重機吊升人員從事電線拆除作業，試依起重升降機具安全規則規定，回答下列問題：\n(一)何謂中型移動式起重機？(2 分)\n(二)對於移動式起重機之使用，應以吊物為限，不得乘載或吊升勞工從事作業。但在垂直高度 20 公尺以上之高處，從事性質特殊的作業及採取相關防護措施情形下，允許得乘載或吊升勞工從事作業，請問該但書規定為何？(8 分)", "ans": "", "sol": "(一)吊升荷重在 0.5 公噸以上未滿 3 公噸之移動式起重機。(依起重升降機具安全規則第 3 條規定)\n(二)從事貨櫃裝卸、船舶維修、高煙囪施工等尚無其他安全作業替代方法，或臨時性、小規模、短時間、作業性質特殊，經採取防止墜落等措施者。\n(依起重升降機具安全規則第 35 條規定)"},
{"id": "sk-cc-71-03", "topic": "第 71 次（103.3.23）", "code": "71-03", "n": 71, "q": "請依勞工安全衛生組織管理及自動檢查辦法規定，回答下列問題：\n(一)自動檢查分為那幾大類？(4 分)\n(二)何類自動檢查無需訂定自動檢查計畫？(2 分)\n(三)事業單位承租機械、設備或器具供勞工使用，如未以書面約定自動檢查之責任時，應由租用者或出租者負責實施之？(2 分)\n(四)勞工人數在 30 人以上時，事業單位應填具何種文件陳報檢查機構備查？(2 分)", "ans": "", "sol": "(一)機械之定期檢查、設備之定期檢查，機械、設備之重點檢查，機械、設備之作業檢點，作業檢點等五大類。(依勞工安全衛生組織管理及自動檢查辦法第四章第一節至第五節)\n(二)「作業檢點」無需訂定自動檢查計畫。(依勞工安全衛生組織管理及自動檢查辦法第 79 條未列入者)\n(三)應由租用者(事業單位)對該機械、設備或器具實施自動檢查。(依勞工安全衛生組織管理及自動檢查辦法第 85 條規定)\n(四)勞工人數在三十人以上之事業單位，依相關規定設管理單位或置管理人員時，應填具勞工安全衛生管理單位（人員）設置（變更）報備書陳報檢查機構備查。(依勞工安全衛生組織管理及自動檢查辦法第 86條規定)", "old": 1},
{"id": "sk-cc-71-04", "topic": "第 71 次（103.3.23）", "code": "71-04", "n": 71, "q": "在製作安全作業標準之前，一般先進行工作安全分析(JSA)，請問：\n(一)工作安全分析之目的為何？(2 分)\n(二)進行工作安全分析之 4 項主要程序為何？(8 分)", "ans": "", "sol": "(一) 工作安全分析可以說是「工作分析」與「預知危險」的結合。工作分析是讓主管人員清楚每件工作的詳細步驟、方法內容、規範。而預知危險是將每件工作中所存在的潛在危險與可能危害，事先加以預知，再經溝通討論而決定最佳的行動目標、或工作方法以確保安全工作。\n(二) 1.決定要分析的工作\n2.將工作步驟分解\n3.辨識出潛在的危害\n4.決定安全的工作方法"},
{"id": "sk-cc-71-05", "topic": "第 71 次（103.3.23）", "code": "71-05", "n": 71, "q": "營造工地有一高度3公尺之開口，工地主任為防止勞工發生墜落災害，欲於該處設置護蓋，依營造安全衛生設施標準規定，其設置之護蓋應如何辦理？\n(請列舉5項，10分)", "ans": "", "sol": "1、應具有能使人員及車輛安全通過之強度。\n2、應以有效方法防止滑溜、掉落、掀出或移動。\n3、供車輛通行者，得以車輛後軸載重之二倍設計之，並不得妨礙車輛之正常通行。\n4、為柵狀構造者，柵條間隔不得大於三公分。\n5、上面不得放置機動設備或超過其設計強度之重物。\n6、臨時性開口處使用之護蓋，表面漆以黃色並書以警告訊息。\n(依營造安全衛生設施標準第 21 條規定，以上任選 5 項作答)"},
{"id": "sk-cc-71-06", "topic": "第 71 次（103.3.23）", "code": "71-06", "n": 71, "q": "請依危險性機械及設備安全檢查規則規定，回答下列問題：\n(一)於吊籠檢查合格證有效期限屆滿前多久，應填具吊籠定期檢查申請書，向檢查機構申請定期檢查？(2 分)\n(二)於變更吊籠那些裝置或構造時，需填具吊籠變更檢查申請書及變更之圖件，向檢查機構申請變更檢查？(請列舉 4 項，8 分)", "ans": "", "sol": "(一)於吊籠檢查合格證有效期限屆滿前一個月提出申請。\n(依危險性機械及設備安全檢查規則第 67 條規定)\n(二)\n1、工作台。\n2、吊臂及其他構造部分。\n3、升降裝置。\n4、制動裝置。\n5、控制裝置。\n6、鋼索或吊鏈。\n7、固定方式。\n(依危險性機械及設備安全檢查規則第 69 條規定，任選 4 項作)"},
{"id": "sk-cc-71-07", "topic": "第 71 次（103.3.23）", "code": "71-07", "n": 71, "q": "依勞工健康保護規則規定，雇主僱用勞工時，應就那些規定項目實施一般體格檢查？(請列舉 10 項，10 分)", "ans": "", "sol": "1.作業經歷、既往病史、生活習慣及自覺症狀之調查。\n2.身高、體重、腰圍。\n3.視力、辨色力。\n4.聽力。\n5.血壓。\n6.身體各系統或部位之理學檢查。\n7.胸部Ｘ光（大片）攝影檢查。\n8.尿液檢查：尿蛋白及尿潛血之檢查。\n9.血液檢查：血色素及白血球數檢查。\n10.生化血液檢查：血糖、血清丙胺酸轉胺酶（ALT）、肌酸酐（creatinine）、膽固醇、三酸甘油酯之檢查。(勞工健康保護規則第 11 條)"},
{"id": "sk-cc-71-08", "topic": "第 71 次（103.3.23）", "code": "71-08", "n": 71, "q": "假如你是某事業單位之勞工安全衛生管理人員，工廠發生勞工死亡職業災害，廠長指派你調查災害原因，並就災害原因加以分析提出報告。請以一流程圖表示災害之調查，原因分析及改善之步驟。(10 分)", "ans": "", "sol": "", "fig": "流程：\n調查階段：1R 掌握災害狀況 → 確認事實〔人（相關人）、物（設備環境）、管理、經過現象〕 → 分析階段。\n分析階段：2R 發現問題點 → 災害要因 → 3R 決定根本問題 → 災害原因。\n災害要因 → 改善規劃：4R 樹立對策 → 類似災害防止方針。\n3R 決定根本問題 → 改善規劃：同種災害防止方針。\n改善規劃：PDCA。", "old": 1},
{"id": "sk-cc-71-09", "topic": "第 71 次（103.3.23）", "code": "71-09", "n": 71, "q": "下列勞工作業環境空氣中有害物，請由 A.活性碳吸附管、B.矽膠吸附管、\nC.吸收液、D.混合纖維素酯濾紙、E.聚氯乙烯濾紙等 5 項中，選定最適當採樣介質：(本題各項均為單選，答題方式如：\n(一)A、\n(二)B….)。(10 分)\n(一)正己烷。\n(二)重金屬粉塵。\n(三)可呼吸性粉塵。\n(四)硫化氫。\n(五)苯胺。", "ans": "", "sol": "(一) A、\n(二) D、\n(三) E、\n(四) C、\n(五) B。"},
{"id": "sk-cc-71-10", "topic": "第 71 次（103.3.23）", "code": "71-10", "n": 71, "q": "某一工作環境中測得乾球溫度 31℃，濕球溫度 28℃，黑球溫度 35℃，為室內無日曬環境，請問該環境之綜合溫度熱指數為多少℃？(請列出計算公式，10 分)", "ans": "", "sol": "室內無日曬時，綜合溫度熱指數(WBGT)＝0.7×Tnwb（濕球溫度）＋0.3×Tgb（黑球溫度）\n＝0.7×28℃＋0.3×35℃＝30.1℃"},
{"id": "sk-cc-72-01", "topic": "第 72 次（103.7.20）", "code": "72-01", "n": 72, "q": "請依職業安全衛生法令規定，回答下列問題：\n(一)工作者包括那 3 種身分之人員？(6 分)\n(二)何謂共同作業？(2 分)\n(三)職業安全衛生管理單位之職責為何？(2 分)", "ans": "", "sol": "(一) 工作者包括勞工、自營作業者及其他受工作場所負責人指揮或監督從事勞動之人員。(職安法 2 條)\n(二) 共同作業係指事業單位與承攬人、再承攬人所僱用之勞工於同一期間、同一工作場所從事工作。(職安法細則 37 條)\n(三) 職業安全衛生管理單位之職責為擬訂、規劃、督導及推動安全衛生管理事項，並指導有關部門實施。(職業安全衛生管理辦法 5 條之 1)"},
{"id": "sk-cc-72-02", "topic": "第 72 次（103.7.20）", "code": "72-02", "n": 72, "q": "勞工於局限空間從事作業，必須採取進入許可之管制措施，以避免發生職業災害，試依職業安全衛生設施規則規定，說明該進入許可應載明之事項。\n(至少回答 5 項，10 分)", "ans": "", "sol": "一、作業場所。\n二、作業種類。\n三、作業時間及期限。\n四、作業場所氧氣、危害物質濃度測定結果及測定人員簽名。\n五、作業場所可能之危害。\n六、作業場所之能源隔離措施。\n七、作業人員與外部連繫之設備及方法。\n八、準備之防護設備、救援設備及使用方法。\n九、其他維護作業人員之安全措施。\n十、許可進入之人員及其簽名。\n十一、現場監視人員及其簽名。\n(依職業安全衛生設施規則 29 條之六，任選 5 項作答)"},
{"id": "sk-cc-72-03", "topic": "第 72 次（103.7.20）", "code": "72-03", "n": 72, "q": "請依職業安全衛生管理辦法規定，回答下列問題：\n(一)荷重在多少公噸以上之堆高機，其操作人員應經特殊安全衛生教育訓練？(2分)\n(二)高空工作車每月定期檢查之項目包括那些？(6 分)\n(三)從事高空工作車之勞工，除接受一般安全衛生教育訓練外，尚需額外接受多少小時訓練？(2 分)", "ans": "", "sol": "(一) 荷重在一公噸以上之堆高機操作人員。(職安訓練則 14 條第二款)\n(二) 高空工作車每月定期實施檢查一次之項目：(職安管理辦法15條之二)\n1.制動裝置、離合器及操作裝置有無異常。\n2.作業裝置及油壓裝置有無異常。\n3.安全裝置有無異常。\n(三) 應額外接受三小時訓練(職安訓練則附表十四)"},
{"id": "sk-cc-72-04", "topic": "第 72 次（103.7.20）", "code": "72-04", "n": 72, "q": "請依職業安全衛生管理辦法規定，回答下列問題：\n(一)有那些事業單位應參照中央主管機關所定指引，建立適合該事業單位之職業安全衛生管理系統？(9 分)\n(二)目前中央主管機關已發布之指引名稱為何？(1 分)", "ans": "", "sol": "(一) 1.第一類事業勞工人數在三百人以上者。\n2.有從事石油裂解之石化工業工作場所者。\n3.有從事製造、處置或使用危害性之化學品，數量達中央主管機關規定量以上之工作場所者。(職安管理辦法 12 條之二)\n(二) 臺灣職業安全衛生管理系統指引，簡稱TOSHMS。"},
{"id": "sk-cc-72-05", "topic": "第 72 次（103.7.20）", "code": "72-05", "n": 72, "q": "有關動力衝剪機械的安全防護，除安全護圍外，請列舉5種安全裝置。(10分)", "ans": "", "sol": "(依照機械器具安全防護標準第9~14條規定)\n一、連鎖防護式安全裝置\n二、雙手操作式安全裝置\n三、感應式安全裝置\n四、拉開式安全裝置\n五、掃除式安全裝置"},
{"id": "sk-cc-72-06", "topic": "第 72 次（103.7.20）", "code": "72-06", "n": 72, "q": "緊急應變組織可依事業單位實際人力及必要之緊急狀況編組，請問緊急應變組織除應變指揮中心外，一般包括那五個編組？(10 分)", "ans": "", "sol": "(緊急應變措施技術指引，附錄一：緊急應變措施技術指引補充說明)應變組織架構以功能來分一般可分為五大部份：\n1.指揮組：不論大小，每一事件之應變都應有此功能，應變指揮官是最先排定而且是最後才撤離的職位。\n2.操作組：指導與協調事件中所有戰術的操作，包括現場負責人的督導。\n3.計畫組：收集、評估、分析與使用有關事件發展與資源運用等資訊。\n4.後勤組：在事件中提供應變組織各組所需之設施、服務與材料。\n5.財務組：記錄所有事件的花費並評估該事件的直間接財務損失。"},
{"id": "sk-cc-72-07", "topic": "第 72 次（103.7.20）", "code": "72-07", "n": 72, "q": "請依營造安全衛生設施標準規定，回答下列問題：\n(一)構築及拆除那幾種施工架前，應事先就預期施工時之最大負荷，依結構力學原理妥為安全設計？(6 分)\n(二)對前項構築及拆除之施工架，應指派所僱之專任工程人員簽章確認何種計算書及何種圖說？(4 分)", "ans": "", "sol": "(營造安全衛生設施標準第 40 條)\n(一)對於懸吊式施工架、懸臂式施工架、高度五公尺以上施工架。\n(二)應由專任工程人員簽章確認強度計算書及施工圖說。"},
{"id": "sk-cc-72-08", "topic": "第 72 次（103.7.20）", "code": "72-08", "n": 72, "q": "雇主使勞工於夏季期間從事戶外作業，為防範高氣溫環境引起之熱疾病，應視天候狀況採取危害預防措施，請列舉 5 項預防措施。(10 分)", "ans": "", "sol": "（職業安全衛生設施規則 324 條之六，任選 5 項）\n一、降低作業場所之溫度。\n二、提供陰涼之休息場所。\n三、提供適當之飲料或食鹽水。\n四、調整作業時間。\n五、增加作業場所巡視之頻率。\n六、實施健康管理及適當安排工作。\n七、留意勞工作業前及作業中之健康狀況。\n八、實施勞工熱疾病預防相關教育宣導。\n九、建立緊急醫療、通報及應變處理機制。"},
{"id": "sk-cc-72-09", "topic": "第 72 次（103.7.20）", "code": "72-09", "n": 72, "q": "勞工安全衛生法修正為職業安全衛生法時，刪除－般女性勞工禁止從事危險性或有害性工作之規定。請簡述其緣由。(10 分)", "ans": "", "sol": "鑑於我國產業結構改變，服務業比重增加，女性勞工參與率接近百分之五十，原勞工安全衛生法之條文對一般女性勞工禁止從事危險性及有害性工作之規定，已制定多年，近代醫學科技未證實須特別保護，故有限制女性工作，產生就業歧視之虞，因此在此次修正為職業安全衛生法時刪除原條文對一般女性勞工禁止從事危險性及有害性工作之規定。\n(勞工安全衛生法修正條文對照表舊條文第 21 條說明)", "old": 1},
{"id": "sk-cc-72-10", "topic": "第 72 次（103.7.20）", "code": "72-10", "n": 72, "q": "某一室內勞動場所工作者之二氧化碳產生率為 11m³/hr，戶外二氧化碳濃度為 400ppm。如欲使此室內勞動場所二氧化碳濃度不超過 1,500 ppm，則戶外空氣之進氣量應至少為多少m³/hr？(10 分，應列出計算式)", "ans": "", "sol": "Q＝K/p－q\n因為K＝11 m³/hr、p＝1,500ppm、q＝400ppm\n所以 Q＝11 m³/hr/(1500ppm－400ppm)＝11 m³/hr/1100ppm＝10,000 m³/hr(參考中華民國工業安全衛生協會教材)"},
{"id": "sk-cc-73-01", "topic": "第 73 次（103.11.9）", "code": "73-01", "n": 73, "q": "某研究機構最近招募一批工讀生，部分年齡尚未達 18 歲，依職業安全衛生法規定，對於未滿 18 歲者，雇主不得使其從事的危險性或有害性工作包括那些?(至少列舉 5 項，10 分)", "ans": "", "sol": "雇主不得使未滿十八歲者從事下列危險性或有害性工作： (職業安全衛生法第 29 條，任選 5 項作答)\n1、坑內工作。\n2、處理爆炸性、易燃性等物質之工作。\n3、鉛、汞、鉻、砷、黃磷、氯氣、氰化氫、苯胺等有害物散布場所之工作。\n4、有害輻射散布場所之工作。\n5、有害粉塵散布場所之工作。\n6、運轉中機器或動力傳導裝置危險部分之掃除、上油、檢查、修理或上卸皮帶、繩索等工作。\n7、超過二百二十伏特電力線之銜接。\n8、已熔礦物或礦渣之處理。\n9、鍋爐之燒火及操作。\n10、鑿岩機及其他有顯著振動之工作。\n11、一定重量以上之重物處理工作。\n12、起重機人字臂起重桿之運轉工作。\n13、動力捲揚機、動力運搬機及索道之運轉工作。\n14、十四、橡膠化合物及合成樹脂之滾輾工作。"},
{"id": "sk-cc-73-02", "topic": "第 73 次（103.11.9）", "code": "73-02", "n": 73, "q": "依勞工作業環境監測實施辦法規定，雇主得自行僱用合格監測人員，以直讀式儀器監測之化學性因子包括那些?(至少列舉 4 項，10 分)", "ans": "", "sol": "依勞工作業環境監測實施辦法第 11 條規定：雇主實施作業環境監測時，應設置或委託監測機構辦理。但監測項目屬物理性因子或得以直讀式儀器有效監測之下列化學性因子者，得僱用乙級以上之監測人員或委由執業之工礦衛生技師辦理：（以下任選 4 項作答）\n1、二氧化碳。\n2、二硫化碳。\n3、二氯聯苯胺及其鹽類。\n4、次乙亞胺。\n5、二異氰酸甲苯。\n6、硫化氫。\n7、汞及其無機化合物。"},
{"id": "sk-cc-73-03", "topic": "第 73 次（103.11.9）", "code": "73-03", "n": 73, "q": "當雇主從事灌注、卸收危險物於槽車之作業時，請依職業安全衛生設施規則規定，回答下列問題:\n(一)使用軟管從事易燃液體或可燃性氣體之灌注或卸收時，應如何辦理?(2 分)\n(二)當灌注環氧乙烷或乙醛時，應以何種氣體置換?(2 分)\n(三)使用槽車從事灌注或卸收作業前後，對槽車之安全措施為何門 6 分)", "ans": "", "sol": "依職業安全衛生設施規則第 186 條規定：雇主對於從事灌注、卸收或儲藏危險物於化學設備、槽車或槽體等作業，應依下列規定辦理：\n(一)使用軟管從事易燃液體或可燃性氣體之灌注或卸收時，應事先確定軟管結合部分已確實連接牢固始得作業。作業結束後，應確認管線內已無引起危害之殘留物後，管線始得拆離。\n(二)從事環氧乙烷、乙醛或 1.2. 環氧丙烷灌注時，應確實將化學設備、槽車或槽體內之氣體，以氮、二氧化碳或氦、氬等惰性氣體置換之。\n(三)使用槽車從事灌注或卸收作業前，槽車之引擎應熄火，且設置適當之輪擋，以防止作業時車輛移動。作業結束後，並確認不致因引擎啟動而發生危害後，始得發動。"},
{"id": "sk-cc-73-04", "topic": "第 73 次（103.11.9）", "code": "73-04", "n": 73, "q": "某電子公司勞工人數達 3,400 人，已訂定職業安全衛生管理計畫，請依職業安全衛生管理辦法規定，回答下列問題:\n(一)該公司內部對職業安全衛生管理計畫具有協調及建議等權責之組織為何?(3 分)\n(二)上述組織之組成，除雇主外，尚包括那 5 種不同身分之成員?(5 分)\n(三)上述組織應每隔多久至少開會 1 次?(1 分)其紀錄應保存多久?(1 分)", "ans": "", "sol": "(一)職業安全衛生委員會(職業安全衛生管理辦法第 10 條)\n(二)(職業安全衛生管理辦法第 11 條)\n1、職業安全衛生人員。\n2、事業內各部門之主管、監督、指揮人員。\n3、與職業安全衛生有關之工程技術人員。\n4、從事勞工健康服務之醫護人員。\n5、勞工代表。\n(三)委員會應每三個月至少開會一次，其紀錄應保存三年。(職業安全衛生管理辦法第 12 條)"},
{"id": "sk-cc-73-05", "topic": "第 73 次（103.11.9）", "code": "73-05", "n": 73, "q": "某一橡膠製造廠，廠內有一3,000公斤之大型化學儲槽，適逢歲修需將化學品排空，並清洗儲槽。針對前述情境，為確保作業安全，應訂定局限空間危害防止計畫，使現場作業主管。監視人員、作業勞工及相關承攬人依循辦理。請說明前項危害防止計畫應包括那些事項？(至少列舉5項，10分)", "ans": "", "sol": "(依職業安全衛生設施規則第29-1條規定，以下任選5項作答)局限空間危害防止計畫，應依作業可能引起之危害訂定下列事項：\n1、局限空間內危害之確認。\n2、局限空間內氧氣、危險物、有害物濃度之測定。\n3、通風換氣實施方式。\n4、電能、高溫、低溫及危害物質之隔離措施及缺氧、中毒、感電、塌陷、被夾、被捲等危害防止措施。\n5、作業方法及安全管制作法。\n6、進入作業許可程序。\n7、提供之防護設備之檢點及維護方法。\n8、作業控制設施及作業安全檢點方法。\n9、緊急應變處置措施。"},
{"id": "sk-cc-73-06", "topic": "第 73 次（103.11.9）", "code": "73-06", "n": 73, "q": "依營造安全衛生設施標準規定，雇主使勞工於斜度平緩(少於 34 度)且易踏穿材料構築之屋頂作業時，應採取何種措施?(10 分)(註:但法條中所列「設置踏板面積已覆蓋全部易踏穿屋頂或採取其他安全工法」排除答案，不予計分)", "ans": "", "sol": "(營造安全衛生設施標準第18條)\n(一)於易踏穿材料構築之屋頂作業時，應先規劃安全通道，於屋架上設置適當強度，且寬度在三十公分以上之踏板，並於下方適當範圍裝設堅固格柵或安全網等防墜設施。\n(二)易踏穿材料構築屋頂作業時，雇主應指派屋頂作業主管於現場辦理下列事項：\n1、決定作業方法，指揮勞工作業。\n2、實施檢點，檢查材料、工具、器具等，並汰換不良品。\n3、監督勞工確實使用個人防護具。\n4、確認安全衛生設備及措施之有效狀況。\n5、其他為維持作業勞工安全衛生所必要之設備及措施。"},
{"id": "sk-cc-73-07", "topic": "第 73 次（103.11.9）", "code": "73-07", "n": 73, "q": "工廠之丙烯儲槽氣體大量洩漏(其氣體密度大於空氣)，洩漏範圍尚局限於廠內，請問如何處理，以避免引起火災爆炸而使災害擴大？(至少列舉 5 項，10 分)", "ans": "", "sol": "1、雇主或工作場所負責人要使勞工立即停止作業，並退避至安全處所。\n2、要隔離丙烯氣體洩漏區，管制無關人員進入該區。\n3、要關閉丙烯儲槽供氣管線，以阻止洩露，避免引起火災爆炸而使災害擴大。\n4、由高壓氣體作業主管指揮搶救人員穿戴適當的個人防護具，進行通風換氣、撲滅或移開火焰，因丙烯氣體密度大於空氣，禁止噴水以減少擴散。\n5、打 119 請求政府消防單位協助。"},
{"id": "sk-cc-73-08", "topic": "第 73 次（103.11.9）", "code": "73-08", "n": 73, "q": "經地方政府宣布停止上班之颱風期間，如果勞工從事外勤作業，有危害勞工之虞時，依職業安全衛生設施規則規定，雇主應視作業危害性，置備適器具、設備及工具。(10 分)", "ans": "", "sol": "（職業安全衛生設施規則第 286-2 條）\n1、器具：置備適當救生衣、安全帽。\n2、設備：連絡通訊設備及其他必要之安全防護設施。\n3、工具：交通工具。"},
{"id": "sk-cc-73-09", "topic": "第 73 次（103.11.9）", "code": "73-09", "n": 73, "q": "商店老闆為預防店員被顧客辱罵等行為造成身體或精神上之不法侵害，應依法採取那些暴力預防措施?(至少列舉 5 項，10 分)", "ans": "", "sol": "（職業安全衛生設施規則第 324-3 條或職安法施行細則第 11 條）雇主為預防勞工於執行職務，因他人行為致遭受身體或精神上不法侵害，應採取下列暴力預防措施：（以下任選 5 項作答）\n1、辨識及評估危害。\n2、適當配置作業場所。\n3、依工作適性適當調整人力。\n4、建構行為規範。\n5、辦理危害預防及溝通技巧訓練。\n6、建立事件之處理程序。\n7、執行成效之評估及改善。\n8、其他有關安全衛生事項。"},
{"id": "sk-cc-73-10", "topic": "第 73 次（103.11.9）", "code": "73-10", "n": 73, "q": "某一正常運轉之局部排氣系統，測得某一點之動壓為 16 mmH₂O，靜壓為－10 mm H₂O。請回答下列問題:\n(一)此監測數值有何錯誤?(5 分)\n(二)依動壓測值，該測點之流速為多少 m/s?(參考公式 V＝4.04√VP)(5 分)", "ans": "", "sol": "(一)此監測數值中，靜壓為－10 mm H₂O(負壓)故得知監測點在排氣機前，因全壓在排氣機前應為負壓，但本題全壓＝靜壓＋動壓＝(－10 mm H₂O)＋16 mmH₂O\n＝6 mmH₂O(正壓)故顯然此監測數值有錯誤。\n(二)依動壓測值，該測點之流速 V＝4.04√VP＝4.04×√16＝16.16 m/s(參考中華民國工業安全衛生協會教材)"},
{"id": "sk-cc-74-01", "topic": "第 74 次（104.3.22）", "code": "74-01", "n": 74, "q": "某電子業製造工廠女性勞工分挽後未滿 1 年，依職業安全衛生法規定，雇主不得使其從事的危險性或有害性工作包括那些?(10 分)", "ans": "", "sol": "雇主不得使分娩後未滿一年之女性勞工從事下列危險性或有害性工作： (職業安全衛生法第 30 條第 2 項)\n1、礦坑工作。\n2、鉛及其化合物散布場所之工作。\n3、鑿岩機及其他有顯著振動之工作。\n4、一定重量以上之重物處理工作。\n5、其他經中央主管機關規定之危險性或有害性之工作。"},
{"id": "sk-cc-74-02", "topic": "第 74 次（104.3.22）", "code": "74-02", "n": 74, "q": "事業單位如發生職業災害，請按雇主應依職業安全衛生法相關規定辦理之事項，回答下列問題:\n(一)勞動場所發生那些職業災害，雇主應於8小時內通報勞動檢查機構?(7分)\n(二)工作場所如發生職業災害，雇主應會同勞工代表實施調查，此代表如何產出?(3 分)", "ans": "", "sol": "(一)事業單位勞動場所發生下列職業災害之一者，雇主應於八小時內通報勞動檢查機構：(職業安全衛生法第 37 條第 2 項)\n1、發生死亡災害。\n2、發生災害之罹災人數在三人以上。\n3、發生災害之罹災人數在一人以上，且需住院治療。\n4、其他經中央主管機關指定公告之災害。\n(二) 勞工代表之產出：(職業安全衛生法施行細則第 43 條)事業單位設有工會者，由工會推派之；無工會組織而有勞資會議者，由勞方代表推選之；無工會組織且無勞資會議者，由勞工共同推選之。", "old": 1},
{"id": "sk-cc-74-03", "topic": "第 74 次（104.3.22）", "code": "74-03", "n": 74, "q": "請依職業安全衛生法相關規定，回答下列問題:\n(一)列舉 2 項具有危險性之設備。(4 分)\n(二)具有危險性之機械、設備，列舉 3 項應經勞動檢查機構或代行檢查機構檢查之檢查項目。(6 分)", "ans": "", "sol": "(一)所稱具有危險性之設備，指符合中央主管機關所定一定容量以上之下列設備：(職業安全衛生法施行細則第 23 條，任選 2 項作答)\n1、鍋爐。\n2、壓力容器。\n3、高壓氣體特定設備。\n4、高壓氣體容器。\n(二) 由中央主管機關依機械、設備之種類、特性，就下列檢查項目分別定之：\n(職業安全衛生法施行細則第 24 條，任選 3 項作答)\n1、熔接檢查。\n2、構造檢查。\n3、竣工檢查。\n4、定期檢查。\n5、重新檢查。\n6、型式檢查。\n7、使用檢查。\n8、變更檢查。", "old": 1},
{"id": "sk-cc-74-04", "topic": "第 74 次（104.3.22）", "code": "74-04", "n": 74, "q": "某電子工廠之勞工需從事輪班、夜間等工作，為避免異常工作負荷促發疾病，請依職業安全衛生法施行細則規定，回答下列問題:\n(一)請列舉 4 項應採取之疾病預防措施。(8 分)\n(二)預防措施之執行紀錄應至少留存多少年?(2 分)", "ans": "", "sol": "(一) 雇主使勞工從事輪班、夜間工作、長時間工作等作業，為避免勞工因異常工作負荷促發疾病，應採取下列疾病預防措施：（職業安全衛生設施規則第324-2 條，以下任選 4 項作答）\n1、辨識及評估高風險群。\n2、安排醫師面談及健康指導。\n3、調整或縮短工作時間及更換工作內容之措施。\n4、實施健康檢查、管理及促進。\n5、執行成效之評估及改善。\n(二) 預防措施之執行紀錄應至少留存多 3 年。"},
{"id": "sk-cc-74-05", "topic": "第 74 次（104.3.22）", "code": "74-05", "n": 74, "q": "某一造紙工廠之勞工每天重複執行搬運工作，雇主依職業安全衛生法施行細則規定，為避免該勞工執行重複性作業而促發肌肉骨骼疾病，應妥為規劃那些事項?(10分)", "ans": "", "sol": "雇主使勞工從事重複性之作業，為避免勞工因姿勢不良、過度施力及作業頻率過高等原因，促發肌肉骨骼疾病，應採取下列危害預防措施：（職業安全衛生設施規則第 324-1 條）\n1、分析作業流程、內容及動作。\n2、確認人因性危害因子。\n3、評估、選定改善方法及執行。\n4、執行成效之評估及改善。\n5、其他有關安全衛生事項。"},
{"id": "sk-cc-74-06", "topic": "第 74 次（104.3.22）", "code": "74-06", "n": 74, "q": "依高溫作業勞工作息時間標準規定，回答下列問題:\n(一)高溫作業為勞工工作日時量平均綜合溫度熱指數達該標準連績作業規定值以上之作業。請列舉 3 項該標準所定之高溫作業。(6 分)\n(二)請說明\n(一)之作業中，不適用之操作方式。(2 分)\n(三)請說明\n(二)情況不適用之原因。(2 分)", "ans": "", "sol": "(一)依高溫作業勞工作息時間標準規定，所定高溫作業，為勞工工作日時量平均綜合溫度熱指數達連續作業規定值以上之下列作業：（高溫作業勞工作息時間標準第 2 條，以下任選 3 項作答）\n1、於鍋爐房從事之作業。\n2、灼熱鋼鐵或其他金屬塊壓軋及鍛造之作業。\n3、於鑄造間處理熔融鋼鐵或其他金屬之作業。\n4、鋼鐵或其他金屬類物料加熱或熔煉之作業。\n5、處理搪瓷、玻璃、電石及熔爐高溫熔料之作業。\n6、於蒸汽火車、輪船機房從事之作業。\n7、從事蒸汽操作、燒窯等作業。\n(二)前項作業，不適用已採取自動化操作方式且勞工無暴露熱危害之虞者。\n(三)因勞工工作日時量平均綜合溫度熱指數未達連續作業規定值以上。"},
{"id": "sk-cc-74-07", "topic": "第 74 次（104.3.22）", "code": "74-07", "n": 74, "q": "有墜落之虞者，應訂定墜落災害防止計畫，依風險控制之先後順序規到，並採取適當墜落災害防止設施。請列舉 5 項風險控制項目。(10 分)", "ans": "", "sol": "雇主對於高度二公尺以上之工作場所，勞工作業有墜落之虞者，應訂定墜落災害防止計畫，依下列風險控制之先後順序規劃，並採取適當墜落災害防止設施：（營造安全衛生設施標準第 17 條，以下任選 5 項作答）\n1、經由設計或工法之選擇，儘量使勞工於地面完成作業，減少高處作業項目。\n2、經由施工程序之變更，優先施作永久構造物之上下設備或防墜設施。\n3、設置護欄、護蓋。\n4、張掛安全網。\n5、使勞工佩掛安全帶。\n6、設置警示線系統。\n7、限制作業人員進入管制區。"},
{"id": "sk-cc-74-08", "topic": "第 74 次（104.3.22）", "code": "74-08", "n": 74, "q": "依職業安全衛生設施規則規定，對於灌注危險物於儲槽之設備有因靜電引起爆炸或火災之虞者，應採取那些措施或裝置。(10 分)", "ans": "", "sol": "（職業安全衛生設施規則第 175 條）\n1.接地。\n2.使用除電劑。\n3.加濕。\n4.使用不致成為發火源之虞之除電裝置。\n5.其他去除靜電之裝置。\n1.接地及搭接：製程中因摩擦、感應或傳導等產生的靜電危害藉由接地及搭接將能量釋放。\n2.增加濕度：在高溼度環境中，可降低物質的表面電阻，增加電荷散逸速度，達成電荷蓄積程度降低。\n3.使用抗靜電材料：使用物質表面或體積電阻係數愈低的材料，即可避免物質蓄積過量的靜電，如棉、碳粉等。\n4.使用靜電消除器：利用高壓電將空氣電離產生帶電離子，可使帶靜電物體的電荷被中和達成蓄積電荷至最低。\n5.限制速度：對於易燃液體的輸送作業限制其流速以消除製程中潛在靜電的來源。"},
{"id": "sk-cc-74-09", "topic": "第 74 次（104.3.22）", "code": "74-09", "n": 74, "q": "有害物控制設備包括 A．包圍型氣罩、B．外裝型氣罩及 C．吹吸型換氣裝置。請問下列各圖示分屬上述何者?請依序回答。(本題各小項均為單選，答題方式如:\n(一)A\n(二)B．‥)。(10 分)", "ans": "", "sol": "(一)B、\n(二)B、\n(三)C、\n(四)B、\n(五)A", "fig": "圖(一)：槽體上方有工件，槽側設吸氣口，氣流由槽面進入側方導管後向上排出。\n圖(二)：箱形氣罩包圍作業設備，前下方留有作業開口，氣流經頂部導管向上排出。\n圖(三)：汽車位於大型作業間內，氣流由上方送入並向兩側下方流出。\n圖(四)：作業物上方設懸吊式錐形氣罩，氣流向上進入氣罩並由上方導管排出。\n圖(五)：密閉箱體前面設兩個手孔，箱內有作業物，上方有吸氣導管。"},
{"id": "sk-cc-74-10", "topic": "第 74 次（104.3.22）", "code": "74-10", "n": 74, "q": "某化學品製造業共有勞工 8,000 人，採日夜 3 班制作業，每年工作 300 夭，每人每天工作 8 小時，當年發生勞工 1 人死亡，3 人殘廢，8 人受傷。請回答下列問題:\n(一)失能傷害頻率為多少?(5 分)\n(二)死亡千人率為多少?(5 分)", "ans": "", "sol": "(一)總歷經工時＝8 × 300 × 8000＝19200000 小時\n失能傷害人次數＝1＋3＋8＝12\n失能傷害頻率(FR)＝(失能傷害人次數 × 1,000,000) / 總歷經工時\n＝(12×1,000,000) / 19200000＝0.62\n(二)死亡千人率＝(年間勞工死亡人數×1000) / 平均勞工人數＝2.1 × FR\n＝2.1 × 0.62\n＝1.3"},
{"id": "sk-cc-75-01", "topic": "第 75 次（104.7.19）", "code": "75-01", "n": 75, "q": "請依職業安全衛生法令規定，列舉 5 項中央主管機關指定應符合安全標準之機械、設備或器具。(10 分)", "ans": "", "sol": "中央主管機關指定應符合安全標準之機械、設備或器具：(職業安全衛生法施行細則第 7 條，任選 5 項作答)\n1、動力衝剪機械。\n2、手推刨床。\n3、木材加工用圓盤鋸。\n4、動力堆高機。\n5、研磨機。\n6、研磨輪。\n7、防爆電氣設備。\n8、動力衝剪機械之光電式安全裝置。\n9、手推刨床之刃部接觸預防裝置。\n10、木材加工用圓盤鋸之反撥預防裝置及鋸齒接觸預防裝置。"},
{"id": "sk-cc-75-02", "topic": "第 75 次（104.7.19）", "code": "75-02", "n": 75, "q": "某一危害風險為第一類事業之事業單位(非營造業)，請依職業安全衛生法相關規定，就其職業安全衛生管理單位及人員之設置，回答下列問題：\n(一)事業單位如將其事業交付承攬，且有其他非該事業單位僱用之工作者從事勞動，其工作場所勞工人數如何計算？(6 分)\n(二)勞工人數經計算如為 300 人，應設置何種層級之職業安全衛生管理單位及職業安全衛生業務主管？(4 分)", "ans": "", "sol": "(一)工作場所勞工人數之計算，包含原事業單位及其承攬人、再承攬人之勞工及其他受工作場所負責人指揮或監督從事勞動之人員，於同一期間、同一工作場所作業時之總人數。(職業安全衛生管理辦法第 3-2 條)\n(二)除已實施職業安全衛生管理系統相關管理制度，管理績效並經中央主管機關認可者外，應設直接隸屬雇主之專責一級管理單位及專職甲種職業安全衛生業務主管一人。(職業安全衛生管理辦法第 2-1,3 條)"},
{"id": "sk-cc-75-03", "topic": "第 75 次（104.7.19）", "code": "75-03", "n": 75, "q": "某塑膠製品業於歲修期間，雇主使勞工進入儲槽之內部從事有機溶劑作業，依有機溶劑中毒預防規則，應遵守那些規定？(請列舉 5 項，共 10 分)", "ans": "", "sol": "(有機溶劑中毒預防規則第 21 條，任選 5 項作答)\n1、派遣有機溶劑作業主管從事監督作業。\n2、決定作業方法及順序於事前告知從事作業之勞工。\n3、確實將有機溶劑或其混存物自儲槽排出，並應有防止連接於儲槽之配管流入有機溶劑或其混存物之措施。\n4、前款所採措施之閥、旋塞應予加鎖或設置盲板。\n5、作業開始前應全部開放儲槽之人孔及其他無虞流入有機溶劑或其混存物之開口部。\n6、以水、水蒸汽或化學藥品清洗儲槽之內壁，並將清洗後之水、水蒸氣或化學藥品排出儲槽。\n7、應送入或吸出三倍於儲槽容積之空氣，或以水灌滿儲槽後予以全部排出。\n8、應以測定方法確認儲槽之內部之有機溶劑濃度未超過容許濃度。\n9、應置備適當的救難設施。\n10、勞工如被有機溶劑或其混存物污染時，應即使其離開儲槽內部，並使該勞工清洗身體除卻污染。"},
{"id": "sk-cc-75-04", "topic": "第 75 次（104.7.19）", "code": "75-04", "n": 75, "q": "請依職業安全衛生管理辦法相關規定，回答下列問題：\n(一)應參照中央主管機關所定之職業安全衛生管理系統指引，建立職業安全衛生管理系統之事業單位有那 3 類？(6 分)\n(二)前述管理系統應包括「政策」等 5 項安全衛生事項，請列出其餘 4 項？\n(4 分)", "ans": "", "sol": "(職安設施規則第 12-2 條)\n(一)下列 3 類事業單位，應參照中央主管機關所定之職業安全衛生管理系統指引，建立適合該事業單位之職業安全衛生管理系統：\n1、第一類事業勞工人數在三百人以上者。\n2、有從事石油裂解之石化工業工作場所者。\n3、有從事製造、處置或使用危害性之化學品，數量達中央主管機關規定量以上之工作場所者。\n(二)管理系統除政策外應包括之其餘 4 項安全衛生事項為：\n1、組織設計。\n2、規劃與實施。\n3、評估。\n4、改善措施。"},
{"id": "sk-cc-75-05", "topic": "第 75 次（104.7.19）", "code": "75-05", "n": 75, "q": "某未實施輪班制事業單位之勞工人數共 1,055 人，依勞工健康保護規則規定，請回答下述問題：\n(一)應至少置多少位急救人員？(2 分)\n(二)急救人員不得有那些健康不良項目，以免妨礙急救事宜？(請列舉 4項，4 分)\n(三)需備置那些急救藥品及器材？(請列舉 4 項，4 分)", "ans": "", "sol": "(勞工健康保護規則 6 條)\n(一)勞工人數超過五十人者，每增加五十人，應再置一人；故勞工人數 1,055人應至少置 21 位急救人員？(勞工健康保護規則 6 條第四項)\n(二)急救人員不得有失聰、色盲、心臟病、兩眼裸視或矯正視力後均在零點六以下與失能等體能及健康不良項目，以免妨礙急救事宜。(勞工健康保護規則 6 條第二項)\n(三)需備置之急救藥品及器材如下：(附表六，任選各 2 項,共 4 項)\n1、藥品：優碘棉片或優碘液、酒精棉片或酒精液等必需藥品。\n2、器材：體溫測量器、血壓計、彈性紗繃或彈性繃帶（大、中、小）、三角巾、無菌手套、無齒鑷子、棉棒（大、中、小）、紗布、紙膠、止血帶、剪刀、安全別針、壓舌板、咬合器、外科口罩等必需器材。"},
{"id": "sk-cc-75-06", "topic": "第 75 次（104.7.19）", "code": "75-06", "n": 75, "q": "依起重升降機具安全規則規定，對於移動式起重機之使用，以吊物為限，不得乘載或吊升勞工從事作業，若在特殊條件下，得以搭乘設備乘載或吊升勞工時，該搭乘設備應符合那些規定？(請列舉 2 項，10 分)", "ans": "", "sol": "搭乘設備應符合下列規定：(起重升降機具安全規則第 36 條，任選 2 項作答)\n1、搭乘設備應有足夠強度，其使用之材料不得有影響構造強度之損傷、變形或腐蝕等瑕疵。\n2、搭乘設備周圍設置高度九十公分以上之扶手，並設中欄杆及腳趾板。\n3、搭乘設備之懸吊用鋼索或鋼線之安全係數應在十以上；吊鏈、吊帶及其支點之安全係數應在五以上。\n4、依搭乘設備之構造及材質，計算積載之最大荷重，並於搭乘設備之明顯易見處，標示自重及最大荷重。"},
{"id": "sk-cc-75-07", "topic": "第 75 次（104.7.19）", "code": "75-07", "n": 75, "q": "依營造安全衛生設施標準規定，對於鋼構吊運、組配作業時，於吊運鋼材、安放鋼構時、設置鋼構時及吊索鬆放前，有何規定？(請列舉 2 項，10 分)", "ans": "", "sol": "對於鋼構吊運、組配作業時，於吊運鋼材、安放鋼構時、設置鋼構時及吊索鬆放前，應依下列規定辦理：(營造安全衛生設施標準第 148 條，任選 2項作答)\n(1).吊運長度超過六公尺以上之構架時，應在適當距離之二端以拉索捆紮拉緊，保持平穩防止擺動，作業人員在其旋轉區內時，應以穩定索繫於構架尾端使之穩定。\n(2).吊運之鋼材，應於卸放前，檢視其確實捆妥或繫固於安定之位置，再卸離吊掛用具。\n(3).鋼樑於最後安裝吊索鬆放前，鋼樑二端腹鈑之接頭處，應有二個以上之螺栓裝妥或採其他設施固定之。\n(4).鋼構組配進行中，柱子尚未於二個以上之方向與其他構架組配牢固前，應使用格柵當場栓接，或採其他設施，以抵抗橫向力，維持構架之穩定。\n(5).使用十二公尺以上長跨度格柵樑或桁架時，於鬆放吊索前，應安裝臨時構件，以維持橫向之穩定。"},
{"id": "sk-cc-75-08", "topic": "第 75 次（104.7.19）", "code": "75-08", "n": 75, "q": "勞工懷疑自己罹患職業病，欲向雇主申請職業災害補償，試述勞雇雙方可循何程序處理。(10 分)", "ans": "", "sol": "", "fig": "流程：勞工疑似罹患職業病 → 醫師（職業疾病／非職業疾病） → 診斷結果勞雇任一方有無異議。\n1.無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償。\n2.無異議且不屬職業疾病 → 結案。\n3.有異議 → 直轄市、縣（市）政府認定；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案。\n4.直轄市、縣（市）政府認定困難，或勞雇任一方對認定有異議 → 行政院勞工委員會（職業疾病鑑定委員會）；勞工保險機構審定職業疾病認有必要時，亦送行政院勞工委員會。\n5.行政院勞工委員會 → 診斷結果勞雇任一方有無異議；無異議且屬職業疾病 → 向勞工保險局申請職業災害給付／由雇主依勞動基準法給予職業災害補償；無異議且不屬職業疾病 → 結案；有異議 → 法律訴訟。", "note": "本題有流程圖，內容已轉錄於 fig。"},
{"id": "sk-cc-75-09", "topic": "第 75 次（104.7.19）", "code": "75-09", "n": 75, "q": "針對化學性因子危害之預防，可從發生源、傳播路徑及暴露者採取對策，試列出 5 項有關「發生源」方面之對策。(10 分)", "ans": "", "sol": "(任選 5 項作答，中華民國工業安全衛生協會教材)\n1.以低毒性、低危害性物料取代。\n2.作業方法、作業程序之變更。\n3.製程之隔離，包括時間與空間。\n4.製程之密閉。\n5.濕式作業。\n6.局部排氣裝置之設置。\n7.控制設備之良好維護保養計畫，維持有效控制能力。"},
{"id": "sk-cc-75-10", "topic": "第 75 次（104.7.19）", "code": "75-10", "n": 75, "q": "某一戶外燒窯作業，在有日曬工作環境中，測得乾球溫度 31℃、自然濕球溫度 28℃、黑球溫度為 34℃，請回答下列問題：\n(一)該環境之綜合溫度熱指數為幾℃？(請列出計算公式)(8 分)\n(二)依您計算結果並依下表所定，如勞工作業為中度工作，則該勞工每小時休息比例應為多少%？(2 分)", "ans": "", "sol": "(一)戶外有日曬時\nWBGT=0.7×Tnwb＋0.2×Tgb＋0.1Tdb=0.7×28＋0.2×34＋0.1×31=29.5℃\n(二)因時量平均綜合溫度熱指數值℃(WBGT)TWA=29.5℃＞29.4℃，所以該勞工每小時休息比例應為 50%休息、50%作業。", "fig": "| 時量平均綜合溫度熱指數值℃ | 連續作業 | 25%休息／75%作業 | 50%休息／50%作業 | 75%休息／25%作業 |\n| --- | --- | --- | --- | --- |\n| 輕工作 | 30.6 | 31.4 | 32.2 | 33.0 |\n| 中度工作 | 28.0 | 29.4 | 31.1 | 32.6 |\n| 重工作 | 25.9 | 27.9 | 30.0 | 32.1 |\n時間比例：每小時作息。"},
{"id": "sk-cc-76-01", "topic": "第 76 次（104.11.8）", "code": "76-01", "n": 76, "q": "(一)依職業安全衛生法規定，請列出必須有勞工代表會同參與之事項。(4分)\n(二)上述之勞工代表產生方式為何？(6 分)", "ans": "", "sol": "(一)1.依職業安全衛生法第 34 條：安全衛生工作守則訂定時。\n2.依職業安全衛生法第 37 條：事業單位工作場所發生職災害時。\n(二)依職業安全衛生法施行細則第 43 條：\n1.事業單位設有工會者，由工會推派之。\n2.無工會組織而有勞資會議者，由勞方代表推選之。\n3.無工會組織且無勞資會議者，由勞工共同推選之。"},
{"id": "sk-cc-76-02", "topic": "第 76 次（104.11.8）", "code": "76-02", "n": 76, "q": "請針對職業安全衛生法有關承攬之規定，回答下列問題：\n(一)原事業單位應與承攬人負那 2 種連帶責任？(4 分)\n(二)請列舉 3 項事業單位與承攬人、再承攬人分別僱用勞工共同作業時，原事業單位應採取之必要措施。(6 分)", "ans": "", "sol": "(一)依職業安全衛生法第 25 條：\n1.職業災害補償。\n2.職業災害賠償。\n(二)依職業安全衛生法第 27 條：(以下任選 3 項作答)\n1.設置協議組織，並指定工作場所負責人，擔任指揮及協調之工作。\n2.工作之連繫與調整。\n3.工作場所之巡視。\n4.相關承攬事業間之安全衛生教育之指導及協助。"},
{"id": "sk-cc-76-03", "topic": "第 76 次（104.11.8）", "code": "76-03", "n": 76, "q": "某勞工達 250 人之金屬製造業，依職業安全衛生管理辦法規定，設置安全衛生組織及人員。請回答下列問題：\n(一)管理單位之層級為何？(4 分)\n(二)應置管理人員之種類及人數為何？(6 分)", "ans": "", "sol": "(一)專責一級。\n(二)1.甲種職業安全衛生業務主管一人。\n2.職業安全衛生管理員一人。\n3.該金屬製造業所屬從事製造之一級單位，勞工人數在 100 人以上應另置甲種職業安全衛生業務主管一人。"},
{"id": "sk-cc-76-04", "topic": "第 76 次（104.11.8）", "code": "76-04", "n": 76, "q": "某工廠有勞工 800 人，於製程中使用之化學品包括硫酸、三氯乙烯、硝酸、丙酮、鹽酸等。依勞工作業環境監測實施辦法規定，請回答下列問題：\n(一)監測計畫應由那些人員組成監測評估小組研訂之？(請列舉2種人員，4分)\n(二)監測評估小組研訂監測計畫後，應共同簽名及作成紀錄，並保存多少年？(2分)\n(三)該工廠所使用那 2 種化學品之監測結果應保存 30 年？(4 分)", "ans": "", "sol": "(一)依勞工作業環境監測實施辦法 10-2 條：(以下任選 2 種人員作答)\n1.工作場所負責人。\n2.依法設置之職業安全衛生人員。\n3.受委託之執業工礦衛生技師。\n4.工作場所作業主管。\n(二)3 年\n(三)1.硫酸\n2.三氯乙烯"},
{"id": "sk-cc-76-05", "topic": "第 76 次（104.11.8）", "code": "76-05", "n": 76, "q": "某工廠研發時，需自行輸入中央主管機關公告之化學物質清單以外之新化學物質，依職業安全衛生法規定，請回答下列問題：\n(一)自行輸入新化學物質時，除繳交化學物質安全評估報告外，並需取得何種文件才能輸入？(2 分)\n(二)中央主管機關審查化學物質安全評估報告後，得予公開那些資訊？(請列舉 4 項，8 分)", "ans": "", "sol": "(一)依職業安全衛生法第 13 條：新化學物質登記許可文件。\n(二)依職業安全衛生法施行細則第 18 條：(以下任選 4 項作答)\n1.新化學物質編碼。\n2.危害分類及標示。\n3.物理及化學特性資訊。\n4.毒理資訊。\n5.安全使用資訊。\n6.為因應緊急措施或維護工作者安全健康，有必要揭露予特定人員之資訊。"},
{"id": "sk-cc-76-06", "topic": "第 76 次（104.11.8）", "code": "76-06", "n": 76, "q": "依營造安全衛生設施標準規定，試回答下列問題：\n(一)雇主使勞工從事何種屋頂作業時，應指派屋頂作業主管於現場作業？(2分)\n(二)該屋頂作業主管應辦理那些事項？(請列舉 4 項，8 分)", "ans": "", "sol": "營造安全衛生設施標準第 18 條：\n(一)易踏穿材料構築屋頂。\n(二)1.決定作業方法，指揮勞工作業。\n2.實施檢點，檢查材料、工具、器具等，並汰換不良品。\n3.監督勞工確實使用個人防護具。\n4.確認安全衛生設備及措施之有效狀況。"},
{"id": "sk-cc-76-07", "topic": "第 76 次（104.11.8）", "code": "76-07", "n": 76, "q": "依職業安全衛生設施規則規定，雇主使勞工於局限空間從事作業前，如有引起勞工缺氧、中毒等相關危害之虞者，應訂定危害防止計畫，並使現場作業主管、監視人員、作業勞工及相關承攬人依循辦理，該計畫應包含那些事項？(請列舉 5 項，10 分)", "ans": "", "sol": "依職業安全衛生設施規則第 29-1 條：(以下任選 5 項作答)\n1.局限空間內危害之確認。\n2.局限空間內氧氣、危險物、有害物濃度之測定。\n3.通風換氣實施方式。\n4.電能、高溫、低溫及危害物質之隔離措施及缺氧、中毒、感電、塌陷、被夾、被捲等危害防止措施。\n5.作業方法及安全管制作法。\n6.進入作業許可程序。\n7.提供之防護設備之檢點及維護方法。\n8.作業控制設施及作業安全檢點方法。\n9.緊急應變處置措施。"},
{"id": "sk-cc-76-08", "topic": "第 76 次（104.11.8）", "code": "76-08", "n": 76, "q": "依職業安全衛生法規定，有些工作屬於A.雇主不得使妊娠中之女性勞工從事，但分娩後即可從事；B.雇主不得使分娩後未滿 1 年之女性勞工從事；\nC.雇主不得使未滿 18 歲勞工從事，但妊娠中及分娩後未滿 1 年之女性勞工可從事。下列各工作分別屬於上述何者？請依序回答。(本題各小項均為單選，答題方式如\n(一)A、\n(二)B_{……})。(10 分)\n(一)處理德國麻疹之工作。\n(二)鍋爐之燒火及操作。\n(三)處理易燃性物質之工作。\n(四)礦坑工作。\n(五)異常氣壓之工作。", "ans": "", "sol": "(一) A\n(二) C\n(三) C\n(四) B\n(五) A"},
{"id": "sk-cc-76-09", "topic": "第 76 次（104.11.8）", "code": "76-09", "n": 76, "q": "依職業安全衛生設施規則規定，下列敘述分別屬於A.固定梯子或B.合梯之要求？請依序回答。(本題各小項均為單選，答題方式如\n(一)A，\n(二)B_{……})。\n(10 分)\n(一)雇主不得使勞工以此梯當作二工作面之上下設備。\n(二)不得有妨礙工作人員通行之障礙物。\n(三)應有防止梯子移位之措施。\n(四)腳部有防滑絕緣腳座套。\n(五)踏條與牆壁間應保持 16.5 公分以上之淨距。", "ans": "", "sol": "(一) B\n(二) A\n(三) A\n(四) B\n(五) A"},
{"id": "sk-cc-76-10", "topic": "第 76 次（104.11.8）", "code": "76-10", "n": 76, "q": "某事業單位進行職場健康促進活動，其中勞工 A 身高 170 公分，體重 65公斤。勞工 B 身高 160 公分，體重 62 公斤。\n(一)請計算此 2 位勞工之身體質量指數(BMI)。(8 分:應列出計算過程)\n(二)BMI 正常範圍在 18.5 至 24 之間。請問有那位勞工需進行肥胖及體重控制？(2 分)", "ans": "", "sol": "(一)身體質量指數(BMI)＝體重(公斤) / 身高(公尺)²\n1. 勞工A身體質量指數(BMI)＝65/1.7²＝22.49\n2. 勞工B身體質量指數(BMI)＝62/1.6²＝24.22\n(二) 勞工 B。"},
{"id": "sk-cc-77-01", "topic": "第 77 次（105.3.20）", "code": "77-01", "n": 77, "q": "依職業安全衛生法規定，雇主應會同勞工代表訂定適合其需要之安全衛生工作守則，試回答下列問題：\n(一)請列舉 4 項安全衛生工作守則內容之事項。(8 分)\n(二)事業單位訂定之安全衛生工作守則其適用區域跨二以上勞動檢查機構轄區時，應如何處理報備事宜？(2 分)", "ans": "", "sol": "(一)安全衛生工作守則之內容，依下列事項定之：(細則 41 條，以下任選 4 項)\n1、事業之安全衛生管理及各級之權責。\n2、機械、設備或器具之維護及檢查。\n3、工作安全及衛生標準。\n4、教育及訓練。\n5、健康指導及管理措施。\n6、急救及搶救。\n7、防護設備之準備、維持及使用。\n8、事故通報及報告。\n(二) 如其適用區域二以上檢查機構轄區時，應報請中央主管機關指定之勞動檢查機構備查。(細則第 42 條)", "old": 1},
{"id": "sk-cc-77-02", "topic": "第 77 次（105.3.20）", "code": "77-02", "n": 77, "q": "請列舉 5 項職業安全衛生管理計畫內容之事項。(10 分)", "ans": "", "sol": "職業安全衛生管理計畫，包括下列事項：(細則 31 條，以下任選 5 項)\n1、工作環境或作業危害之辨識、評估及控制。\n2、機械、設備或器具之管理。\n3、危害性化學品之分類、標示、通識及管理。\n4、有害作業環境之採樣策略規劃及監測。\n5、危險性工作場所之製程或施工安全評估。\n6、採購管理、承攬管理及變更管理。\n7、安全衛生作業標準。\n8、定期檢查、重點檢查、作業檢點及現場巡視。\n9、安全衛生教育訓練。\n10、個人防護具之管理。\n11、健康檢查、管理及促進。\n12、安全衛生資訊之蒐集、分享及運用。\n13、緊急應變措施。\n14、職業災害、虛驚事故、影響身心健康事件之調查處理及統計分析。\n15、安全衛生管理紀錄及績效評估措施。"},
{"id": "sk-cc-77-03", "topic": "第 77 次（105.3.20）", "code": "77-03", "n": 77, "q": "(一)某營造廠工地設置吊升荷重 4 公噸之固定式起重機 1 座，雇主應依規定實施定期檢查，除檢查年月日外，請另列舉 3 項定期檢查應記錄之事項。(6 分)\n(二)上述固定式起重機，設置完成後\n(1)應向所在地何種機構申請竣工檢查？(2 分)\n(2)往後應向何種中央主管機關所指定之機構申請定期檢查？(2 分)", "ans": "", "sol": "(一)危險性機械之定期檢查應就下列事項記錄(管理辦法第80條，以下2~6任選3項)\n1、檢查年月日。\n2、檢查方法。\n3、檢查部分。\n4、檢查結果。\n5、實施檢查者之姓名。\n6、依檢查結果應採取改善措施之內容。\n(二)\n1、勞動檢查機構。\n2、危險性機械之代行檢查機構。", "old": 1},
{"id": "sk-cc-77-04", "topic": "第 77 次（105.3.20）", "code": "77-04", "n": 77, "q": "食品公司實施作業危害之辨識及評估，發現某項作業屬該公司高風險作業，欲使用表格方式製作該作業之安全作業標準。請問此安全作業標準(除標題欄及圖示外)之主要內容一般包含那 5 項？(10 分)", "ans": "", "sol": "1、確認實際工作步驟。\n2、研擬工作方法。\n3、辨識不安全因素。\n4、擬定安全措施。\n5、規劃事故之處理。"},
{"id": "sk-cc-77-05", "topic": "第 77 次（105.3.20）", "code": "77-05", "n": 77, "q": "某橋樑引道及地震傾倒建物拆除，如果你是該等工程施工廠商之職業安全衛生管理員，依營造安全衛生設施標準，在拆除該構造物前，應協助雇主辦理那些規定事項，以確保工程順利完成？(至少列出 5 項，10 分)", "ans": "", "sol": "雇主於拆除構造物前，應依下列規定辦理：(營造安全衛生設施標準第 155條，以下任選 5 項)\n1、檢查預定拆除之各構件。\n2、對不穩定部分，應予支撐穩固。\n3、切斷電源，並拆除配電設備及線路。\n4、切斷可燃性氣體管、蒸汽管或水管等管線。管中殘存可燃性氣體時，應打開全部門窗，將氣體安全釋放。\n5、拆除作業中須保留之電線管、可燃性氣體管、蒸氣管、水管等管線，其使用應採取特別安全措施。\n6、具有危險性之拆除作業區，應設置圍柵或標示，禁止非作業人員進入拆除範圍內。\n7、在鄰近通道之人員保護設施完成前，不得進行拆除工程。"},
{"id": "sk-cc-77-06", "topic": "第 77 次（105.3.20）", "code": "77-06", "n": 77, "q": "某金屬加工製造工廠，勞工需從事(－)高架作業、\n(二)重體力勞動作案，請說明從事上述作業或減少或縮短工作時間之規定。(10 分)", "ans": "", "sol": "(一)雇主使勞工從事高架作業時，應減少工作時間，每連續作業二小時，應給予作業勞工下列休息時間：(高架作業勞工保護措施標準第 4 條)\n1.度在二公尺以上未滿五公尺者，至少有二十分鐘休息。\n2.在五公尺以上未滿二十公尺者，至少有二十五分鐘休息。\n3.在二十公尺以上者，至少有三十五分鐘休息。\n(二)雇主使勞工從事重體力勞動作業時，應考慮勞工之體能負荷情形，減少工作時間給予充分休息，休息時間每小時不得少於二十分鐘。(重體力勞動作業勞工保護措施標準第 3 條)"},
{"id": "sk-cc-77-07", "topic": "第 77 次（105.3.20）", "code": "77-07", "n": 77, "q": "某事業單位規劃歲修保養作業，諸依下述主題，說明停電作業之安全措施：\n(一)標示管理。(2 分)\n(二)殘留電荷。(2 分)\n(三)接地管理。(3 分)\n(四)變電設備有電/停電標誌之警示區分。(3 分)", "ans": "", "sol": "(業安全衛生設施規則第 254 條)\n1.路之開關於作業中，應上鎖或標示「禁止送電」、「停電作業中」或設置監視人員監視之。\n2.後之電路如含有電力電纜、電力電容器等致電路有殘留電荷引起危害之虞，應以安全方法確實放電。\n3.後之電路藉放電消除殘留電荷後，應以檢電器具檢查，確認其已停電，且為防止該停電電路與其他電路之混觸、或因其他電路之感應、或其他電源之逆送電引起感電之危害，應使用短路接地器具確實短路，並加接地。\n4.停電作業範圍如為發電或變電設備或開關場之一部分時，應將該停電作業範圍以藍帶或網加圍，並懸掛「停電作業區」標誌；有電部分則以紅帶或網加圍，並懸掛「有電危險區」標誌，以資警示。"},
{"id": "sk-cc-77-08", "topic": "第 77 次（105.3.20）", "code": "77-08", "n": 77, "q": "依職業安全衛生設施規則規定，雇主供給勞工使用之呼吸防護具，其選擇與使用應依國家標準 CNS 14258 23035 辦理。請回答在下表所列條件時，是否可使用列舉之呼吸防護具，可使用者請答○，不可使用者請答 X。(答題方式：\n(一)○、\n(二)○...，(10 分)", "ans": "", "sol": "(一) O\n(二) X\n(三) O\n(四) X\n(五) O", "fig": "呼吸式防護具功能分類：無動力淨氣式呼吸防護具（防塵面具、防毒面具）；供氣式呼吸防護具（正壓壓縮空氣開放式自攜呼吸器）。\n| 作業環境污染危害型態與程度 | 防塵面具 | 防毒面具 | 正壓壓縮空氣開放式自攜呼吸器 |\n| --- | --- | --- | --- |\n| 氧含量高於18%，粒狀污染物濃度不致立即對生命健康造成危害 | (一) | (二) | (三) |\n| 氧含量不明或低於18%，且有害物濃度不明或可能立即對生命健康造成危害 | (四) | （與左欄合併） | (五) |"},
{"id": "sk-cc-77-09", "topic": "第 77 次（105.3.20）", "code": "77-09", "n": 77, "q": "防止物理性、化學性或生物性有害物之方法，可從 A：發生源、B：傳播途徑及 C：暴露者等 3 方面著手。請問下列各方法分屬上述何者？請依序回答。\n(本題各小項均為單選，答題方式如\n(一)A、\n(二)B.....，10 分)\n(一)使用生物安全櫃。\n(二)使用空氣簾幕以保護工作者。\n(三)自動監測裝置。\n(四)濕式作業。\n(五)除濕。\n(六)戴用個人劑量計。\n(七)整體換氣。\n(八)滅菌。\n(九)廠場整潔。\n(十)執行適當之個人防護具維護計畫。", "ans": "", "sol": "(一) A、\n(二) C、\n(三) B、\n(四) A、\n(五) B、\n(六) C、\n(七) B、\n(八) A、\n(九) B、\n(十) C"},
{"id": "sk-cc-77-10", "topic": "第 77 次（105.3.20）", "code": "77-10", "n": 77, "q": "某工作場所每勞工所佔空間(自地面算起高度超過 4 公尺以上之空間不計)為 30m³，以機械通風方式提供每位勞工 0.14m³/min之新鮮空氣。請計算每小時換氣次數。(請列出計算式，答案有效位數到小數點以下 2 位)。(10分)", "ans": "", "sol": "每一勞工所佔空間為 30m³，仍符合每分鐘每一勞工所需之新鮮空氣應在0.14 立方公尺以上之規定。(設施規則第 312 條)換算成每小時換氣量＝0.14m³/人、min × 60min ＝8.4 m³故以每一勞工所佔所佔空間為 30m³來計算，所以新鮮空氣換氣率為\n每小時至少應為 8.4 m³ ÷ 30m³＝0.28 次"},
{"id": "sk-cc-78-01", "topic": "第 78 次（105.7.17）", "code": "78-01", "n": 78, "q": "依職業安全衛生法規定，雇主應宣導該法有關安全衛生規定，使勞工周知。\n請列舉 5 種足使勞工周知之宣導方式。(10 分)", "ans": "", "sol": "(細則 40 條，以下任選 5 項)\n1、教育\n2、公告\n3、分發印刷品\n4、集會報告\n5、電子郵件\n6、網際網路"},
{"id": "sk-cc-78-02", "topic": "第 78 次（105.7.17）", "code": "78-02", "n": 78, "q": "A 電子零組件製造公司，其勞工人數及相關組織架構如下，請依職業安全衛生管理辦法規定，回答下列問題。(10 分)勞工總人數400人\n（一）職業安全衛生管理單位設置之性質及層級為何？(2 分)\n（二）職業安全衛生管理單位之職業安全衛生管理人員如何設置？(6 分)\n（三）製造一課應增加何種職業安全衛生管理人員？(2 分)", "ans": "", "sol": "A電子零組件製造公司為第一類事業單位，勞工人數＝400人＋120人＝520人\n（一）專責一級\n（二）甲種職業安全衛生業務主管 1 人、職業安全(或衛生)管理師 1 人、職業安全衛生管理員 2 人。\n（三）甲種職業安全衛生業務主管 1 人。", "fig": "組織圖：A電子公司（勞工總人數400人；派遣工120人〔受指揮監督〕） → 總務室／製造二課（勞工：250人；派遣工：60人）／製造一課（勞工：50人；派遣工：60人）／其他。"},
{"id": "sk-cc-78-03", "topic": "第 78 次（105.7.17）", "code": "78-03", "n": 78, "q": "某鐵工廠設置吊升荷重 3 公噸之固定式起重機 1 座，未經檢查合格，即行使用。某日雇主指示勞工操作，因鋼索斷裂致吊舉物掉落，撞擊該勞工致死，\n試問：\n（一）依職業安全衛生法所定罰則，發生此種職業災害，得對公司負責人處何種刑事處分？(6 分)\n(二) 發生事故之固定式起重機吊掛作業場所經勞動檢查機構予以停工處分，雇主乃繼續使用該起重機從事吊掛作業，除處罰其負責人外，並對公司法人處以何種處分？(2 分)\n（三）雇主應申請何種檢查合格後使可使用？(2 分)", "ans": "", "sol": "(一) 處三年以下有期徒刑、拘役或科或併科新臺幣三十萬元以下罰金。\n(二) 處新臺幣十八萬元以下罰金。\n（三）定期檢查。", "old": 1},
{"id": "sk-cc-78-04", "topic": "第 78 次（105.7.17）", "code": "78-04", "n": 78, "q": "依職業安全衛生法規定，回答下列問題：？(10 分)\n（一）事業單位勞動場所發生何種職業災害時，雇主應於 8 小時內通報勞動檢查機構？請寫出 3 種職業災害(「其他經中央主管機關指定公告之災害」除外，寫出不計分。(6 分)\n（二）勞動檢查機構接獲通報後，應就工作場所發生之那 2 種災害派員檢查？\n(4 分)", "ans": "", "sol": "(職業安全衛生法第 37 條)\n（一）\n1、發生死亡災害。\n2、發生災害之罹災人數在三人以上。\n3、發生災害之罹災人數在一人以上，且需住院治療。\n（二）\n1、死亡。\n2、重傷之災害。", "old": 1},
{"id": "sk-cc-78-05", "topic": "第 78 次（105.7.17）", "code": "78-05", "n": 78, "q": "依營造安全衛生設施標準規定，雇主對於何種施工架及工作臺之構築及拆除，應事先就預期施工時之最大荷重，依結構力學原理妥為設計，置備施工圖說，並指派所僱之專任工程人員簽章確認強度計算書及施工圖說？(10分，請列舉 5 種)", "ans": "", "sol": "(依營造安全衛生設施標準第 40 條，以下任選 5 種)\n1、懸吊式施工架\n2、懸臂式施工架\n3、高度五公尺以上施工架\n4、高度五公尺以上之吊料平臺\n5、升降機直井工作臺\n6、鋼構橋橋面板下方工作臺或其他類似工作臺"},
{"id": "sk-cc-78-06", "topic": "第 78 次（105.7.17）", "code": "78-06", "n": 78, "q": "依職業安全衛生設施規則規定，雇主對於有車輛出入易導致交通事故之虞之工作場所，應採取安全措施，請回答下列問題。\n（一）已完工道路於通車前應設置那些措施？(6 分)\n（二）使用於夜間之柵欄，應設置那些措施？(2 分)\n（三）若所設置之措施，尚不足以防止交通事故，應如何再強化，以避免事故發生？(2 分)", "ans": "", "sol": "(依職業安全衛生設施規則第 21-1 條規定)\n(一) 應設置適當的：\n1、交通號誌\n2、標示\n3、柵欄\n(二) 應設有照明或反光片等設施。\n（三）應置交通引導人員。"},
{"id": "sk-cc-78-07", "topic": "第 78 次（105.7.17）", "code": "78-07", "n": 78, "q": "雇主對於那些勞工，應使其接受特殊作業安全衛生教育訓練？(10 分，請列舉 5 種)", "ans": "", "sol": "(職業安全衛生教育訓練規則第 14 條，以下任選 5 種)\n1、小型鍋爐操作人員。\n2、荷重在一公噸以上之堆高機操作人員。\n3、吊升荷重在零點五公噸以上未滿三公噸之固定式起重機操作人員或吊升荷重未滿一公噸之斯達卡式起重機操作人員。\n4、吊升荷重在零點五公噸以上未滿三公噸之移動式起重機操作人員。\n5、吊升荷重在零點五公噸以上未滿三公噸之人字臂起重桿操作人員。\n6、使用起重機具從事吊掛作業人員。\n7、以乙炔熔接裝置或氣體集合熔接裝置從事金屬之熔接、切斷或加熱作業人員。\n8、火藥爆破作業人員。\n9、胸高直徑七十公分以上之伐木作業人員。\n10、機械集材運材作業人員。\n11、高壓室內作業人員。\n12、潛水作業人員。\n13、油輪清艙作業人員。"},
{"id": "sk-cc-78-08", "topic": "第 78 次（105.7.17）", "code": "78-08", "n": 78, "q": "職業災害原因可分為 A：直接原因、B：間接原因、C：基本原因。請問下列原因分屬上述何者？請依序回答。 (本題各小項均為單選，答題方式如\n(一)A、\n(二)A……，10 分)\n（一）自動檢查未確實。\n（二）鋼構上墜落致死。\n（三）未於高架鋼樑作業處設置防墜設備。\n（四）未採取協議連繫調整巡視等承攬管理。\n（五）未實施勞工安全衛生教育訓練。", "ans": "", "sol": "(一) C\n(二) A\n(三) B\n(四) C\n(五) C", "old": 1},
{"id": "sk-cc-78-09", "topic": "第 78 次（105.7.17）", "code": "78-09", "n": 78, "q": "以下項目\n(一)至\n(十)，請列出與右列項目 A 至 J 相關性最大者。(本題各小項均為單選，答題方式如\n(一)A…\n(二)B……，10 分，複選不計分)", "ans": "", "sol": "(一) C\n(二) D\n(三) I\n(四) J\n(五) A\n(六) B\n(七) F\n(八) H\n(九) G\n(十) E", "fig": "| 項目 | 右列項目 |\n| --- | --- |\n| (一)凍傷 | A X光 |\n| (二)振動 | B 電磁波 |\n| (三)綜合溫度熱指數 | C 低溫作業 |\n| (四)異常氣壓 | D 白指病 |\n| (五)游離輻射 | E 輻射熱 |\n| (六)非游離輻射 | F 聽力損失 |\n| (七)噪音 | G 空氣溫度 |\n| (八)米燭光 | H 照度 |\n| (九)乾球溫度 | I 高溫作業 |\n| (十)黑球溫度 | J 潛水夫病 |"},
{"id": "sk-cc-78-10", "topic": "第 78 次（105.7.17）", "code": "78-10", "n": 78, "q": "下列為穀粉作業環境監測資料：採樣時溫度 25°C，氣壓 760mmHg，採樣流速 2L/min，計採 8 小時，實驗室分析其粉塵重量為 19.2mg，其 8 小時日時量平均容許濃度(PEL)＝10mg/m³。\n（一）全程工作日時量平均濃度為多少mg/m³？(8 分)\n（二）請說明是否超過 8 小時日時量平均容許濃度？(2 分)", "ans": "", "sol": "於 25°C，氣壓 760mmHg實施八小時單一樣本連續採樣，共採樣：\n2L/min × 60min × 8＝960L＝0.96m³\n（一）全程工作日時量平均濃度＝19.2mg ÷ 0.96m³＝20mg/m³\n（二）超過 8 小時日時量平均容許濃度(PEL)＝10mg/m³。"},
{"id": "sk-cc-79-01", "topic": "第 79 次（105.11.6）", "code": "79-01", "n": 79, "q": "請依職業安全衛生法令及勞動檢查法令說明下列名詞：\n（一）勞動場所(6 分)\n（二）職業災害嚴重度(2 分)\n（三）職業災害傷害頻率(2 分)", "ans": "", "sol": "（一）勞動場所：(職業安全衛生法施行細則第 5 條)\n1、於勞動契約存續中，由雇主所提示，使勞工履行契約提供勞務之場所。\n2、自營作業者實際從事勞動之場所。\n3、其他受工作場所負責人指揮或監督從事勞動之人員，實際從事勞動之場所。\n（二）職業災害嚴重度：(勞動檢查法施行細則第 6 條)每百萬工時之失能傷害總損失日數。\n或(失能傷害嚴重率(SR)＝失能傷害總損失日數×1,000,000/總歷經工時)\n（三）職業災害傷害頻率：(勞動檢查法施行細則第 6 條)每百萬工時之失能傷害次數。\n或(失能傷害頻率(FR)＝失能傷害人次數×1,000,000/總歷經工時）"},
{"id": "sk-cc-79-02", "topic": "第 79 次（105.11.6）", "code": "79-02", "n": 79, "q": "某工廠勞工 580 人，某日於其工作場所發生勞工遭堆高機翻覆壓傷致死之職業災害，請回答下列問題：\n(－)如您是該事業單位之職業安全衛生管理員，要協助雇主辦理職業安全 衛生法規定之後續處理事項為何？(請列舉 3 項，6 分)\n(二)依勞動基準法規定，雇主應給輿罹災勞工之遺屬幾個月平均工資之喪葬費？(2 分)以及幾個月平均工資之死亡補償？(2 分)", "ans": "", "sol": "：\n(一)協助雇主辦理職安法規定之後續處理事項如下：(職安法第 37 條)\n1、應即採取必要之急救、搶救等措施，並會同勞工代表實施調查、分析及作成紀錄。\n2、應於八小時內通報勞動檢查機構。\n3、除必要之急救、搶救外，非經司法機關或勞動檢查機構許可，不得移動或破壞現場。\n(二) (勞基法第 59 條)\n1、5 個月。\n2、40 個月。", "old": 1},
{"id": "sk-cc-79-03", "topic": "第 79 次（105.11.6）", "code": "79-03", "n": 79, "q": "某公司之生產線係採輪班工作型態，為避免勞工因異常工作負荷促發疾病，請依職業安全衛生設施規則規定回答下列問題：\n(一)列舉 3 項雇主應採取之疾病預防措施。(6 分)\n(二)上述預防措施之執行記錄應保存幾年？(2 分)\n(三)該公司如依規定應配置醫護人員從事勞工健康服務，應參照中央主管機關公告之相關指引，訂定何種計畫？(2 分)", "ans": "", "sol": "(一)雇主應採取下列疾病預防措施：(設施規則第 324-2 條，任選 3 項作答)\n1、辨識及評估高風險群。\n2、安排醫師面談及健康指導。\n3、調整或縮短工作時間及更換工作內容之措施。\n4、實施健康檢查、管理及促進。\n5、執行成效之評估及改善。\n(二)執行紀錄應留存三年。\n(三)應訂定異常工作負荷促發疾病預防計畫。"},
{"id": "sk-cc-79-04", "topic": "第 79 次（105.11.6）", "code": "79-04", "n": 79, "q": "颱風過後某工廠廠房鐵皮板屋頂(裝有塑膠採光罩)損壞須要整修，此屋頂有踏穿墜落之虞，為防止勞工於屋頂作業時，因踏穿屋頂而發生墜落災害，雇主應在屋頂上方及下方分別設置那些安全設備？(10 分)", "ans": "", "sol": "(營造安全衛生設施標準第 18 條)\n(一)在屋頂上方，應先規劃安全通道，於屋架上設置適當強度，且寬度在三十公分以上之踏板。\n(二)在屋頂下方適當範圍裝設堅固格柵或安全網等防墜設施。"},
{"id": "sk-cc-79-05", "topic": "第 79 次（105.11.6）", "code": "79-05", "n": 79, "q": "某公司為實施緊急應變，編組緊急應變組織，除應變指揮官及應變指揮小組外，緊急應變組織可有那些編組？(列舉 5 項、10 分)", "ans": "", "sol": "1、通報組。\n2、滅火組。\n3、避難引導組。\n4、緊急救護組。\n5、安全防護組。"},
{"id": "sk-cc-79-06", "topic": "第 79 次（105.11.6）", "code": "79-06", "n": 79, "q": "某事業單位將清洗地下水池工作委由某－承攬人承做，承攬人所僱勞工發生職業災害。請回答下列問題：\n(一)該事業單位違反安全衛生規定，致發生此職業災害，應與承攬商負何種責任？(2 分)\n(二)該事業單位與該承攬商分別僱用勞工共同作業時，應採取那些必要措施？\n(請列舉 4 項，8 分)", "ans": "", "sol": "(一)連帶賠償責任。(職安法第 25 條第二項)\n(二)(職安法第 27 條第一項，)\n1、設置協議組織，並指定工作場所負責人，擔任指揮、監督及協調之工作。\n2、工作之連繫與調整。\n3、工作場所之巡視。\n4、相關承攬事業間之安全衛生教育之指導及協助。"},
{"id": "sk-cc-79-07", "topic": "第 79 次（105.11.6）", "code": "79-07", "n": 79, "q": "某工廠執行歲修作業(有低壓、高壓，特高壓等 3 種作業區)，某些作業區須停電，某些作業區仍為活電作業。請回答下列問題：\n(一)低壓、高壓、特高壓之電壓範圍分別為何？(3 分)\n(二)雇主對於高壓以上之停電作業、活線作業，除指定監督人員負資指揮外，應將那些資訊告知作業之勞工？(4 分)\n(三)針對此 3 種不同電壓之作業區，雇主如果沒有委託用電設備檢驗維護業，負責維護輿電業供電設備分界點以內－般及緊急電力設備之用電安全，應分別置那種技術人員？(3 分)", "ans": "", "sol": "(一) (設施規則第 3 條)低壓：六百伏特以下之電壓。\n高壓：超過六百伏特至二萬二千八百伏特之電壓。\n特高壓：超過二萬二千八百伏特之電壓。\n(二) (設施規則第 265 條)作業期間、作業內容、作業之電路及接近於此電路之其他電路系統。\n(三) (設施規則第 264 條)\n1、低壓供電之用電場所，應置初級電氣技術人員。\n2、高壓供電之用電場所，應置中級電氣技術人員。\n3、特高壓供電之用電場所，應置高級電氣技術人員。"},
{"id": "sk-cc-79-08", "topic": "第 79 次（105.11.6）", "code": "79-08", "n": 79, "q": "某廠房有－正常運作之吸氣導管，請回答下列問題：\n(一)此導管之全壓為正值或負值？(1 分)\n(二)請指出以下圖示可分別測得全壓、動壓或靜壓。(本題各項均為單選，答題方式如：A＝全壓、B＝動壓、C＝靜壓，9 分)", "ans": "", "sol": "(一)此吸氣導管之全壓為負值。\n(二)A＝靜壓、B＝動壓、C＝全壓\n註：運轉中之局部排氣系統內之動壓(PV)皆為正壓，全壓(PT)與靜壓(PS)在排氣機前為負壓，在排氣機後為正壓；靜壓、全壓與動壓測定示意圖如下：", "fig": "圖：三個壓力計連接於水平導管，氣流均向右（→）。A：壓力計一端連接管壁靜壓孔，另一端通大氣。B：壓力計一端連接朝向上游的彎管口，另一端連接管壁靜壓孔。C：壓力計一端連接朝向上游的彎管口，另一端通大氣。\n補充圖：(A)靜壓、(B)全壓、(C)動壓。\n各圖儀器標示「壓差計」。補充圖為U形壓差計：(A)靜壓SP，(B)全壓TP，(C)動壓VP。"},
{"id": "sk-cc-79-09", "topic": "第 79 次（105.11.6）", "code": "79-09", "n": 79, "q": "依危害性化學品標示及通識規則規定，裝有危害性化學品之容器，其標示內容除名稱外，其他 5 項內容分別為何？(10 分)", "ans": "", "sol": "（危害性化學品標示及通識規則第 5 條）\n1、危害成分。\n2、警示語。\n3、危害警告訊息。\n4、危害防範措施。\n5、製造者、輸入者或供應者之名稱、地址及電話。"},
{"id": "sk-cc-79-10", "topic": "第 79 次（105.11.6）", "code": "79-10", "n": 79, "q": "某勞工之噪音暴露經監測結果如下，請計算其噪音暴露劑量。(應列出計算式，10 分)08：00～10：00 穩定性噪音 95 分貝10：00～12：00 變動性噪音 D＝10%13：00～15：00 穩定性噪音 90 分貝\n15：00～17：00 變動性噪音 D＝20%", "ans": "", "sol": "因為T₁＝8/2^{(L_{A}-90)/5}＝8/2^{(95-90)/5}＝4，T₃＝8/2^{(L_{A}-90)/5}＝8/2^{(90-90)/5}＝8\n所以噪音暴露劑量 D＝ t_{l} / T₁ ＋ t₂ / T₂ ＋ t₃ / T₃ ＋ t₄ / T₄\n＝ 2/4 ＋ 10 % ＋ 2/8 ＋ 20%\n＝ 50% ＋ 10% ＋ 25% ＋ 20% ＝105%\n(上列暴露劑量和 105%＝1.05 大於 1，超出容許暴露劑量，不符合法令規定。)"},
{"id": "sk-cc-80-05", "topic": "第 80 次（106.3.19）", "code": "80-05", "n": 80, "q": "靜電之火花放電，使可燃性氣體、易燃液體蒸氣或粉塵發生火災爆炸，請列舉 5 種預防靜電災害之方法(10 分)", "ans": "", "sol": "1.接地及搭接：製程中因摩擦、感應或傳導等產生的靜電危害藉由接地及搭接將能量釋放。\n2.增加濕度：在高溼度環境中，可降低物質的表面電阻，增加電荷散逸速度，達成電荷蓄積程度降低。\n3.使用抗靜電材料：使用物質表面或體積電阻係數愈低的材料，即可避免物質蓄積過量的靜電，如棉、碳粉等。\n4.使用靜電消除器：利用高壓電將空氣電離產生帶電離子，可使帶靜電物體的電荷被中和達成蓄積電荷至最低。\n5.限制速度：對於易燃液體的輸送作業限制其流速以消除製程中潛在靜電的來源。"},
{"id": "sk-cc-81-04", "topic": "第 81 次（106.7.16）", "code": "81-04", "n": 81, "q": "事業單位為避免勞工因操作失誤而發生職業災害，應針對高風險作業製作安全作業標準，其製作程序可分成那5項？(10分)", "ans": "", "sol": "1.擬定工作安全分析計畫。\n2.決定要分析工作的名稱。\n3.將工作步驟分解。\n4.辨識出潛在的危險。\n5.決定安全的工作方法。"},
{"id": "sk-cc-81-09", "topic": "第 81 次（106.7.16）", "code": "81-09", "n": 81, "q": "依今年度健康職場認證推動方案，事業單位如欲取得健康啟動標章，其重點工作辦理情形中，健康需求評估為必辦類別。該方案中提供的評估及瞭解員工健康需求之方法為何？(請列出5項，10分)", "ans": "", "sol": "(依據衛福部 106 年度「健康職場認證」推動方案，以下任選 5 項作答)可利用下列方法評估、瞭解員工的健康需求：\n1、分析職業傷病發生情形。\n2、觀察員工作業方式。\n3、分析健康檢查結果。\n4、辦理活動後的意見回饋。\n5、問卷調查（如調查員工是否有職場壓力的問題、調查員工有興趣的健康議題）。\n6、訪談。\n7、勞工代表提出。\n8、員工信箱。"},
{"id": "sk-cc-82-06", "topic": "第 82 次（106.11.5）", "code": "82-06", "n": 82, "q": "工程施工者，應於施工規劃階段實施風險評估，對於不可接受之風險，則採取降低風險之控制措施，防止施工時，發生職業災害。請寫出5種降低風險之控制措施類型？(10分)", "ans": "", "sol": "1、消除。\n2、取代。\n3、工程控制。\n4、標示/警告/管理控制措施。\n5、個人防護具。"},
{"id": "sk-cc-82-07", "topic": "第 82 次（106.11.5）", "code": "82-07", "n": 82, "q": "火災爆炸危險區域劃分使用之電氣機械、器具與設備，應具有防爆性能構造，請列舉5種電氣設備防爆構造。(10分)", "ans": "", "sol": "(以下任選 5 種作答)\n1、耐壓型防爆構造\n2、正壓型防爆構造\n3、油入型防爆構造\n4、增加安全型防爆構造\n5、特殊型防爆構造\n6、本質安全型防爆構造\n7、填粉型防爆構造\n8、模鑄型防爆構造。"},
{"id": "sk-cc-82-08", "topic": "第 82 次（106.11.5）", "code": "82-08", "n": 82, "q": "以交流電焊機從事鋼質圓筒型儲槽(內徑3公尺)之製造，分別對電焊作業之感電危害、儲槽組裝作業之墜落危害，各提出3項防止對策。(10分)", "ans": "", "sol": "(一)\n1、交流電焊機應有自動電擊防止裝置。\n2、裝設漏電斷路器。\n3、使用電壓不得超過 24 伏特。\n(二)\n1、設置護欄、護蓋。\n2、張掛安全網。\n3、使勞工佩掛安全帶。"},
{"id": "sk-cc-82-09", "topic": "第 82 次（106.11.5）", "code": "82-09", "n": 82, "q": "勞工從事下列作業時，分別會引起下表所列何種危害？\n(一)局部振動；\n(二)高溫作業；\n(三)熔接作業；\n(四)高壓室內作業；\n(五)電腦輸入作業；\n(六)抽血作業；\n(七)鉛作業；\n(八)氯乙烯作業；\n(九)噴砂(石英砂)作業；\n(十)煉焦作業。(本題各小項均為單選，答題方式如\n(一)A…\n(二)B…，10分，複選不計分)", "ans": "", "sol": "（ 一 ） I（ 二 ） A（ 三 ） H（ 四 ） J（ 五 ） B（ 六 ） G（ 七 ） C（ 八 ） E（ 九 ） D（ 十 ） F", "fig": "|  |  |\n| --- | --- |\n| A | 熱痙攣 |\n| B | 腕道症候群 |\n| C | 貧血 |\n| D | 塵肺症 |\n| E | 肝癌 |\n| F | 肺癌 |\n| G | 針扎 |\n| H | 眼睛疼痛 |\n| I | 白指病 |\n| J | 減壓症 |"},
{"id": "sk-cc-83-09", "topic": "第 83 次（107.3.18）", "code": "83-09", "n": 83, "q": "在一般工作場所中，下列數值增加後，工作者安全衛生條件或該安全衛生設施之效能會變好或變差？(答題方式請依：\n(一)變好\n(二)變差…，10分)\n(一)口罩之粉塵穿透率。\n(二)口罩之防護係數。\n(三)口罩之密合度。\n(四)外裝式氣罩與有害物發生之距離。\n(五)通風導管之曲率半徑。\n(六)通風導管2條導管合流處之角度。\n(七)氣罩進入損失係數。\n(八)氣罩進入係數。\n(九)太子樓與地板之溫差。\n(十)生物安全櫃等級。", "ans": "", "sol": "（ 一 ） 變 差 （ 二 ） 變 好 （ 三 ） 變 好 （ 四 ） 變 差 （ 五 ） 變 差（ 六 ） 變 差 （ 七 ） 變 差 （ 八 ） 變 好 （ 九 ） 變 差 （ 十 ） 變 好\n【註：本題是觀念題】"},
{"id": "sk-cc-84-05", "topic": "第 84 次（107.7.15）", "code": "84-05", "n": 84, "q": "燃燒三要素包括A：可燃物、B：助燃物、C：引火源。請問下列火災爆炸預防措施分別控制上述何者？請依序回答。(本題各小項均為單選，答題方式如\n(一)A、\n(二)B…，10分)\n(一)嚴禁煙火。\n(二)設置防爆電器。\n(三)加氮封。\n(四)加強通風排氣。\n(五)減少紙箱儲存。", "ans": "", "sol": "（一）C 、\n（二）C、\n（三）B、\n（四）B、\n（五）A"},
{"id": "sk-cc-84-06", "topic": "第 84 次（107.7.15）", "code": "84-06", "n": 84, "q": "如下圖所示，工地之模板工人使用高度約1.6公尺之合梯，從事模板組立作業。請列舉5項圖示中有違反法規之不安全之狀況或行為。(10分)", "ans": "", "sol": "（以下任選 5 項作答）\n1、未戴安全帽\n2、不可站立於合梯的梯面\n3、兩梯腳間未有金屬等硬質繫材扣牢\n4、梯腳未有防滑絕緣腳座套\n5、開口處護蓋未蓋妥\n6、鋼筋尖端未彎曲向下\n7、工作場所未設置適當交通號誌、標示或柵欄\n【註：本題是觀念題】", "fig": "圖：模板工人一腳站在合梯頂面，另一腳跨向模板；工人未戴安全帽。合梯放在模板牆旁，兩梯腳間未見扣牢之金屬等硬質繫材，梯腳未見防滑絕緣腳座套。地面有向上突出的鋼筋（標示「鋼筋」），右側有未完全覆蓋的開口（標示「開口」）。"},
{"id": "sk-cc-84-08", "topic": "第 84 次（107.7.15）", "code": "84-08", "n": 84, "q": "職業病之認定為相當專業之過程。請說明於本國要被認定為職業病必須要滿足哪5項原則。(10分)", "ans": "", "sol": "1、勞工確實有病徵。\n2、必須曾暴露於存在有害因子之環境。\n3、發病期間與症狀及有害因子之暴露期間有時序之相關。\n4、病因不屬於非職業上之因素所引起。\n5、文獻上曾記載症狀與危害因子之關係。"},
{"id": "sk-cc-85-05", "topic": "第 85 次（107.11.4）", "code": "85-05", "n": 85, "q": "使可燃性氣體或易燃液體蒸氣發生火災爆炸，請列舉5種火源。(10分)", "ans": "", "sol": "(以下任選 5 種作答)\n1、電氣，\n2、吸煙，\n3、摩擦，\n4、過熱物料，\n5、熱表面，\n6、明火\n7、燃燒火花，\n8、切割與焊接，\n9、自然發火，\n10、暴露，\n11、縱火\n12、機械火花，\n13、熔融物質，\n14、化學變化\n15、靜電，\n16、閃電。\n【註：本題是一般常識題(送分題)】"},
{"id": "sk-cc-85-09", "topic": "第 85 次（107.11.4）", "code": "85-09", "n": 85, "q": "請列出以下氣罩型式排氣量之估計公式。(10分，單選，請以\n(一)A、\n(二)B…方式作答)\n(一)單一狹縫式\n(二)外裝型\n(三)有凸緣之外裝型\n(四)崗亭式\n(五)懸吊式各公式的代號：v為捕捉點風速；X為氣罩開口與捕捉點距離，A為氣罩開口面積，P為作業面周長，L為氣罩開口長邊邊長。", "ans": "", "sol": "（一）D\n（二）F\n（三）A\n（四）G\n（五）B\n【註：本題解題感謝湯士弘老師協助】", "fig": "|  |  |\n| --- | --- |\n| A | 0.75v(10X²＋A) |\n| B | 1.4PvX |\n| C | 2.6LvX |\n| D | 3.7LvX |\n| E | v(5X²＋A) |\n| F | v(10X²＋A) |\n| G | vA |"},
{"id": "sk-cc-87-04", "topic": "第 87 次（108.7.14）", "code": "87-04", "n": 87, "q": "安全作業標準可用表格方式表示，4欄式或5欄式(事故處理除外)應包含那4個要項？(10分)", "ans": "", "sol": "1、確認實際工作步驟。\n2、研擬工作方法。\n3、辨識不安全因素。\n4、擬定安全措施。"},
{"id": "sk-cc-88-06", "topic": "第 88 次（108.11.3）", "code": "88-06", "n": 88, "q": "如圖所示，某工廠為了整修柴油槽，使1名勞工在槽頂從事人孔電焊作業，現場負責人於施工前辨識出此作業有感電的危害。試問：\n(一)針對此感電的危害，提出3種預防感電之安全衛生設施？(6分)\n(二)除感電的危害之外，還有那2個安全主要危害？(4分)(注意：答案只取題目要求之答案數目評分，後面多寫的均不計分)", "ans": "", "sol": "（一）1.交流電焊機應加裝自動電擊防止裝置\n2.交流電焊機應裝置漏電斷路器\n3.交流電焊機電極帶電部分應有防止感電之絕緣被覆\n(二) 1.高處作業無護欄、安全網設置會有墜落危害。\n2.在柴油槽從事電焊作業會有火災爆炸的危害。", "fig": "圖：一名勞工在直立圓筒形柴油槽頂部的人孔旁從事電焊，槽頂邊緣未見護欄。槽左側地面設有「電焊機」，電纜通往槽頂，另標示「接地電纜」；槽右側地面有容器。"},
{"id": "sk-cc-89-08", "topic": "第 89 次（109.3.15）", "code": "89-08", "n": 89, "q": "下列各情境，何者可使用整體換氣即可(A)，何者應使用局部排氣(B)？請依序作答。(10分，本題各小項均為單選，答題方式如：(1)A、(2)B……)\n(1)工作場所的區域大，不是隔離的空間。\n(2)在一隔離的工作場所或有限的工作範圍。\n(3)有害物的毒性高或為放射性物質。\n(4)有害物產生量少且毒性相當低，允許其散布在作業環境空氣中。\n(5)有害物發生源分布區域大，且不易設置氣罩時。\n(6)有害物進入空氣中的速率快，且無規律。\n(7)有害物進入空氣中的速率相當慢，且較有規律。\n(8)含有害物的空氣產生量不超過通風用空氣量。\n(9)產生大量有害物的工作場所。\n(10)工作者與有害物發生源距離足夠遠，使得工作者暴露濃度不致超過容許濃度標準。", "ans": "", "sol": "(1)A、(2)B、(3)B、(4)A、(5)A、(6)B、(7)A、(8)A、(9)B、(10)A。\n【註：本題屬通風換氣一般常識】"},
{"id": "sk-cc-89-09", "topic": "第 89 次（109.3.15）", "code": "89-09", "n": 89, "q": "(一)檢修電氣設備前應先停止送電，要確認是否已切斷電源，可使用那些安全衛生測定儀器？(4分，列舉2種)\n(二)從事局限空間作業應置備測定儀器，最常使用四用氣體偵測器，此四用氣體偵測器可偵測那4種氣體？(6分，列舉3種)", "ans": "", "sol": "(一)1.驗電筆、2.三用電表。\n(二)1.氧氣(O₂)、2.一氧化碳(CO)、3.硫化氫(H₂S)、4.可燃性氣體(LEL)\n【註：本題屬安全衛生儀器的一般常識】"},
{"id": "sk-cc-90-09", "topic": "第 90 次（109.7.12）", "code": "90-09", "n": 90, "q": "噪音造成的聽力損失及引起身體器官或系統的失調或異常等危害， 試列舉5項噪音危害預防之「工程控制」方法。(10分)", "ans": "", "sol": "(1)隔離噪音發生源。\n(2)密閉噪音發生源。\n(3)使用吸音材料降低機械所發生的噪音。\n(4)振動隔離。\n(5)利用消音方式。\n(6)利用慣性塊方式。"},
];
